const numberFormatters=new Map();
function fmt(n,d=0){let formatter=numberFormatters.get(d);if(!formatter){formatter=new Intl.NumberFormat('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});numberFormatters.set(d,formatter);}return formatter.format(Number(n));}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chains=['清洁链','厨房链','环境链','个护 & 健康链'],brands=[...new Set(['海尔','创维','康佳','美的','苏泊尔',...sampleSpus.map(p=>p.brand)])],channels=['抖音','快手','视频号','京东','拼多多','天猫','跨境','线下'],depts=['产品部','项目部','品质部','研发部','采购部'],types=['自研立项','选品立项','自研上品','选品上品','产品迭代','研发创新','产品下市','自选','自研','品质整改','创新项目'];
const config={green:100,yellow:80,low:20,high:60,profit:10,delay:15,returnGrowth:5,inventory:1.2};
let quarter=3,projectStatus='all',projectPage=1,lifeIndex=0,lifeView='chain',matrixTab='B',invView='chain',modalData=[],modalHeaders=[],activeRisk=0,aiTab=0,lastFocus=null,toastTimer,activeSales=-1,salesView='brand';
// 六个位置仅是旧演示计算的模板；所有名称都取SPU主表，不生成新产品。
const names=Array.from({length:4},(_,chain)=>{const pool=sampleSpus.filter(p=>p.chain===chain);return Array.from({length:6},(_,i)=>pool[i%pool.length].name)});
const people=['林悦','周铭','陈嘉','许宁','刘畅','唐琪','王磊','沈舟'];
const baseSales=[{sku:96,sale:3200,target:3500,profit:14.2,annual:14000,ytd:9250},{sku:78,sale:2450,target:3000,profit:10.4,annual:12000,ytd:6850},{sku:64,sale:1850,target:2000,profit:13.1,annual:8000,ytd:5100},{sku:48,sale:1150,target:1500,profit:12,annual:6000,ytd:2900}];
function totalSales(){const a=sales();return{name:'公司整体',sku:a.reduce((s,x)=>s+x.sku,0),sale:a.reduce((s,x)=>s+x.sale,0),target:a.reduce((s,x)=>s+x.target,0),profit:a.reduce((s,x)=>s+x.sale*x.profit,0)/a.reduce((s,x)=>s+x.sale,0),annual:a.reduce((s,x)=>s+x.annual,0),ytd:a.reduce((s,x)=>s+x.ytd,0)}}
function status(v){return v>=config.green?'green':v>=config.yellow?'orange':'red'}
function badge(v,label){const c=status(v);return `<span class="tag ${c}">${label||fmt(v,1)+'%'}</span>`}
function traffic(s){return `<span class="tag ${s==='红灯'?'red':s==='黄灯'?'orange':'green'}">● ${s}</span>`}
function projects(){return sampleProjectRows()}
function productRows(isNew){return sampleProductRows(isNew)}
function category(p){return p.sales>=config.high?(p.profit>=config.profit?'A':'B'):(p.profit>=config.profit?'C':'D')}
function table(headers,rows,cls=''){return `<table class="${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}" class="empty">暂无符合条件的数据</td></tr>`}</tbody></table>`}
function titleProduct(p,{showBrand=true}={}){return `<div class="prodname">${riskThumbnail(p.name)}<div><strong>${p.name}</strong><small>${p.spuCode?'SPU码：'+esc(p.spuCode):'型号：'+esc(p.model||'—')}${showBrand?' · '+esc(p.brand):''}</small></div></div>`}
function spark(i=0){let points=Array.from({length:22},(_,k)=>`${k*10},${25-Math.sin(k*.8+i)*5-k*.5}`).join(' ');return `<svg class="spark" viewBox="0 0 210 32" preserveAspectRatio="none" aria-hidden="true"><polyline points="${points} 210,32 0,32" fill="#eef1ff" stroke="none"/><polyline points="${points}" fill="none" stroke="#8594ff" stroke-width="1.5"/></svg>`}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3200)}
function downloadCsv(headers,rows,name){const cell=x=>'"'+String(x??'').replace(/<[^>]*>/g,'').replace(/^[=+@-]/,"'" ).replace(/"/g,'""')+'"';const blob=new Blob(['\ufeff'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function openModal(title,body,drawer=false,sub=''){if($('#overlay').hidden)lastFocus=document.activeElement;$('#dialog').classList.toggle('drawer',drawer);$('#dialogtitle').textContent=title;$('#dialogsub').textContent=sub;$('#dialogbody').innerHTML=body;$('#dialogbody').scrollTop=0;$('#dialogactions').innerHTML='<button class="btn small" id="modalclose">关闭</button>';$('#overlay').hidden=false;document.body.style.overflow='hidden';$('#modalclose').onclick=closeModal;$('#close').focus()}
function closeModal(){$('#overlay').hidden=true;document.body.style.overflow='';lastFocus?.focus()}

const riskTitles=['高危品质风险榜','高危劣质店铺榜','高危亏损产品榜','库存风险榜','高危滞销产品榜','高危延期项目榜','高危退货恶化榜'];
function riskRows(k){if(k===0)return sampleQualityCatalog();if(k===5)return projects().filter(p=>p.delay>config.delay).sort((a,b)=>b.delay-a.delay).map(p=>({...p,value:p.delay+' 天',metric:p.delay,desc:p.stage}));return Array.from({length:8},(_,i)=>{const ci=(i+k)%4,p={id:i,name:k===1?brands[i%5]+['生活电器旗舰店','家电专营店'][i%2]:names[ci][i%6],model:['CL','KT','EN','HC'][ci]+'-'+(101+i),chain:ci,brand:brands[i%5],channel:channels[i%8],owner:people[i%8],metric:0};const f=snapshotFactor();const val=[((18.2-i*1.2)*f).toFixed(1)+'%',(3.2+i*.08+(1-f)*.25).toFixed(2)+' 分',((12.8-i*1.1)*f).toFixed(1)+' 万',Math.round((268-i*23)*f)+' 万',Math.round((156-i*13)*f)+' 万','',((28.6-i*2.1)*f).toFixed(1)+'%'][k];return{...p,...(k===1?{}:sampleSpuIdentity(ci,Math.floor(i/4),false)),value:val,metric:parseFloat(val),desc:[i===0?'平台处罚 · 一票置顶':'高退货 / 差评','违规扣分 / 流量下滑','当月毛利为负','库龄 >90 天且近30天无动销',i<4?'两季品 · 优先处置':'四季品 · 动销不足','','退货率环比增长'][k]}})}
function renderRisks(){$('#riskrail').innerHTML=riskTitles.map((t,k)=>{const rows=riskRows(k);return `<article class="riskcard"><div class="rhead"><h3><i class="riskbadge"></i>${t}</h3><button class="link" data-risk="${k}">全部 ${rows.length} ›</button></div><div class="riskfoot" style="margin:0 0 3px"><span>风险对象</span><span>${['差评率','店铺评分','月度亏损金额','库存总金额','滞销积压金额','延迟天数','退货率环比增长率'][k]}</span></div>${rows.slice(0,6).map((p,i)=>`<button class="riskline" data-riskitem="${k},${p.id}"><span class="rank ${i<3?'top':''}">${String(i+1).padStart(2,'0')}</span>${riskThumbnail(p.name,k===1)}<span class="rname" title="${esc(p.name)}">${p.name}</span><span class="rvalue">${p.value}</span></button>`).join('')}</article>`}).join('')}
function openRisk(k){activeRisk=k;let rows=riskRows(k);const labels=['差评率','店铺评分','月度亏损金额','库存总金额','滞销积压金额','延迟天数','退货率环比增长率'];openModal(riskTitles[k]+' · 完整榜单',`<div class="contextstrip"><span class="note">${['平台处罚优先，其余按综合风险排序','违规清店风险优先，评分辅助判断','月度亏损金额 > 3 万元','展示库存金额，榜单按呆滞金额及周转异常排序','近30天销售额 < 1 万元，积压 > 10 万元；两季品优先','延迟天数 > '+config.delay+' 天','近30天销售额 ≥ 5 万元，环比增长率 > '+config.returnGrowth+'%'][k]}</span><select id="risksort" aria-label="风险排序"><option value="default">默认风险排序</option><option value="desc">${labels[k]}从高到低</option><option value="asc">${labels[k]}从低到高</option></select></div><div id="riskfull" class="tablewrap"></div>`);function fill(order){let a=[...rows];if(order!=='default')a.sort((a,b)=>order==='desc'?b.metric-a.metric:a.metric-b.metric);$('#riskfull').innerHTML=table(['排名',k===1?'店铺名称':'产品 / 项目','所属链群',labels[k],'风险原因','责任人','操作'],a.map((p,i)=>[i+1,`<span class="risk-product-name">${riskThumbnail(p.name,k===1)}${esc(p.name)}</span>`,chains[p.chain],`<span class="red">${p.value}</span>`,p.desc,p.owner,`<button class="link" data-riskitem="${k},${p.id}">查看详情</button>`]));modalData=a.map((p,i)=>[i+1,p.name,chains[p.chain],p.value,p.desc,p.owner])}fill('default');$('#risksort').onchange=e=>fill(e.target.value)}
function riskDetail(k,id){const p=riskRows(k).find(p=>p.id===id);if(k===5){projectDetail(p.id);return}const labels=['差评率','店铺评分','月度亏损金额','库存总金额','滞销积压金额','','退货率环比增长率'];openModal(p.name+' · 风险详情',`<div class="detailgrid">${[['型号',p.model],['所属品类',chains[p.chain]],['所属品牌',p.brand],['销售渠道',p.channel],['核心指标',labels[k]+' '+p.value],['风险等级','高危'],['责任人',p.owner],['风险原因',p.desc]].map(([a,b])=>`<div class="detailitem"><small>${a}</small>${b}</div>`).join('')}</div><div class="aitext"><h3>建议处理方向</h3><p>${['优先核实平台处罚，复盘退货与差评原因，对高频故障安排品质复测。','复核违规记录并安排申诉，拆分流量来源，跟踪店铺体验分修复。','拆解采购、平台、物流及退货损耗成本，评估调价与降本空间。','按库龄及近30天动销复核呆滞库存，形成渠道调拨与清库方案。','季节性产品优先评估清库窗口，测算折扣后的利润与库存回收。','','对比相邻周期发货和退货数量，确认波动来源，排查品质与物流异常。'][k]}</p><p class="source">证据来源：模拟${['品质风险台账','店铺运营月报','财务毛利台账','库存库龄台账','产品动销台账','','退货台账'][k]} · ${dateBack(0)}</p></div><div class="notice">这是设计示例，AI 建议需人工复核；任务草稿仅保存在当前浏览器。</div>`);$('#dialogactions').insertAdjacentHTML('afterbegin',`<button class="btn primary small" id="riskdraft">生成整改草稿</button>`);$('#riskdraft').onclick=()=>draft(p.name+'风险整改',p.owner)}
const aiLabels=['核心卡点','工作偏差','优先工作','资源调配'];
const aiContent=[[
['P0 · 厨房链 / 采购部','海尔1.2升多功能破壁豆浆机核心物料资质复审未完成，影响样机交付及后续量产排期。建议采购部在 2 个工作日内完成复审并确认替代供应商。','采购日报、项目卡点台账 · 责任人：周铭'],['P1 · 清洁链 / 研发部','洗地机测试版本交付滞后，品质复测与上品计划出现依赖阻塞。建议明确版本冻结时间并预留测试窗口。','研发日报、跨链协同记录 · 责任人：林悦'],['26 项高风险卡点','高危 12 项、中风险 14 项；以项目为单位去重，同一项目保留主要卡点。','模拟项目台账 · 按当前所选截止日项目快照']],
[['流程遗漏 · 3 项','部分立项缺少竞品与成本评估附件，建议产品部完成材料补齐后再推进评审。','立项资料检查记录'],['重心错位 2 项 · 资源浪费 1 项','研发资源集中于常规迭代，优先项目缺少测试支持；建议复核本周资源投入。','部门日报、人员排期记录'],['协同漏洞 · 4 项','跨链交付事项存在未回复与逾期，建议在周例会上确定单一责任人和闭环时限。','跨链协同台账、会议纪要']],
[['P0 · 完成核心物料资质复审','责任人：周铭 / 采购部。明日关键行动：确认补充材料、完成复核、给出可执行交付日期。','关联：海尔1.2升多功能破壁豆浆机 / KT-102'],['P0 · 洗地机关键测试闭环','责任人：林悦 / 研发部。明日关键行动：冻结测试版本，安排品质复测，确认上品风险。','关联：苏泊尔洗地机EWV-M22 / CL-105'],['P1 · 制定季节性产品库存处置方案','责任人：陈嘉 / 产品部。本周工作：按渠道复核积压库存，测算促销及调拨成本。','库存月报、滞销产品台账']],
[['R001 · 研发人力调配建议','建议评估从环境链临时抽调 1 位工程师支持厨房链两周。调配可能影响环境链常规迭代，需双方部长确认后执行。','资源排期表、跨链协同记录'],['R002 · 品质检测窗口建议','建议为高危整改产品预留复测窗口，调整低优先级样品送检顺序。需品质部评估资质与检测能力。','检测排期、红灯项目台账'],['R003 · 备用供应商导入建议','建议对现有储备供应商安排并行小样验证，缓解单一物料供应风险。费用与采购份额需采购部确认。','供应商池、核心物料风险清单']]];
function openAI(tab=0){aiTab=tab;const selectedPeriod=copyPeriod(periodFor('ai'));const key='pc-ai-v2-'+periodKey(selectedPeriod)+'-'+tab;let edited='';try{edited=localStorage.getItem(key)||''}catch{}openModal('全局 AI 总诊断',`<div class="tabs">${aiLabels.map((x,i)=>`<button data-ai="${i}" class="${i===tab?'active':''}">${x}</button>`).join('')}</div><div class="notice">示例诊断 · 复盘范围见顶部日期；历史工作项仅供回溯，AI 建议须人工确认。</div><div id="aireport">${edited?`<div class="aitext"><h3>人工复核版本</h3><p style="white-space:pre-wrap">${esc(edited)}</p><p class="source">已保存在当前浏览器 · 原始示例证据来源见编辑日志</p></div>`:aiContent[tab].map((x,i)=>`<article class="aitext"><h3>${x[0]}</h3><p>${x[1]}</p><p class="source">证据来源：${x[2]}</p>${tab===2?`<button class="link" data-draft="${esc(x[0])}">生成工作草稿 →</button>`:''}</article>`).join('')}</div><button class="link" id="editai">✎ 人工复核编辑</button><button class="link" id="ailogs" style="margin-left:15px">查看编辑日志</button>`,true,'演示生成时间：'+dateBack(0)+' 09:00');$('#editai').onclick=()=>{const before=edited||aiContent[tab].map(x=>x[0]+'\n'+x[1]+'\n证据来源：'+x[2]).join('\n\n');$('#aireport').innerHTML=`<textarea id="edittext" aria-label="人工编辑诊断内容">${esc(before)}</textarea><button class="btn primary small" id="saveedit" style="margin:12px 0">保存到本地并留痕</button>`;$('#saveedit').onclick=()=>{try{let after=$('#edittext').value;localStorage.setItem(key,after);let logs=JSON.parse(localStorage.getItem('pc-ai-logs')||'[]');logs.push({人:'演示负责人',时间:new Date().toLocaleString(),周期:periodLabel(selectedPeriod),类型:aiLabels[tab],修改前:before,修改后:after});localStorage.setItem('pc-ai-logs',JSON.stringify(logs));openAI(tab);toast('已保存本地复核版本及编辑日志')}catch{toast('浏览器未允许本地存储，未保存')}}};$('#ailogs').onclick=()=>{let logs=[];try{logs=JSON.parse(localStorage.getItem('pc-ai-logs')||'[]')}catch{}openModal('AI 编辑日志',logs.length?logs.map(l=>`<div class="aitext"><h3>${esc(l.类型)} · ${esc(l.时间)}</h3><p>操作人：${esc(l.人)} · ${esc(l.周期||('Q'+l.季度))}</p><details><summary>修改前后内容</summary><p style="white-space:pre-wrap">修改前：${esc(l.修改前)}\n\n修改后：${esc(l.修改后)}</p></details></div>`).join(''):'<div class="empty">暂无编辑记录</div>',true)}}const DRAWER_PAGE_SIZE=20;
function listPageNumbers(page,pages){
 const visible=new Set([1,pages,...Array.from({length:5},(_,i)=>page+i-2)].filter(n=>n>=1&&n<=pages));
 const result=[];for(const n of [...visible].sort((a,b)=>a-b)){const last=result.at(-1);if(typeof last==='number'&&n-last>1)result.push(n-last===2?last+1:'…');result.push(n)}return result;
}
function listPager(total,page,size=DRAWER_PAGE_SIZE,delegate={}){
 const pages=Math.max(1,Math.ceil(total/size));page=Math.max(1,Math.min(page,pages));
 const extra=Object.entries(delegate.extra||{}).map(([key,value])=>`${key}="${esc(String(value))}"`).join(' ');
 const attrs=n=>delegate.attr?`${delegate.attr}="${esc(String(delegate.value??((delegate.prefix||'')+n)))}" ${extra} ${delegate.delta?`${delegate.delta}="${n-page}"`:''}`:'';
 const button=(n,label,disabled=false,arrow=false)=>`<button type="button" class="list-page-button ${arrow?'list-page-arrow':''} ${!arrow&&n===page?'selected':''}" data-list-page="${n}" ${attrs(n)} ${disabled?'disabled':''} ${!arrow&&n===page?'aria-current="page"':''} aria-label="${arrow?(n<page?'上一页':'下一页'):'第'+n+'页'}">${label}</button>`;
 return `<nav class="list-pagination" aria-label="列表分页" data-list-total="${total}" data-list-current="${page}" data-list-pages="${pages}" data-list-size="${size}" data-list-prefix="${esc(delegate.prefix||'')}" data-list-attr="${delegate.attr||''}" data-list-value="${esc(String(delegate.value??''))}" data-list-delta="${delegate.delta||''}" data-list-extra="${esc(JSON.stringify(delegate.extra||{}))}"><span class="list-page-total">共 ${fmt(total)} 条</span><span class="list-page-size">${size}条/页</span><div class="list-page-numbers">${button(page-1,'‹',page===1,true)}${listPageNumbers(page,pages).map(n=>n==='…'?'<span class="list-page-ellipsis">…</span>':button(n,n)).join('')}${button(page+1,'›',page===pages,true)}</div><label class="list-page-jump">前往<input type="number" min="1" max="${pages}" step="1" value="${page}" aria-label="跳转页码" inputmode="numeric">页</label></nav>`;
}
function listNavigate(nav,page,onPage){
 if(nav.dataset.listNavigating)return;nav.dataset.listNavigating='true';
 try{onPage(page)}finally{delete nav.dataset.listNavigating}
}
function listJump(nav,input,onPage){
 if(nav.dataset.listNavigating)return;
 const raw=input.value.trim(),n=Number(raw),current=Number(nav.dataset.listCurrent),pages=Number(nav.dataset.listPages);
 if(!raw||!Number.isInteger(n)){input.value=current;return}
 const page=Math.max(1,Math.min(n,pages));input.value=page;if(page!==current)listNavigate(nav,page,onPage);
}
function bindListPager(host,onPage){
 const nav=host.querySelector('.list-pagination');if(!nav)return;nav.dataset.listDirect='true';
 nav.onclick=e=>{const b=e.target.closest('[data-list-page]');if(b&&!b.disabled){e.stopPropagation();const n=Number(b.dataset.listPage);if(n!==Number(nav.dataset.listCurrent))listNavigate(nav,n,onPage)}};
 const input=nav.querySelector('input');input.onchange=()=>listJump(nav,input,onPage);
 input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();e.stopPropagation();listJump(nav,input,onPage)}};
}
function mountListPager(host,total,page,onPage){host.innerHTML=listPager(total,page);bindListPager(host,onPage)}
// Delegated lists keep their existing page event contract; jumps dispatch once.
function listDelegatedJump(input){
 const nav=input.closest('.list-pagination');if(!nav||nav.dataset.listDirect||!nav.dataset.listAttr)return;
 listJump(nav,input,page=>{const button=document.createElement('button');button.type='button';button.hidden=true;button.setAttribute(nav.dataset.listAttr,nav.dataset.listValue||((nav.dataset.listPrefix||'')+page));if(nav.dataset.listDelta)button.setAttribute(nav.dataset.listDelta,page-Number(nav.dataset.listCurrent));for(const [key,value] of Object.entries(JSON.parse(nav.dataset.listExtra||'{}')))button.setAttribute(key,value);nav.append(button);button.click();button.remove()});
}
document.addEventListener('change',e=>{if(e.target.matches('.list-page-jump input'))listDelegatedJump(e.target)});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('.list-page-jump input')){e.preventDefault();listDelegatedJump(e.target)}});

function draft(name,owner='对应链主'){openModal('工作项草稿',`<div class="detailgrid"><div class="detailitem wide"><small>工作内容</small>${esc(name)}</div><div class="detailitem"><small>建议责任人</small>${esc(owner)}</div><div class="detailitem"><small>状态</small><span class="tag orange">未下发</span></div></div><label for="drafttext" class="note">补充执行要求</label><textarea id="drafttext">核实当前问题、制定闭环计划，并记录责任人及完成时间。</textarea><div class="notice" style="margin-top:12px">本原型未连接任务系统。保存后仅生成本地草稿，不会通知责任人。</div>`);$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary small" id="savedraft">保存本地草稿</button>');$('#savedraft').onclick=()=>{try{const ds=JSON.parse(localStorage.getItem('pc-drafts')||'[]');ds.push({name,owner,content:$('#drafttext').value,date:new Date().toISOString()});localStorage.setItem('pc-drafts',JSON.stringify(ds));toast('草稿已保存到当前浏览器，尚未下发');closeModal()}catch{toast('浏览器未允许本地存储，未保存')}}}
function renderSales(){const all=[totalSales(),...sales()];$('#salescards').innerHTML=all.map((p,i)=>`<article class="salescard ${i===0?'company':''}"><h3>${p.name}<button class="link" data-sales="${i-1}" aria-label="查看${p.name}销售明细">↗</button></h3><div class="metriclabel" style="margin-top:12px">季度销售额</div><div class="amount num">${fmt(p.sale)}<span class="unit">万元</span></div><div class="salesrow"><span>季度规模达成率</span>${badge(p.sale/p.target*100)}</div><div class="track"><i style="width:${Math.min(p.sale/p.target*100,100)}%"></i></div><div class="salesrow"><span class="muted">SKU 总数</span><b class="num">${p.sku} 个</b></div><div class="salesrow"><span class="muted">季度利润率</span><b class="num">${fmt(p.profit,1)}%</b></div><div class="salesrow" title="年度目标－年度累计销售额；正值表示剩余缺口"><span class="muted">年度销售额差额</span><b class="num">${fmt(p.annual-p.ytd)}</b></div>${spark(i)}</article>`).join('');const s=sales(),max=Math.ceil(Math.max(...s.flatMap(p=>[p.sale,p.target]))/1000)*1000;$('#saleschart').innerHTML=`<svg viewBox="0 0 580 200" role="img" aria-label="四大链群季度销售额与目标比较">${[0,max/4,max/2,max*3/4,max].map(v=>`<line x1="48" y1="${165-v/max*140}" x2="568" y2="${165-v/max*140}" stroke="#edf0f6"/><text x="38" y="${169-v/max*140}" text-anchor="end">${v?fmt(v):0}</text>`).join('')}${s.map((p,i)=>{const x=100+i*128;return `<g class="chartclick" data-sales="${i}"><rect x="${x-15}" y="${165-p.target/max*140}" width="23" height="${p.target/max*140}" rx="3" fill="#e3e7fb"/><rect x="${x+13}" y="${165-p.sale/max*140}" width="23" height="${p.sale/max*140}" rx="3" fill="#7381fb"/><text x="${x+25}" y="${158-p.sale/max*140}" text-anchor="middle" style="fill:#6370da">${fmt(p.sale)}</text><text x="${x+8}" y="191" text-anchor="middle">${p.name}</text></g>`}).join('')}</svg>`;$('#attainchart').innerHTML=s.map(p=>{const r=p.sale/p.target*100;return `<div class="barrow"><span>${p.name}</span><div class="track"><i style="width:${Math.min(100,r)}%;background:var(--${status(r)})"></i></div><b class="${status(r)} num">${fmt(r,1)}%</b></div>`}).join('');$('#thresholdnote').textContent=`绿灯 ≥${config.green}% · 黄灯 ${config.yellow}%–${config.green}% · 红灯 <${config.yellow}%；达成率达到绿灯阈值即为绿灯。`}
function salesDetail(index,view='brand'){activeSales=index;salesView=view;const p=index<0?totalSales():sales()[index],labels=view==='brand'?brands:channels;const weights=labels.map((_,i)=>labels.length-i+3),ws=weights.reduce((a,b)=>a+b,0);const distribute=n=>{let a=weights.map(w=>Math.floor(n*w/ws));a[a.length-1]+=n-a.reduce((x,y)=>x+y,0);return a};const actual=distribute(p.sale),target=distribute(p.target),sku=distribute(p.sku),annual=distribute(p.annual-p.ytd);const rows=labels.map((l,i)=>[l,sku[i],fmt(actual[i]),fmt(target[i]),fmt(actual[i]/target[i]*100,1)+'%',fmt(p.profit,1)+'%',fmt(annual[i])]);openModal(p.name+' · 销售明细',`<div class="contextstrip"><div class="tabs"><button data-salesview="brand" class="${view==='brand'?'active':''}">分品牌</button><button data-salesview="channel" class="${view==='channel'?'active':''}">分渠道</button></div><span class="note">${periodLabel()} · 金额单位：万元 · 各维度合计与大盘一致</span></div><div class="tablewrap">${table([view==='brand'?'品牌':'销售渠道','SKU 总数','季度销售额','季度销售目标','季度规模达成率','季度利润率','年度销售额差额'],rows)}</div>`);}
function filteredProjects(){const chain=$('#projectchain').value,type=$('#projecttype').value;return projects().filter(p=>(chain==='全部'||p.chain===+chain)&&(type==='全部'||p.type===type))}
function renderProjects(){let list=filteredProjects(),tot=list.length,red=list.filter(p=>p.status==='红灯').length,yellow=list.filter(p=>p.status==='黄灯').length,green=tot-red-yellow,high=list.filter(p=>p.delay>config.delay).length;let s=[['项目总数量',tot,'all',''],['绿灯项目数',green,'绿灯','green'],['黄灯项目数',yellow,'黄灯','orange'],['红灯项目数',red,'红灯','red'],['高危红灯项目数',high,'high','red']];$('#projectstats').innerHTML=s.map(([l,n,id,c])=>`<button class="stat ${projectStatus===id?'selected':''}" data-status="${id}"><span>${c?`<i class="dot ${c}"></i>`:''}${l}</span><strong class="num ${c}">${n}<span class="unit">个</span></strong><small>${id==='all'?'覆盖 '+new Set(filteredProjects().map(p=>p.type)).size+' 类项目':id==='high'?'延期 > '+config.delay+' 天':'占当前项目 '+(tot?fmt(n/tot*100,1):'0')+'%'}</small></button>`).join('');$('#projectprogress').innerHTML=[['green',green],['orange',yellow],['red',red]].map(([c,n])=>`<span style="width:${tot?n/tot*100:0}%;background:var(--${c})"></span>`).join('');$('#projecttabs').innerHTML=[['all','全部项目'],['红灯','红灯项目'],['黄灯','黄灯项目'],['绿灯','绿灯项目']].map(([v,l])=>`<button data-status="${v}" class="${v===projectStatus?'active':''}">${l}</button>`).join('');const q=$('#projectsearch').value.trim();list=list.filter(p=>(projectStatus==='all'||(projectStatus==='high'?p.delay>config.delay:p.status===projectStatus))&&(!q||p.name.toLocaleLowerCase().includes(q.toLocaleLowerCase())));const pages=Math.max(1,Math.ceil(list.length/5));projectPage=Math.min(projectPage,pages);$('#projecttable').innerHTML=table(['产品 / 项目','项目类型','红绿灯状态','当前阶段','原计划量产','调整后计划量产','实际量产','计划调整','逾期天数','责任部门 / 项目经理','操作'],list.slice((projectPage-1)*5,projectPage*5).map(p=>[titleProduct(p),esc(p.type),traffic(p.status),esc(p.stage),p.plan,p.revisedPlan||'—',esc(p.actual&&p.actual!=='—'?p.actual:'待补录'),p.plannedDelay===null?'—':p.plannedDelay===0?'未调整':`<span class="${p.plannedDelay>0?'orange':'green'}">${p.plannedDelay>0?'延后':'提前'} ${Math.abs(p.plannedDelay)} 天</span>`,p.delay?`<span class="red num">${p.delay} 天</span>`:'—',esc(p.dept)+'<small>'+esc(p.owner)+'</small>',`<button class="link" data-project="${p.id}">查看详情</button>`]));if(!list.length)$('#projecttable').innerHTML='<div class="empty">暂无匹配项目</div>';$('#projectcount').textContent='';$('#projectpages').innerHTML=listPager(list.length,projectPage,5,{attr:'data-page'});$('#departments').innerHTML=depts.map(d=>{const all=filteredProjects().filter(p=>p.dept===d),r=all.filter(p=>p.status==='红灯'),h=r.filter(p=>p.delay>config.delay).length;return `<button class="dept" data-dept="${d}"><h3>${d} <span class="muted">›</span></h3><div class="depnum num">${r.length}<span class="unit">个红灯</span></div><small>高危 ${h} 个 · 占比 ${all.length?fmt(r.length/all.length*100,1):0}%</small><small>${r[0]?.cause||'暂无红灯卡点'}</small></button>`}).join('')}
function projectDetail(id){let p=projects().find(p=>p.id===+id);let fields=[['产品名称',p.name],['型号',p.model],['所属品类',chains[p.chain]],['所属品牌',p.brand],['立项日期',dateBack(100)],['计划上线日期',p.plan],['实际上线日期',p.actual+'（尚未上线）'],['延迟天数',p.delay+' 天'],['单品成本','¥ '+p.cost],['单品售价','¥ '+p.price],['卡点阶段',p.status==='绿灯'?'无':p.stage],['卡点部门',p.status==='绿灯'?'无':p.dept],['根因描述',p.status==='绿灯'?'按计划推进':p.cause],['责任人',p.owner],['红绿灯状态',traffic(p.status)],['跟进日志链接','<a class="blue" href="#projectlog">查看本项目跟进记录 ↓</a>']];openModal('项目详情 · '+p.name,`<div class="detailgrid">${fields.map(([l,v])=>`<div class="detailitem"><small>${l}</small>${v}</div>`).join('')}</div><div class="tabs" id="logtabs"><button class="active" data-log="0">跟进记录</button><button data-log="1">延期时间线</button><button data-log="2">卡点日志与责任人轨迹</button></div><div id="projectlog"></div>`);const logs=[`<div class="timeline"><p>${dateBack(0)} 09:10 · ${p.owner}<small>${p.status==='绿灯'?'项目按计划推进，已更新本周工作安排。':'已确认卡点，待责任部门反馈闭环日期。'}</small></p><p>${dateBack(2)} 16:20 · 项目部<small>例会复核项目进展及依赖事项。</small></p></div>`,`<div class="timeline"><p>原计划上线 · ${p.plan}</p><p>截至 ${dateBack(0)}<small>${p.delay?'尚未上线，延期 '+p.delay+' 天；新计划待评审确认。':'尚未到计划上线时间。'}</small></p></div>`,`<div class="timeline"><p>卡点：${p.status==='绿灯'?'无':p.cause}<small>状态：${p.status==='绿灯'?'正常':'待闭环'} · 责任部门：${p.dept}</small></p><p>责任人：${p.owner}<small>本快照无责任人变更记录。</small></p></div>`];$('#projectlog').innerHTML=logs[0];$('#logtabs').onclick=e=>{if(!e.target.dataset.log)return;$('#projectlog').innerHTML=logs[+e.target.dataset.log];$('#logtabs .active').classList.remove('active');e.target.classList.add('active')};}
const lifeNames=['自研上品计划','选品上品计划','自研立项规划','选品立项规划','产品迭代规划','品质整改规划','研发创新规划','产品下市规划'];
function newList(){let c=$('#newchain').value;return productRows(true).filter(p=>c==='全部'||p.chain===+c||pfCategory(p)===c)}
function renderNew(){const list=newList(),c=$('#newchain').value,{planned,ontime,sold}=newMetrics();const channelTotals=channels.map(ch=>list.filter(p=>p.channel===ch).reduce((a,p)=>a+p.sales,0)),max=Math.max(...channelTotals,1);$('#newtop').innerHTML=`<div class="newmetric"><span>新品销售成功率</span><strong class="num">${fmt(sold/planned*100,1)}<span class="unit">%</span></strong><small class="muted">按期上品且有销售 ${sold} / 计划 ${planned}</small>${spark(1)}</div><div class="newmetric"><span>新品上线及时率</span><strong class="num">${fmt(ontime/planned*100,1)}<span class="unit">%</span></strong><small class="muted">按期上线 ${ontime} / 计划 ${planned}</small>${spark(3)}</div><div class="donutwrap"><div class="donut" id="newdonut"><span class="num">${list.length}<small>新品样本</small></span></div><div class="donutleg">${['A','B','C','D'].map((g,i)=>`<div><i style="background:${['#5865f5','#9285fa','#6bc8f9','#edb667'][i]}"></i>${g} 级　${list.filter(p=>p.grade===g).length}</div>`).join('')}</div></div><div><h3 style="margin-bottom:8px">各渠道新品季度销售额</h3><svg viewBox="0 0 290 110" role="img" aria-label="新品分渠道季度销售额，单位万元">${channelTotals.map((n,i)=>`<rect x="${i*35+10}" y="${85-n/max*65}" width="17" height="${n/max*65}" rx="2" fill="#93a0ff"/><text x="${i*35+18}" y="${79-n/max*65}" text-anchor="middle">${fmt(n)}</text><text x="${i*35+18}" y="104" text-anchor="middle">${channels[i]}</text>`).join('')}</svg></div>`;let start=0;const colors=['#5865f5','#9285fa','#6bc8f9','#edb667'];$('#newdonut').style.background='conic-gradient('+['A','B','C','D'].map((g,i)=>{let end=start+list.filter(p=>p.grade===g).length/list.length*100;const s=colors[i]+' '+start+'% '+end+'%';start=end;return s}).join(',')+')';$('#newtable').innerHTML=table(['产品名称','上线天数','所属品类 / 渠道','季度销售额','单品利润率','总退货率','销售状态','产品等级','操作'],list.slice(0,5).map(p=>[titleProduct(p),p.days+' 天',chains[p.chain]+'<small>'+p.channel+'</small>',fmt(p.sales,1)+' 万',fmt(p.profit,1)+'%',fmt(p.returnRate,1)+'%',`<span class="tag ${p.state==='整改'?'orange':'green'}">${p.state}</span>`,`<span class="tag">${p.grade}</span>`,`<button class="link" data-product="new,${p.id}">✧ AI 新品评估</button>`]));$('#newcount').textContent=`当前 ${list.length} 个新品样本 · 已展示 ${Math.min(5,list.length)} 条 · 新品等级为人工评级示例`}
function productDetail(isNew,id){const p=productRows(isNew).find(p=>p.id===+id),cat=category(p),strategies={A:'保障供货，推进迭代，扩充衍生产品矩阵。',B:'拆解采购成本与退货损耗，优先推动采购降本、品质改善及产品迭代。',C:'小范围测试渠道扩展与内容投放，结合需求验证追加备货。',D:'测算降本与迭代可行性，评估品牌调整、清仓及下市方案。',O:'处于中间观察区，持续跟踪动销及利润，不强行归入四类榜单。'};openModal((isNew?'新品评估':'老品经营策略')+' · '+p.name,`<div class="detailgrid">${[['型号',p.model],['所属品类',chains[p.chain]],['品牌 / 渠道',p.brand+' / '+p.channel],['上架时长',p.days+' 天'],[isNew?'季度销售额':'近30天销售额',fmt(p.sales,1)+' 万元'],['单品利润率',fmt(p.profit,1)+'%'],['总退货率',fmt(p.returnRate,1)+'%'],[isNew?'产品等级':'经营分层',isNew?p.grade:cat==='O'?'中间观察区':cat+' 类']].map(([a,b])=>`<div class="detailitem"><small>${a}</small>${b}</div>`).join('')}</div><h3>${isNew?'季度':'近30天'} GMV 趋势 · 演示分布（万元）</h3>${trend(p.sales,isNew?bounds():{start:shiftDate(bounds().cutoff,-29),cutoff:bounds().cutoff})}<div class="aitext"><h3>✧ ${isNew?'AI 新品经营建议':'标准化处置策略'}</h3><p>${isNew?(p.grade==='D'?'优先排查需求匹配、退货原因与渠道定位，验证优化方案后再扩大投入。':'结合当前渠道表现评估推广与供给，持续监测毛利和退货率，避免仅按销售额放大投放。'):strategies[cat]}</p><p class="source">证据来源：模拟销售、毛利与退货台账 · ${dateBack(0)}</p></div>`);$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary small" id="productdraft">生成工作草稿</button>');$('#productdraft').onclick=()=>draft(p.name+(cat==='B'?'降本评估':'经营优化'))}
function trend(total){let vals=[.07,.095,.085,.12,.105,.13,.145,.15,.1].map(n=>n*total),max=Math.max(...vals)*1.2;let pts=vals.map((v,i)=>`${50+i*63},${155-v/max*120}`).join(' ');return `<svg viewBox="0 0 590 195" role="img" aria-label="周期内分段销售额趋势，单位万元"><line x1="50" y1="155" x2="554" y2="155" stroke="#e8ecf5"/><text x="40" y="155" text-anchor="end">0</text><text x="40" y="35" text-anchor="end">${fmt(max,0)}</text><polyline points="${pts} 554,155 50,155" fill="#f0f3ff"/><polyline points="${pts}" fill="none" stroke="#7182fb" stroke-width="2.5"/>${vals.map((v,i)=>`<circle cx="${50+i*63}" cy="${155-v/max*120}" r="3" fill="#7182fb"><title>第${i+1}段：${pfMoneyYuan((v)*10000)}</title></circle>`).join('')}<text x="50" y="180">周期开始</text><text x="554" y="180" text-anchor="end">统计截止日</text></svg>`}
function renderMatrix(){let rows=productRows(false);let w=460,h=260,left=44,right=444,top=28,bottom=223,maxX=Math.max(140,config.high*1.4,...rows.map(p=>p.sales*1.1)),maxY=Math.max(26,config.profit*1.5,...rows.map(p=>p.profit*1.1));const x=v=>left+v/maxX*(right-left),y=v=>bottom-v/maxY*(bottom-top),low=x(config.low),high=x(config.high),mid=y(config.profit);$('#matrixchart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="老品销售利润矩阵：横轴近30天销售额万元，纵轴单品利润率百分比"><text x="44" y="15">单品利润率（%）</text><rect x="${left}" y="${top}" width="${low-left}" height="${mid-top}" fill="#f0f6ff"/><rect x="${left}" y="${mid}" width="${low-left}" height="${bottom-mid}" fill="#fff3f3"/><rect x="${low}" y="${top}" width="${high-low}" height="${bottom-top}" fill="#f6f7fa"/><rect x="${high}" y="${top}" width="${right-high}" height="${mid-top}" fill="#eef9f5"/><rect x="${high}" y="${mid}" width="${right-high}" height="${bottom-mid}" fill="#fff9ed"/>${[config.low,config.high].map(v=>`<line x1="${x(v)}" x2="${x(v)}" y1="${top}" y2="${bottom}" stroke="#c7cedf" stroke-dasharray="4 4"/>`).join('')}<line x1="44" x2="444" y1="${mid}" y2="${mid}" stroke="#c7cedf" stroke-dasharray="4 4"/><text x="${left+8}" y="47">C</text><text x="${high+10}" y="47" style="fill:#469c81">A 高销高利</text><text x="${left+8}" y="${mid+19}">D</text><text x="${high+10}" y="${mid+19}" style="fill:#bd964c">B 高销低利</text><text x="${(low+high)/2}" y="47" text-anchor="middle">观察区</text>${[0,config.low,config.high,maxX].map(v=>`<text x="${x(v)}" y="245" text-anchor="middle">${fmt(v)}</text>`).join('')}${[0,config.profit,maxY].map(v=>`<text x="35" y="${y(v)+4}" text-anchor="end">${fmt(v,1)}%</text>`).join('')}${rows.map(p=>`<circle class="chartclick" data-product="old,${p.id}" cx="${x(p.sales)}" cy="${y(p.profit)}" r="5" fill="${{A:'#38b190',B:'#eab45e',C:'#718bf1',D:'#e2848d',O:'#afb6c8'}[category(p)]}" fill-opacity=".8"><title>${p.name}：${pfMoneyYuan((p.sales)*10000)} / 利润率${p.profit}%</title></circle>`).join('')}</svg>`;$('#matrixtabs').innerHTML=[['A','高销高利'],['B','高销低利'],['C','低销高利'],['D','低销低利']].map(([c,l])=>`<button class="${matrixTab===c?'active':''}" data-matrix="${c}">${c} ${l}</button>`).join('');const sorted=rows.filter(p=>category(p)===matrixTab).sort((a,b)=>b.sales-a.sales).slice(0,10);$('#matrixtable').innerHTML=table(['产品 / 品牌','近30天销售额','单品利润率','总退货率','操作'],sorted.map(p=>[titleProduct(p),fmt(p.sales,1)+' 万',`<span class="${p.profit<config.profit?'orange':'green'}">${fmt(p.profit,1)}%</span>`,fmt(p.returnRate,1)+'%',`<button class="link" data-product="old,${p.id}">AI 策略</button>`]));}
function stockDetail(i){const p=inventoryRows()[i];openModal(p.name+' · 库存概览',`<div class="detailgrid">${[['库存数',fmt(p.num)+' 件'],['库存总金额',p.amount+' 万元'],['库存周转率',fmt(p.turn,2)+' 次/'+{month:'月',quarter:'季',year:'年'}[periodFor().mode]],['呆滞库存金额',p.stale+' 万元']].map(([a,b])=>`<div class="detailitem"><small>${a}</small>${b}</div>`).join('')}</div><div class="aitext"><h3>库存处置建议</h3><p>呆滞库存占比 ${fmt(p.stale/p.amount*100,1)}%。优先核对库龄超过 90 天且近 30 天无动销的产品，结合渠道动销制定处置方案。</p><p class="source">证据来源：模拟 WMS 截止日库存快照</p></div><div class="notice">SKU 库龄、在途库存与工单属于独立库存管理页面，本次总看板仅展示汇总及下钻示意。</div>`)}
function renderSuppliers(){$('#suppliergrid').innerHTML=supplierData().map((p,i)=>`<article class="supplierpanel"><div class="charthead"><h3><span class="tier">TIER ${i+1}</span>${p.tier}供应商管控</h3><span class="note">${i?'备选与外协补充':'核心主力供货'}</span></div><div class="suppliernums"><button data-supplier="${i},reserve"><span class="muted">${p.tier}储备供应商总数</span><strong class="num">${p.reserve}<span class="unit">家</span></strong></button><button data-supplier="${i},active"><span class="muted">${p.tier}合作供应商总数</span><strong class="num">${p.active}<span class="unit">家</span></strong></button></div><div class="supplierprogress ${periodFor().mode==='year'?'single-period':''}"><div><div class="inline"><span>本季度新增</span>${badge(p.q/p.qt*100)}</div><div class="track"><i style="width:${p.q/p.qt*100}%"></i></div><div class="inline muted"><span>实际 ${p.q} 家</span><span>目标 ${p.qt} 家</span></div></div><div ${periodFor().mode==='year'?'hidden':''}><div class="inline"><span>本年度累计新增</span>${badge(p.y/p.yt*100)}</div><div class="track"><i style="width:${p.y/p.yt*100}%"></i></div><div class="inline muted"><span>实际 ${p.y} 家</span><span>目标 ${p.yt} 家</span></div></div></div></article>`).join('')}
function suppliersDetail(tier,kind){let n=supplierData()[tier][kind==='reserve'?'reserve':'active'],type=kind==='reserve'?'储备':'合作';const rows=Array.from({length:n},(_,i)=>[`${['华新','恒拓','盛川','瑞能','森源','科泰'][i%6]}${['智造','精密','电器','科技'][Math.floor(i/6)%4]} ${String(i+1).padStart(2,'0')}（示例）`,chains[i%4],type,'有效',dateBack(160+i),kind==='reserve'?'—':dateBack(120+i)]);openModal((tier?'物料供应商':'整机供应商')+' · '+type,`<div class="notice">供应商名称为虚构示例，共 ${n} 家。</div><div class="tablewrap">${table(['供应商名称','所属供应品类','类型','资质状态','入库时间','合作起始时间'],rows)}</div>`);}
function costDetail(i){let p=costs()[i],a=Math.round(p.a*.6),t=Math.round(p.t*.6);let rows=[['核心物料成本优化','采购',t,a,people[i],'推进中'],['工艺与包装改善','工艺 / 包装',p.t-t,p.a-a,people[i+1],'推进中']];openModal(p.name+' · 降本项目明细',`<p class="note" style="margin-bottom:15px">金额单位：万元 · 实际降本仅计入财务已确认金额</p><div class="tablewrap">${table(['降本项目名称','降本类型','计划降本金额','实际降本金额','责任人','状态'],rows)}</div>`);}
