const moduleNames={risk:'高危预警',ai:'AI 总诊断',sales:'销售达成',projects:'项目进度',lifecycle:'生命周期',new:'新品专项',matrix:'关键产品',inventory:'库存管控',suppliers:'供应链采购',cost:'降本增效'};
