function shiftDate(date,n){const key=date+'|'+n,cached=shiftedDates.get(key);if(cached!==undefined)return cached;const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return shiftedDates.set(key,iso(d));}
