function renderInventory(){const oldView=invView;invView='chain';const all=inventoryRows();invView=oldView;const sum=k=>all.reduce((n,p)=>n+p[k],0),amount=sum('amount'),stale=sum('stale'),turn=sum('cost')/sum('avg'),delivery=sum('on')/sum('due')*100,ref=sum('refOn')/sum('refDue')*100;$('#inventorymetrics').innerHTML=[['总库存数',fmt(sum('num')),'件','截止日实物余额'],['库存总金额',fmt(amount),'万元','截止日账面成本'],['库存周转率',fmt(turn,2),'次/'+{month:'月',quarter:'季',year:'年'}[periodFor().mode],'周期成本 ÷ 平均库存'],['呆滞库存金额',fmt(stale),'万元','余额占比 '+fmt(stale/amount*100,1)+'%'],['交付率',fmt(delivery,1),'%','按期 '+sum('on')+' / 到期 '+sum('due')],['翻新及时率',fmt(ref,1),'%','按期 '+sum('refOn')+' / 到期 '+sum('refDue')]].map(([l,v,u,n],i)=>`<div class="inventorymetric"><span class="muted">${l}</span><strong class="num ${i===3?'orange':''}">${v}<span class="unit">${u}</span></strong><small>${n}</small></div>`).join('');$('#inventorytable').innerHTML=table([invView==='chain'?'业务链群':'合作品牌','期末库存数','期末库存金额','周期库存周转率','期末呆滞库存金额','周期交付率','周期翻新及时率','操作'],inventoryRows().map((p,i)=>[p.name,fmt(p.num),fmt(p.amount)+' 万',fmt(p.turn,2)+' 次/'+{month:'月',quarter:'季',year:'年'}[periodFor().mode],fmt(p.stale)+' 万',fmt(p.delivery,1)+'%',fmt(p.refurb,1)+'%',`<button class="link" data-stock="${i}">查看明细</button>`]));}
function costs(){const p=periodFor(),b=bounds(p);return [{name:'采购部',yt:2600,ratio:.82},{name:'研发部',yt:750,ratio:.96},{name:'产品部',yt:600,ratio:.98},{name:'品质部',yt:350,ratio:.93},{name:'项目部',yt:200,ratio:.91}].map(x=>{const targets=allocate(x.yt,Array(12).fill(1));const amount=m=>Math.round(targets[m-1]*x.ratio*(p.year===2025?.88:1)*(1+(m%3-1)*.04)*(p.year===2026&&m===9?.53:1));return {...x,t:targets.slice(b.first-1,b.last).reduce((a,b)=>a+b,0),a:months(p).reduce((n,m)=>n+amount(m),0),ya:months(p,true).reduce((n,m)=>n+amount(m),0)}})}
function renderCost(){const c=costs(),annual=periodFor().mode==='year',sum=k=>c.reduce((n,p)=>n+p[k],0);$('#costcards').style.gridTemplateColumns=annual?'1fr':'';$('#costcards').innerHTML=[[word()+'降本',sum('a'),sum('t')],...(annual?[]:[['年度累计降本',sum('ya'),sum('yt')]])].map(([l,a,t])=>`<div class="costcard"><div><h3>${l}实际达成</h3><strong class="num">${fmt(a)}<span class="unit">万元</span></strong><p class="note">目标金额 ${pfMoneyYuan((t)*10000)}</p></div><div><div class="costnumbers"><span>完成率</span><b class="num ${status(a/t*100)}">${fmt(a/t*100,1)}%</b></div><div class="track"><i style="width:${Math.min(100,a/t*100)}%"></i></div><div class="costnumbers"><span class="muted">数据差额</span><span class="red">${pfMoneyYuan((a-t)*10000)}</span></div></div></div>`).join('');$('#costtable').innerHTML=table(['责任部门',word()+'目标 / 实际（万元）',word()+'完成率',word()+'数据差额',...(annual?[]:['年度目标 / 累计实际（万元）','年度完成率','年度数据差额']),'操作'],c.map((p,i)=>[p.name,fmt(p.t)+' / '+fmt(p.a),badge(p.a/p.t*100),`<span class="red">${fmt(p.a-p.t)}</span>`,...(annual?[]:[fmt(p.yt)+' / '+fmt(p.ya),badge(p.ya/p.yt*100),`<span class="red">${fmt(p.ya-p.yt)}</span>`]),`<button class="link" data-cost="${i}">查看明细</button>`]));$('#costcallout').textContent=`截至 ${bounds().cutoff}，识别 ${productRows(false).filter(p=>category(p)==='B').length} 款近30天高销低利产品，建议优先拆解采购与退货成本。`}
function newMetrics(){const p=periodFor(),b=bounds(p),c=$('#newchain').value,cs=c==='全部'?[0,1,2,3]:[+c];let planned=0,ontime=0,sold=0;for(const chain of cs){for(let m=b.first;m<=b.last;m++)planned+=3+(m+chain)%2;for(const m of months(p)){const target=3+(m+chain)%2,timely=Math.max(0,target-((m+chain)%3===0?1:0)-(p.year===2026&&m===9?1:0));ontime+=timely;sold+=Math.max(0,timely-((m+chain)%4===0?1:0))}}return{planned,ontime,sold}}
function aiSnapshot(){const ms=months(),issues=[0,0,0,0],work=[0,0];ms.forEach(m=>{issues[0]+=m%3+1;issues[1]+=m%2+1;issues[2]+=m%2;issues[3]+=(m+1)%3+1;work[0]+=m%2+1;work[1]+=m%3+2});return{issues,work,red:projects().filter(p=>p.status==='红灯').length,yellow:projects().filter(p=>p.status==='黄灯').length,resources:Math.min(ms.length+1,6)}}
