document.addEventListener('click',e=>{const el=e.target.closest('[data-risk],[data-riskitem],[data-ai],[data-sales],[data-salesview],[data-status],[data-page],[data-project],[data-dept],[data-life],[data-view],[data-product],[data-matrix],[data-inv],[data-stock],[data-supplier],[data-cost],[data-rules],[data-draft]');if(!el)return;const d=el.dataset;if(d.risk!==undefined)openRisk(+d.risk);else if(d.riskitem!==undefined){const [k,id]=d.riskitem.split(',').map(Number);riskDetail(k,id)}else if(d.ai!==undefined)openAI(+d.ai);else if(d.sales!==undefined)salesDetail(+d.sales);else if(d.salesview)salesDetail(activeSales,d.salesview);else if(d.status){projectStatus=d.status;projectPage=1;renderProjects()}else if(d.page){projectPage=+d.page;renderProjects()}else if(d.project!==undefined)projectDetail(d.project);else if(d.dept){withPeriod('projects',()=>{const rows=filteredProjects().filter(p=>p.dept===d.dept&&p.status==='红灯');openModal(d.dept+' · 红灯归因',`<div class="tablewrap">${table(['产品名称','卡点阶段','根因描述','延迟天数','责任人','操作'],rows.map(p=>[p.name,p.stage,p.cause,p.delay+' 天',p.owner,`<button class="link" data-project="${p.id}">查看详情</button>`]))}</div>`)});}else if(d.life!==undefined){lifeIndex=+d.life;renderLife()}else if(d.view){lifeView=d.view;$$('#lifetabs button').forEach(b=>b.classList.toggle('active',b===el));renderLife()}else if(d.product){const [kind,id]=d.product.split(',');productDetail(kind==='new',id)}else if(d.matrix){matrixTab=d.matrix;renderMatrix()}else if(d.inv){invView=d.inv;$$('#inventorytabs button').forEach(b=>b.classList.toggle('active',b===el));renderInventory()}else if(d.stock!==undefined)stockDetail(+d.stock);else if(d.supplier){let [t,k]=d.supplier.split(',');suppliersDetail(+t,k)}else if(d.cost!==undefined)costDetail(+d.cost);else if(d.rules!==undefined)showRules();else if(d.draft)draft(d.draft)});

