const aiRecords=aiKinds.flatMap(([kind])=>aiFixtures[kind].map((row,i)=>({kind,id:kind+'-'+i,chain:row[0],department:row[1],owner:row[8]!==undefined?sampleProjectSource.find(p=>p.id===row[8]).productOwner:aiOwners[chains.indexOf(row[0])],subject:row[2],problem:row[3],action:row[4],level:row[5],stage:row[6],source:row[7],projectId:row[8],date:shiftDate(aiCutoff,-[0,0,1,2,7,21][i]),deadline:kind==='priority'?shiftDate(shiftDate(aiCutoff,-[0,0,1,2,7,21][i]),row[5]==='P0'?1:3):null})));
function aiDayPickerHTML(){return `<div class="ai-day-picker"><div class="period-segment ai-day-options"><button type="button" data-ai-daymode="single" aria-pressed="${aiView.dayMode!=='range'}">单日</button><button type="button" data-ai-daymode="range" aria-pressed="${aiView.dayMode==='range'}">日期区间</button></div>${aiView.dayMode==='range'?`<form id="ai-day-range-form" class="ai-day-range"><label class="ai-date-label">开始<input id="ai-day-start" type="date" aria-label="AI诊断开始日期" min="${aiCoverageStart}" max="${aiCutoff}" required value="${aiView.dayStart}"></label><span>至</span><label class="ai-date-label">结束<input id="ai-day-end" type="date" aria-label="AI诊断结束日期" min="${aiCoverageStart}" max="${aiCutoff}" required value="${aiView.dayEnd}"></label><button type="submit" class="btn small">应用</button><span id="ai-day-error" role="alert"></span></form>`:`<label class="ai-date-label">日期<input id="ai-date" type="date" aria-label="AI诊断日期" min="${aiCoverageStart}" max="${aiCutoff}" value="${aiView.date}"></label>`}</div>`}
function aiApplyDayRange(view,start,end){if(!start||!end||!Number.isFinite(Date.parse(start))||!Number.isFinite(Date.parse(end))||start<aiCoverageStart||end>aiCutoff||start>end)return false;view.dayStart=start;view.dayEnd=end;view.date=end;view.month=end.slice(0,7);return true}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ai-daymode]');if(!b)return;aiView.dayMode=b.dataset.aiDaymode;renderInlineAI()});
document.addEventListener('submit',e=>{const form=e.target;if(!['ai-day-range-form','dx-ai-day-range-form'].includes(form.id))return;e.preventDefault();const prefix=form.id.startsWith('dx-')?'dx-':'',view=prefix?dxAI:aiView,start=$('#'+prefix+'ai-day-start').value,end=$('#'+prefix+'ai-day-end').value;if(!aiApplyDayRange(view,start,end)){$('#'+prefix+'ai-day-error').textContent='请选择有效日期，开始日期不能晚于结束日期';return}if(prefix)dxRefresh('ai');else renderInlineAI()});
function inlineAIRange(){let start,end;if(aiView.mode==='all')return{start:aiCoverageStart,end:aiCutoff,plannedEnd:aiCutoff,label:'总览',partial:false};if(aiView.mode==='month'){start=aiView.month+'-01';const [y,m]=aiView.month.split('-').map(Number);end=iso(new Date(Date.UTC(y,m,0)))}else if(aiView.mode==='week'){const date=new Date(aiView.date+'T00:00:00Z'),offset=(date.getUTCDay()+6)%7;start=shiftDate(aiView.date,-offset);end=shiftDate(start,6)}else{start=aiView.dayMode==='range'?aiView.dayStart:aiView.date;end=aiView.dayMode==='range'?aiView.dayEnd:aiView.date}return{start,end:end>aiCutoff?aiCutoff:end,plannedEnd:end,label:{day:start===end?'日诊断':'区间诊断',week:'周诊断',month:'月诊断'}[aiView.mode],partial:end>aiCutoff}}
function inlineAIRows(){const range=inlineAIRange();return aiRecords.filter(r=>r.date>=range.start&&r.date<=range.end&&pfIncludes(aiView.chain,r.chain)&&(aiView.department==='全部'||r.department===aiView.department)&&(aiView.owner==='全部'||r.owner===aiView.owner)).sort((a,b)=>b.date.localeCompare(a.date)||((a.level==='高危'||a.level==='P0')?-1:1))}
function aiDetailTable(kind,rows){const hs=['风险 / 优先级','类目','对应部门','对应链主','诊断明细与业务影响',kind==='priority'?'行动要求 / 计划完成':'建议行动','记录时间','操作'];return `<div class="ai-detail-table"><table><thead><tr>${hs.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${[
 `<span class="tag ${r.level==='高危'||r.level==='P0'?'red':'orange'}">${r.level}</span><small>${r.stage}</small>`,
 esc(r.chain),esc(r.department),`<span class="chain-owner">${esc(r.owner)}</span>`,
 `<strong>${esc(r.subject)}</strong><p>${esc(r.problem)}</p><small class="ai-source">证据来源：${esc(r.source)}</small>`,
 `<p>${esc(r.action)}</p>${r.deadline?`<small class="ai-due">计划完成：${r.deadline}</small>`:''}`,r.date,
 `<div class="ai-row-actions"><button class="link" data-ai-detail="${r.id}">查看详情</button><button class="btn soft small" data-ai-handle="${r.id}">立即处理</button></div>${aiTasks[r.id]?'<small class="ai-task-saved">已建本地任务</small>':''}`
 ].map((v,i)=>`<td data-label="${hs[i]}">${v}</td>`).join('')}</tr>`).join(''):`<tr><td class="empty" colspan="8">所选时间及筛选条件下，暂无${aiKinds.find(k=>k[0]===kind)[1]}记录</td></tr>`}</tbody></table></div>`}
function renderInlineAI(){
 const range=inlineAIRange(),rows=inlineAIRows(),counts=Object.fromEntries(aiKinds.map(([k])=>[k,rows.filter(r=>r.kind===k&&(k!=='deviation'||r.finding==='deviation')).length])),high=rows.filter(r=>r.level==='高危'||r.level==='P0').length;
 $('#aitime').textContent='类目 × 部门 × 链主 · 按分类查看明细';
 $('#ai-inline-controls').innerHTML=`<div class="ai-time-main"><div class="period-segment ai-time-segment" role="group" aria-label="AI诊断时间粒度">${[['day','日'],['week','周'],['month','月'],['all','总览']].map(([v,l])=>`<button data-ai-period="${v}" aria-pressed="${aiView.mode===v}">${l}</button>`).join('')}</div>${aiView.mode==='all'?`<span class="ai-date-cover">全部记录</span>`:aiView.mode==='month'?`<label class="ai-date-label">月份<input id="ai-month" type="month" aria-label="AI诊断月份" min="${aiCoverageStart.slice(0,7)}" max="${aiCutoff.slice(0,7)}" value="${aiView.month}"></label>`:aiView.mode==='day'?aiDayPickerHTML():`<label class="ai-date-label">${aiView.mode==='week'?'所在周':'日期'}<input id="ai-date" type="date" aria-label="AI诊断日期" min="${aiCoverageStart}" max="${aiCutoff}" value="${aiView.date}"></label>`}<span class="ai-range-label">${range.start} — ${range.end}</span></div><div class="ai-dimension-filters"><label>类目<select multiple data-pf-multiple id="ai-chain" aria-label="AI类目筛选"><option>全部</option>${chains.map(c=>`<option ${pfOptionSelected(aiView.chain,c)?'selected':''}>${c}</option>`).join('')}</select></label><label>部门<select id="ai-department" aria-label="AI部门筛选"><option>全部</option>${depts.map(d=>`<option ${d===aiView.department?'selected':''}>${d}</option>`).join('')}</select></label><label>链主<select id="ai-owner" aria-label="AI链主筛选"><option>全部</option>${aiOwners.map(o=>`<option ${o===aiView.owner?'selected':''}>${o}</option>`).join('')}</select></label><button class="link" id="ai-reset">重置筛选</button></div>`;
 $('#aigrid').innerHTML=aiKinds.map(([kind,title,unit],i)=>`<button type="button" class="aicard ${kind===aiView.kind?'selected':''}" data-ai-kind="${kind}" aria-pressed="${kind===aiView.kind}" aria-controls="ai-inline-details"><h3>${title}</h3><div class="an num ${i===0?'red':i===2?'blue':''}">${counts[kind]}<span>${unit==='卡点'?'个':'项'}</span></div><p>${['定位阶段阻塞与业务影响','识别流程、重心及协同偏差','明确行动要求与计划完成日期','展示建议、涉及资源及决策边界'][i]}</p></button>`).join('');
 $('#ai-inline-summary').innerHTML=`<span class="ai-logo">✧ AI</span><p>${rows.length?`${range.label} · 全部类型共 <b>${rows.length}</b> 条诊断记录，涉及 <b>${new Set(rows.map(r=>r.chain)).size}</b> 个类目、<b>${new Set(rows.map(r=>r.department)).size}</b> 个部门、<b>${new Set(rows.map(r=>r.owner)).size}</b> 位链主；其中 <b class="red">${high}</b> 条为高危或 P0，建议优先核实并安排闭环。`:'所选条件下暂无诊断记录，可调整时间、类目、部门或链主。'}</p>`;
 $('#ai-inline-details').innerHTML=aiKinds.map(([kind,title],i)=>kind!==aiView.kind?'':`<section class="ai-detail-block" id="ai-detail-${kind}" aria-labelledby="ai-detail-title-${kind}"><div class="ai-detail-heading"><div class="titlegroup"><span class="ai-detail-index">0${i+1}</span><h3 id="ai-detail-title-${kind}">${title}</h3><span class="tag">${counts[kind]} ${kind==='block'?'个':'项'}</span></div><span class="note">${['按项目归集主要卡点','按期间记录统计','计划日期保留原始记录','仅为建议，需负责人确认'][i]}</span></div>${aiDetailTable(kind,rows.filter(r=>r.kind===kind))}</section>`).join('');
 $('#ai-inline-foot').textContent=`演示诊断 · 数据截至 ${aiCutoff} · 同一项目可出现在不同诊断类型中，条目数不等于项目数。历史行动项仅供复盘。`;
 $('#ai-reset').onclick=()=>{aiView.chain=aiView.department=aiView.owner='全部';renderInlineAI()};
 for(const [id,key] of [['ai-chain','chain'],['ai-department','department'],['ai-owner','owner']])$('#'+id).onchange=e=>{aiView[key]=pfControlValue(e.target);renderInlineAI()};
 if($('#ai-date'))$('#ai-date').onchange=e=>{const v=e.target.value;if(!e.target.checkValidity()||v<aiCoverageStart||v>aiCutoff){toast('请选择演示数据范围内的日期：08-01 至 09-16');renderInlineAI();return}aiView.date=v;aiView.month=v.slice(0,7);renderInlineAI()};
 if($('#ai-month'))$('#ai-month').onchange=e=>{const v=e.target.value;if(!e.target.checkValidity()||v<'2026-08'||v>'2026-09'){toast('请选择 2026 年 8 月或 9 月');renderInlineAI();return}aiView.month=v;aiView.date=v===aiCutoff.slice(0,7)?aiCutoff:v+'-01';renderInlineAI()};
}
renderAI=renderInlineAI;
document.addEventListener('click',e=>{const b=e.target.closest('[data-ai-period]');if(!b)return;aiView.mode=b.dataset.aiPeriod;renderInlineAI()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-ai-kind]');if(!b)return;aiView.kind=b.dataset.aiKind;renderInlineAI();$(`[data-ai-kind="${aiView.kind}"]`).focus({preventScroll:true})});
$('#refreshai').onclick=()=>{renderInlineAI();toast('已刷新当前筛选下的演示诊断，未调用真实 AI 服务')};
// The hidden global picker no longer controls the visible experience.
for(const id of moduleIds.filter(id=>id!=='ai'))localPeriods[id]=copyPeriod(globalPeriod);
// Sticky section navigation and scroll-aware selected state.
const navigationToolbar=document.createElement('div');navigationToolbar.className='navigation-toolbar';$('.jumpnav').before(navigationToolbar);navigationToolbar.append($('.jumpnav'));
const navigationActions=document.createElement('div');navigationActions.className='navigation-actions';navigationActions.append($('#rules'));navigationToolbar.append(navigationActions);




const jumpNavigation=$('.jumpnav'),jumpLinks=[...jumpNavigation.querySelectorAll('a')];
function updateNavigation(){const top=navigationToolbar.getBoundingClientRect().bottom+20;let current=moduleIds[0];for(const id of moduleIds){if($('#'+id).getBoundingClientRect().top<=top)current=id;else break}for(const link of jumpLinks){const selected=link.hash==='#'+current;link.classList.toggle('is-current',selected);if(selected)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')}const selected=jumpLinks.find(l=>l.hash==='#'+current);if(selected){const a=selected.getBoundingClientRect(),n=jumpNavigation.getBoundingClientRect();if(a.left<n.left||a.right>n.right)jumpNavigation.scrollLeft+=a.left-n.left-12}}
let navigationFrame=0;window.addEventListener('scroll',()=>{if(navigationFrame)return;navigationFrame=requestAnimationFrame(()=>{navigationFrame=0;updateNavigation()})},{passive:true});
new ResizeObserver(()=>{document.documentElement.style.setProperty('--dashboard-anchor-offset',(navigationToolbar.offsetHeight+$('.head').offsetHeight+18)+'px');updateNavigation()}).observe(navigationToolbar);
requestAnimationFrame(updateNavigation);

// Offline prototype: never report a DingTalk notification as delivered.
