let aiTasks={};try{const saved=JSON.parse(localStorage.getItem(aiTaskKey)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))aiTasks=saved}catch(_){}
const aiAssignees=[['林悦','清洁链链主'],['周铭','厨房链链主'],['陈嘉','环境链链主'],['许宁','个护 & 健康链链主'],['王磊','研发部'],['刘畅','品质部'],['唐琪','采购部'],['沈舟','项目部']];
function aiToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function aiTaskNotice(t){return `【产品链待办】${t.title}\n负责人：${t.assignee}\n完成日期：${t.due} 23:59（北京时间）\n优先级：${t.priority}\n类目 / 部门 / 链主：${t.chain} / ${t.department} / ${t.owner}\n处理要求：${t.notes}\n来源：${t.source}\n请核实问题并反馈处理结果。`}
function aiTaskSummary(t){return `<div class="ai-task-receipt"><div class="titlegroup"><span class="tag green">本地任务已保存</span><span class="note">${esc(t.id)}</span></div><h3>${esc(t.title)}</h3><p>指派给 <b>${esc(t.assignee)}</b> · ${esc(t.due)} 前完成 · ${esc(t.priority)}</p><p class="note">${t.notify?'钉钉通知：待发送（尚未接入服务）':'钉钉通知：未开启'} · 本地待处理</p></div>`}
function openAIRecord(id){const r=aiRecords.find(r=>r.id===id);if(!r)return;const t=aiTasks[id];modalModule=null;openModal('诊断详情',`<div class="ai-detail-hero"><span class="tag ${r.level==='高危'||r.level==='P0'?'red':'orange'}">${esc(r.level)} · ${esc(r.stage)}</span><h2>${esc(r.subject)}</h2><p>${esc(aiKinds.find(k=>k[0]===r.kind)[1])} · 记录于 ${r.date}</p></div><div class="detailgrid ai-context-grid">${[['类目',r.chain],['对应部门',r.department],['对应链主',r.owner],['证据来源',r.source]].map(([l,v])=>`<div class="detailitem"><small>${l}</small>${esc(v)}</div>`).join('')}</div><div class="aitext"><h3>诊断明细与业务影响</h3><p>${esc(r.problem)}</p></div><div class="aitext"><h3>建议行动</h3><p>${esc(r.action)}</p>${r.deadline?`<div class="source">原记录计划完成日期：${r.deadline}</div>`:''}</div>${t?aiTaskSummary(t):'<div class="notice">尚未创建处理任务，可指派人员并安排完成日期。</div>'}`,false,'演示诊断 · 人工核实后安排处理');$('#dialogactions').insertAdjacentHTML('afterbegin',`<button class="btn primary small" data-ai-handle="${id}">${t?'修改处理任务':'立即处理'}</button>`)}
function openAIHandle(id){const r=aiRecords.find(r=>r.id===id);if(!r)return;const old=aiTasks[id];const today=aiToday(),due=old?.due||(r.deadline&&r.deadline>=today?r.deadline:shiftDate(today,3));modalModule=null;
 openModal(old?'修改处理任务':'立即处理 · 指派任务',`<div class="ai-handle-context"><span class="ai-logo">✧ AI</span><div><strong>${esc(r.subject)}</strong><p>${esc(r.chain)} / ${esc(r.department)} / 链主 ${esc(r.owner)}</p></div><span class="tag">${esc(r.level)}</span></div><form id="ai-handle-form"><div class="ai-form-grid"><label class="ai-field ai-field-wide">任务名称 <input id="ai-task-title" required maxlength="100" value="${esc(old?.title||r.subject+' · 问题处理')}"></label><label class="ai-field">指派人员 <span class="note">演示人员</span><select id="ai-task-assignee" required><option value="">请选择负责人</option>${aiAssignees.map(([name,dept])=>`<option value="${name}" ${name===(old?.assignee||r.owner)?'selected':''}>${esc(name)} · ${esc(dept)}</option>`).join('')}</select></label><label class="ai-field">完成日期 <span class="note">北京时间，当天 23:59</span><input id="ai-task-due" type="date" required min="${today}" value="${due}"></label><label class="ai-field">优先级<select id="ai-task-priority">${['P0','P1','P2'].map(p=>`<option ${p===(old?.priority||(r.level==='高危'||r.level==='P0'?'P0':'P1'))?'selected':''}>${p}</option>`).join('')}</select></label><div class="ai-field ai-status-field">任务状态<span class="tag">待处理 · 本地演示</span></div><label class="ai-field ai-field-wide">处理要求<textarea id="ai-task-notes" required rows="3" maxlength="1000">${esc(old?.notes||r.action)}</textarea></label></div><div class="ai-ding-box"><div class="ai-ding-heading"><label><input id="ai-task-notify" type="checkbox" ${old?.notify===false?'':'checked'}> 钉钉通知负责人</label><span class="tag orange">未接入</span></div><p class="note">保存任务时生成通知待发记录；接入钉钉服务后才可真实通知。</p><div id="ai-ding-preview"><div class="ai-preview-title">通知内容预览</div><pre id="ai-notice-text"></pre></div></div><p id="ai-form-error" class="red" role="alert"></p></form>`,false,'明确负责人和交付日期，推动诊断闭环');
 $('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary small" type="submit" form="ai-handle-form" id="ai-save-task">保存任务并加入待发</button>');
 const form=$('#ai-handle-form');const values=()=>({recordId:id,title:$('#ai-task-title').value.trim(),assignee:$('#ai-task-assignee').value,due:$('#ai-task-due').value,priority:$('#ai-task-priority').value,notes:$('#ai-task-notes').value.trim(),notify:$('#ai-task-notify').checked,chain:r.chain,department:r.department,owner:r.owner,source:r.source});
 function preview(){const v=values();$('#ai-notice-text').textContent=aiTaskNotice(v);$('#ai-ding-preview').hidden=!v.notify;$('#ai-save-task').textContent=v.notify?'保存任务并加入待发':'保存本地任务'}form.addEventListener('input',preview);form.addEventListener('change',preview);preview();
 form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const v=values();if(!v.title||!v.notes||!aiAssignees.some(a=>a[0]===v.assignee)||v.due<aiToday()){$('#ai-form-error').textContent='请填写有效的任务、负责人、完成日期和处理要求。';return}const task={...v,id:old?.id||'AI-'+Date.now().toString(36).toUpperCase(),status:'local_pending',notificationStatus:v.notify?'pending_integration':'not_requested',createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};const updated={...aiTasks,[id]:task};try{localStorage.setItem(aiTaskKey,JSON.stringify(updated))}catch(_) {$('#ai-form-error').textContent='浏览器未允许保存本地数据，任务尚未保存。请允许本地存储后重试。';return}aiTasks=updated;renderInlineAI();openAITaskReceipt(task);};
}
function openAITaskReceipt(t){modalModule=null;openModal('处理任务已保存',`${aiTaskSummary(t)}<div class="aitext"><h3>处理要求</h3><p>${esc(t.notes)}</p></div>${t.notify?`<div class="ai-ding-box"><h3>钉钉通知 · 待发送</h3><p class="note">当前为离线演示，尚未发送任何钉钉消息。可复制通知内容手动发送。</p><pre>${esc(aiTaskNotice(t))}</pre></div>`:'<div class="notice">本次未开启钉钉通知。</div>'}`,false,'任务已保存于当前浏览器，刷新后可继续查看');$('#dialogactions').insertAdjacentHTML('afterbegin',`${t.notify?'<button class="btn soft small" id="ai-copy-notice">复制通知内容</button>':''}<button class="btn primary small" data-ai-handle="${t.recordId}">修改任务</button>`);if($('#ai-copy-notice'))$('#ai-copy-notice').onclick=async()=>{try{await navigator.clipboard.writeText(aiTaskNotice(t));toast('通知内容已复制，尚未发送')}catch(_){toast('复制未成功，请选中通知内容手动复制')}}}
document.addEventListener('click',e=>{const detail=e.target.closest('[data-ai-detail]'),handle=e.target.closest('[data-ai-handle]');if(detail)openAIRecord(detail.dataset.aiDetail);if(handle)openAIHandle(handle.dataset.aiHandle)});

// Use the same catalog asset wherever a concrete product is shown.
function hasProductSummary(body,name){
 const template=document.createElement('template');template.innerHTML=body;
 // Only recognize dedicated summaries; a product appearing in a related-items
 // table must not suppress the current product's own header.
 return [...template.content.querySelectorAll('[data-product-summary],.product-detail-image,.dp-detail-head,.cw-detail-top,.od-hero,.pc-hero,.md-hero,.nt-product')]
  .some(summary=>summary.textContent.includes(name));
}
const openModalWithProductImage=openModal;
openModal=function(title,body,drawer=false,sub=''){
 const name=Object.keys(productImages).find(n=>title.includes(n));
 if(name&&!hasProductSummary(body,name))body=`<div class="product-detail-image">${riskThumbnail(name)}<div><strong>${esc(name)}</strong></div></div>`+body;
 return openModalWithProductImage(title,body,drawer,sub);
};

// Targets use integer hundredths of 万元. Actual sales remain independent fixtures.
const salesTargetKey='product-chain-sales-targets-v1';
let salesTargetStore={version:1,years:{}};
function validTargetGrid(g,count=4){return Array.isArray(g)&&g.length===count&&g.every(row=>Array.isArray(row)&&row.length===12&&row.every(n=>Number.isSafeInteger(n)&&n>=0&&n<=100000000000))}
try{const saved=JSON.parse(localStorage.getItem(salesTargetKey)||'null');if(saved?.version===1&&saved.years){for(const y of [2025,2026])if(validTargetGrid(saved.years[y]?.months))salesTargetStore.years[y]=saved.years[y]}}catch(_){}
const targetClone=v=>JSON.parse(JSON.stringify(v));
function defaultTargetGrid(year){return baseSales.map(s=>allocate(Math.round(s.annual*(year===2025?.92:1)),Array(12).fill(1)).map(n=>n*100))}
function targetGrid(year,dimension=salesDimension){const chain=salesTargetStore.years[year]?.months||defaultTargetGrid(year);if(dimension==='chain')return chain;const saved=salesTargetStore.years[year]?.brandMonths,brand=saved&&saved.length<brands.length?[...saved,...Array.from({length:brands.length-saved.length},()=>Array(12).fill(0))]:saved;return validTargetGrid(brand,brands.length)&&sameCompanyTargets(chain,brand)?brand:defaultBrandTargets(chain)}
function targetSum(a){return a.reduce((n,v)=>n+v,0)}
function targetMoney(cents){return fmt(cents/100,2)}
function splitTarget(total,weights){const sum=targetSum(weights),ws=sum?weights:weights.map(()=>1),den=targetSum(ws),raw=ws.map(w=>total*w/den),a=raw.map(Math.floor);let left=total-targetSum(a);const order=raw.map((v,i)=>({i,f:v-a[i]})).sort((a,b)=>b.f-a.f||a.i-b.i);for(let i=0;i<left;i++)a[order[i%order.length].i]++;return a}
function targetTotal(grid,chain,indices){return chain<0?targetSum(grid.map(r=>targetSum(indices.map(m=>r[m])))):targetSum(indices.map(m=>grid[chain][m]))}
function targetIndexes(mode,value){return mode==='year'?Array.from({length:12},(_,i)=>i):mode==='quarter'?[0,1,2].map(i=>(value-1)*3+i):[value-1]}
const salesBeforeTargets=sales;
sales=function(){if(salesDimension==='brand')return brandSales();const p=periodFor(),grid=targetGrid(p.year),indices=targetIndexes(p.mode,p.value);return salesBeforeTargets().map((s,i)=>({...s,target:targetTotal(grid,i,indices)/100,annual:targetSum(grid[i])/100}))};
const totalSalesBeforeTargets=totalSales;
totalSales=function(){const p=periodFor(),grid=targetGrid(p.year);return {...totalSalesBeforeTargets(),target:targetTotal(grid,-1,targetIndexes(p.mode,p.value))/100,annual:targetTotal(grid,-1,targetIndexes('year',1))/100}};
function salesRate(p){return p.target>0?p.sale/p.target*100:null}
function salesRateLabel(p,decimals=1){const r=salesRate(p);return r===null?'未设目标':fmt(r,1)+'%'}
function salesRateBadge(p){return p.target>0?badge(salesRate(p)):'<span class="tag">未设目标</span>'}
const salesRenderBeforeTargets=renderSales;
renderSales=function(){salesRenderBeforeTargets();withPeriod('sales',()=>{
 const all=[totalSales(),...sales()],grid=targetGrid(periodFor().year);
 $('#salescards').innerHTML=all.map((p,i)=>`<article class="salescard ${i===0?'company':''}"><h3>${p.name}<button class="link" data-sales="${i-1}" aria-label="查看${p.name}销售明细">↗</button></h3><div class="metriclabel" style="margin-top:12px">${word()}销售额</div><div class="amount num">${fmt(p.sale,salesDimension==="brand"?2:0)}<span class="unit">万元</span></div><div class="salesrow target-card-goal"><span>${word()}目标</span><b class="num" data-sales-target="${i-1}">${fmt(p.target,2)}<span class="sales-money-unit">万元</span></b></div><div class="salesrow"><span>${word()}规模达成率</span>${salesRateBadge(p)}</div><div class="track"><i style="width:${p.target?Math.min(salesRate(p),100):0}%"></i></div><div class="salesrow"><span class="muted">${word()}目标差额</span><b class="num">${fmt(p.target-p.sale,2)}<span class="sales-money-unit">万元</span></b></div><div class="salesrow"><span class="muted">SKU 总数</span><b class="num">${p.sku} 个</b></div><div class="salesrow"><span class="muted">${word()}利润率</span><b class="num">${fmt(p.profit,1)}%</b></div><div class="salesrow"><span class="muted">年度目标</span><b class="num">${fmt(p.annual,2)}<span class="sales-money-unit">万元</span></b></div><div class="salesrow" title="年度目标－截至当前周期的年度累计销售額；正值为缺口，负值为超额"><span class="muted">年度销售额差额</span><b class="num">${fmt(p.annual-p.ytd,2)}<span class="sales-money-unit">万元</span></b></div>${spark(i)}</article>`).join('');
 $('#attainchart').innerHTML=sales().map(p=>{const r=salesRate(p);return `<div class="barrow"><span>${p.name}</span><div class="track"><i style="width:${r===null?0:Math.min(100,r)}%;background:var(--${r===null?'muted':status(r)})"></i></div><b class="${r===null?'muted':status(r)} num">${salesRateLabel(p)}</b></div>`}).join('');
 });};
// Allocate targets at the chain level, then aggregate company detail to avoid rounding drift.
salesDetail=bindDetail('sales',function(index,view='brand'){
 activeSales=index;salesView=view;const p=index<0?totalSales():sales()[index],labels=view==='brand'?brands:channels,weights=labels.map((_,i)=>labels.length-i+3),chainData=sales();
 const parts=chainData.map(s=>({target:splitTarget(Math.round(s.target*100),weights),gap:splitTarget(Math.abs(Math.round((s.annual-s.ytd)*100)),weights).map(n=>n*Math.sign(s.annual-s.ytd))}));
 const targets=labels.map((_,j)=>index<0?targetSum(parts.map(p=>p.target[j])):parts[index].target[j]),gaps=labels.map((_,j)=>index<0?targetSum(parts.map(p=>p.gap[j])):parts[index].gap[j]),actual=allocate(p.sale,weights),sku=allocate(p.sku,weights);
 const rows=labels.map((l,i)=>[l,sku[i],fmt(actual[i]),targetMoney(targets[i]),targets[i]?fmt(actual[i]/(targets[i]/100)*100,1)+'%':'未设目标',fmt(p.profit,1)+'%',targetMoney(gaps[i])]);
 openModal(p.name+' · 销售明细',`<div class="contextstrip"><div class="tabs"><button data-salesview="brand" class="${view==='brand'?'active':''}">分品牌</button><button data-salesview="channel" class="${view==='channel'?'active':''}">分渠道</button></div><span class="note">${periodLabel()} · 金额单位：万元</span></div><div class="notice">本期目标 ${pfMoneyYuan((p.target)*10000)}；品牌 / 渠道目标按现有演示占比分配，合计与所属链群及公司目标一致。</div><div class="tablewrap">${table([view==='brand'?'品牌':'销售渠道','SKU 总数',word()+'销售额',word()+'销售目标',word()+'规模达成率',word()+'利润率','年度销售额差额'],rows)}</div>`);
 
});

let targetEditor=null;
function targetDraftYear(){const e=targetEditor,y=e.year;if(!e.drafts[y])e.drafts[y]={chain:targetClone(targetGrid(y,'chain')),brand:targetClone(targetGrid(y,'brand'))};return e.drafts[y][e.dimension]}
function targetEditorColumns(){const e=targetEditor;if(e.mode==='year')return[{label:'年目标',mode:'year',value:1}];if(e.mode==='quarter')return [1,2,3,4].map(q=>({label:'Q'+q,mode:'quarter',value:q}));return [1,2,3].map(m=>({label:((e.quarter-1)*3+m)+' 月目标',mode:'month',value:(e.quarter-1)*3+m}))}
function applyTargetValue(chain,indices,cents){const grid=targetDraftYear();const chainAmounts=chain<0?splitTarget(cents,grid.map(row=>targetSum(indices.map(m=>row[m])))):null;for(const c of chain<0?grid.map((_,i)=>i):[chain]){const amounts=splitTarget(chain<0?chainAmounts[c]:cents,indices.map(m=>grid[c][m]));indices.forEach((m,i)=>grid[c][m]=amounts[i])}syncOtherTargetDimension(indices);targetEditor.dirty.add(targetEditor.year)}
function targetEditorRefreshValues(){const e=targetEditor,grid=targetDraftYear(),cols=targetEditorColumns();$$('#target-edit-table tbody tr').forEach((row,j)=>{const chain=j-1,yearTotal=targetTotal(grid,chain,targetIndexes('year',1)),oldTotal=targetTotal(targetGrid(e.year,e.dimension),chain,targetIndexes('year',1));row.querySelectorAll('input').forEach(input=>{input.value=(targetTotal(grid,chain,targetIndexes(input.dataset.targetMode,+input.dataset.targetValue))/100).toFixed(2)});const cells=row.querySelectorAll('td');if(e.mode==='month')cells[cols.length].textContent=targetMoney(targetTotal(grid,chain,targetIndexes('quarter',e.quarter)));cells[cells.length-2].textContent=targetMoney(yearTotal);const delta=cells[cells.length-1];delta.textContent=yearTotal===oldTotal?'—':(yearTotal>oldTotal?'+':'')+targetMoney(yearTotal-oldTotal);delta.className='num '+(yearTotal===oldTotal?'muted':'blue')});targetEditorSummary()}
function targetEditorTable(){const e=targetEditor,grid=targetDraftYear(),cols=targetEditorColumns();$('#target-edit-table').innerHTML=`<table><thead><tr><th>业务范围</th>${cols.map(c=>`<th>${c.label}（万元）</th>`).join('')}${e.mode==='month'?'<th>本季合计（万元）</th>':''}<th>全年合计（万元）</th><th>年度变化（万元）</th></tr></thead><tbody>${['公司整体',...salesNames(e.dimension)].map((name,j)=>{const chain=j-1,yearTotal=targetTotal(grid,chain,targetIndexes('year',1)),oldTotal=targetTotal(targetGrid(e.year,e.dimension),chain,targetIndexes('year',1));return `<tr class="${j===0?'target-company':''}"><th scope="row">${name}${j===0?'<small>公司总目标 · 两维度共用</small>':''}</th>${cols.map(c=>{const v=targetTotal(grid,chain,targetIndexes(c.mode,c.value));return `<td><input class="target-amount" type="number" min="0" max="1000000000" step="0.01" required inputmode="decimal" aria-label="${name}${c.label}" data-target-dimension="${e.dimension}" data-target-year=${e.year} data-target-chain="${chain}" data-target-mode="${c.mode}" data-target-value="${c.value}" value="${(v/100).toFixed(2)}"></td>`}).join('')}${e.mode==='month'?`<td class="num">${targetMoney(targetTotal(grid,chain,targetIndexes('quarter',e.quarter)))}</td>`:''}<td class="num" data-target-total="${chain}">${targetMoney(yearTotal)}</td><td class="num ${yearTotal===oldTotal?'muted':'blue'}">${yearTotal===oldTotal?'—':(yearTotal>oldTotal?'+':'')+targetMoney(yearTotal-oldTotal)}</td></tr>`}).join('')}</tbody></table>`;targetEditorSummary();}
function targetEditorSummary(){const grid=targetDraftYear(),sum=targetTotal(grid,-1,targetIndexes('year',1));$('#target-summary').innerHTML=`<span class="tag green">✓ 汇总一致</span><span>${targetEditor.year} 年公司目标 <b>${targetMoney(sum)}</b> 万元 = 四品链合计 = 五品牌合计</span><span class="note">月 → 季 → 年自动汇总，精确到 0.01 万元</span>`;$('#target-unsaved').textContent=targetEditor.dirty.size?'未保存修改：'+[...targetEditor.dirty].sort().join('、')+' 年':'已与当前看板目标对齐';}
function targetEditorControls(){const e=targetEditor;$('#target-editor-controls').innerHTML=`<div class="period-segment target-dimension-tabs" role="group" aria-label="目标配置维度">${[['chain','品链配置'],['brand','品牌配置']].map(([d,l])=>`<button type="button" data-target-dimension-tab="${d}" aria-pressed="${e.dimension===d}">${l}</button>`).join('')}</div><label>目标年份 <select id="target-year" aria-label="目标配置年份">${[2026,2025].map(y=>`<option ${y===e.year?'selected':''}>${y}</option>`).join('')}</select></label><div class="period-segment" role="group" aria-label="目标配置粒度">${[['month','月目标'],['quarter','季目标'],['year','年目标']].map(([m,l])=>`<button type="button" data-target-grain="${m}" aria-pressed="${e.mode===m}">${l}</button>`).join('')}</div>${e.mode==='month'?`<label>月份范围 <select id="target-quarter" aria-label="目标月份范围">${[1,2,3,4].map(q=>`<option value="${q}" ${q===e.quarter?'selected':''}>Q${q}</option>`).join('')}</select></label>`:''}<button type="button" class="link" id="target-revert">撤销本年修改</button>`;$('#target-year').onchange=ev=>{if(!targetEditorInputsValid()){ev.target.value=e.year;return}e.year=+ev.target.value;targetEditorTable()};if($('#target-quarter'))$('#target-quarter').onchange=ev=>{if(!targetEditorInputsValid()){ev.target.value=e.quarter;return}e.quarter=+ev.target.value;targetEditorTable()};$('#target-revert').onclick=()=>{e.drafts[e.year]={chain:targetClone(targetGrid(e.year,'chain')),brand:targetClone(targetGrid(e.year,'brand'))};e.dirty.delete(e.year);$('#target-form-error').textContent='';targetEditorTable()};}
function targetEditorInputsValid(){for(const input of $$('#target-edit-table input'))if(!input.checkValidity()){input.reportValidity();return false}return true}
function openSalesTargets(){const p=periodFor('sales');targetEditor={dimension:salesDimension,year:p.year,mode:p.mode,quarter:p.mode==='month'?Math.ceil(p.value/3):p.mode==='quarter'?p.value:3,drafts:{},dirty:new Set()};modalModule=null;openModal('销售目标配置',`<form id="target-config-form"><div class="target-config-intro"><strong>品链 / 品牌目标分别配置</strong><p>两个维度共用公司目标，各品链、各品牌可分别配置。修改总额时，另一维度按原占比同步；修改季 / 年目标按月分配，原目标为零时均分。</p></div><div id="target-editor-controls"></div><div id="target-edit-table" class="tablewrap"></div><div id="target-summary" aria-live="polite"></div><div class="target-config-foot"><span id="target-unsaved"></span><span>目标为 0 时显示“未设目标”，不计算达成率。</span></div><p class="note">可配置全年 12 个月；实际销售额仍按数据截止日统计。保存后联动销售卡片、目标图表、完成率、差额、明细。</p><p id="target-form-error" class="red" role="alert"></p></form>`,false,'金额单位：万元 · 保存于当前浏览器');$('#dialogactions').innerHTML='<button class="btn small" id="target-cancel">取消</button><button class="btn primary small" type="submit" form="target-config-form" id="target-save">保存并更新看板</button>';$('#target-cancel').onclick=closeModal;targetEditorControls();targetEditorTable();
 $('#target-edit-table').addEventListener('change',ev=>{const input=ev.target.closest('[data-target-chain]');if(!input||!input.isConnected||+input.dataset.targetYear!==targetEditor.year||input.dataset.targetDimension!==targetEditor.dimension)return;if(!input.checkValidity()){input.reportValidity();return}const cents=Math.round(Number(input.value)*100);if(cents===targetTotal(targetDraftYear(),+input.dataset.targetChain,targetIndexes(input.dataset.targetMode,+input.dataset.targetValue)))return;applyTargetValue(+input.dataset.targetChain,targetIndexes(input.dataset.targetMode,+input.dataset.targetValue),cents);$('#target-form-error').textContent='';targetEditorRefreshValues()});
 $('#target-editor-controls').addEventListener('click',ev=>{const b=ev.target.closest('[data-target-grain],[data-target-dimension-tab]');if(!b||!targetEditorInputsValid())return;if(b.hasAttribute('data-target-dimension-tab'))targetEditor.dimension=b.dataset.targetDimensionTab;else targetEditor.mode=b.dataset.targetGrain;targetEditorControls();targetEditorTable()});
 $('#target-config-form').onsubmit=ev=>{ev.preventDefault();if(!targetEditorInputsValid())return;const updated=targetClone(salesTargetStore);for(const y of targetEditor.dirty){const grid=targetEditor.drafts[y].chain,brandGrid=targetEditor.drafts[y].brand;if(!validTargetGrid(grid)||!validTargetGrid(brandGrid,5)||!sameCompanyTargets(grid,brandGrid)){$('#target-form-error').textContent='目标数据不合法，请检查金额。';return}updated.years[y]={months:grid,brandMonths:brandGrid,revision:(salesTargetStore.years[y]?.revision||0)+1,updatedAt:new Date().toISOString()}}try{localStorage.setItem(salesTargetKey,JSON.stringify(updated))}catch(_) {$('#target-form-error').textContent='浏览器未允许保存本地数据，配置尚未生效。';return}salesTargetStore=updated;renderSales();closeModal();toast(targetEditor.dirty.size?'销售目标已保存，卡片、图表、明细已同步':'目标与看板一致，无新增修改')};
}
const salesHeader=$('#sales .sectionhead');const salesActions=document.createElement('div');salesActions.className='sales-header-actions';salesActions.append(salesHeader.querySelector('.note'));salesActions.insertAdjacentHTML('beforeend','<button class="btn small" id="sales-config">⚙ 配置</button>');salesHeader.append(salesActions);$('#sales-config').onclick=openSalesTargets;
// Read-only view used by QA to verify all calendar and organization rollups.
window.dashboardSalesSnapshot=()=>withPeriod('sales',()=>({dimension:salesDimension,period:copyPeriod(periodFor()),records:targetClone([totalSales(),...sales()]),targets:targetClone(targetGrid(periodFor().year))}));

// Two views of the same company. Brand actuals are explicitly demo allocations.
let salesDimension='chain';
const brandMix=[[32,18,15,23,12],[18,15,14,28,25],[25,24,21,20,10],[16,22,26,20,16]].map(row=>brands.map((_,i)=>row[i]||[4,3,5,3,4][(i-5)%5]));
function salesNames(d=salesDimension){return d==='brand'?brands:chains}
function sameCompanyTargets(chain,brand){return Array.from({length:12},(_,m)=>targetSum(chain.map(r=>r[m]))===targetSum(brand.map(r=>r[m]))).every(Boolean)}
function defaultBrandTargets(chain){const rows=brands.map(()=>Array(12).fill(0));for(let m=0;m<12;m++)chain.forEach((row,c)=>splitTarget(row[m],brandMix[c]).forEach((v,b)=>rows[b][m]+=v));return rows}
function syncOtherTargetDimension(indices){const e=targetEditor,grid=targetDraftYear(),other=e.drafts[e.year][e.dimension==='brand'?'chain':'brand'];for(const m of indices){const values=splitTarget(targetSum(grid.map(row=>row[m])),other.map(row=>row[m]));other.forEach((row,i)=>row[m]=values[i])}}
function targetCrossMatrix(year,m){const rowGoals=targetGrid(year,'chain').map(r=>r[m]),remaining=targetGrid(year,'brand').map(r=>r[m]);return rowGoals.map((total,c)=>{const parts=c===3?[...remaining]:splitTarget(total,remaining);parts.forEach((v,b)=>remaining[b]-=v);return parts})}
// 原始月度样例是整月量；未结束月份仅累计到数据截止日，不提前计入未来业绩。
function salesMonthActual(chain,month,year){
 const start=year+'-'+String(month).padStart(2,'0')+'-01',end=iso(new Date(Date.UTC(year,month,0)));
 if(start>DATA_CUTOFF)return 0;
 const last=end<DATA_CUTOFF?end:DATA_CUTOFF;
 return Math.round(salesMonth(chain,month,year)*(aiFlowDayDiff(start,last)+1)/(aiFlowDayDiff(start,end)+1)*100)/100;
}
function salesCrossData(){
 const p=periodFor(),periodMonths=new Set(months(p)),yearMonths=new Set(months(p,true)),targetMonths=new Set(targetIndexes(p.mode,p.value)),raw=salesBeforeTargets();
 const cells=chains.map((_,c)=>brands.map((_,b)=>({name:brands[b],sku:splitTarget(raw[c].sku,brandMix[c])[b],sale:0,gross:0,ytd:0,target:0,annual:0})));
 for(let m=1;m<=12;m++){
  const targets=targetCrossMatrix(p.year,m-1);
  for(let c=0;c<4;c++){
   const actual=salesMonthActual(c,m,p.year),amounts=splitTarget(actual*100,brandMix[c]),margin=baseSales[c].profit+(m-9)*.08,grossWeights=brandMix[c].map((v,b)=>v*([1.07,.94,.9,1.03,1.08][b]||1)),grossSum=targetSum(grossWeights);
   for(let b=0;b<brands.length;b++){const cell=cells[c][b];if(periodMonths.has(m)){cell.sale+=amounts[b]/100;cell.gross+=actual*margin/100*grossWeights[b]/grossSum}if(yearMonths.has(m))cell.ytd+=amounts[b]/100;if(targetMonths.has(m-1))cell.target+=targets[c][b]/100;cell.annual+=targets[c][b]/100}
  }
 }
 return cells.map(row=>row.map(c=>({...c,sale:+c.sale.toFixed(2),ytd:+c.ytd.toFixed(2),target:+c.target.toFixed(2),annual:+c.annual.toFixed(2),profit:c.sale?c.gross/c.sale*100:0})));
}
function sumSalesCells(cells,name){const sum=k=>targetSum(cells.map(c=>c[k]));return{name,sku:sum('sku'),sale:+sum('sale').toFixed(2),ytd:+sum('ytd').toFixed(2),target:+sum('target').toFixed(2),annual:+sum('annual').toFixed(2),gross:sum('gross'),profit:sum('sale')?sum('gross')/sum('sale')*100:0}}
function brandSales(){const cells=salesCrossData();return brands.map((name,b)=>sumSalesCells(cells.map(row=>row[b]),name))}
const salesRenderWithTargets=renderSales;
renderSales=function(){salesRenderWithTargets();withPeriod('sales',()=>{
 $('#sales').dataset.dimension=salesDimension;
 $$('#sales-dimension-tabs button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.salesDimension===salesDimension)));
 $('#sales .sectionhead .sub').textContent=salesDimension==='brand'?'多品牌经营数据，定位每个品牌的经营表现':'从公司大盘，定位每一条业务链';
 const list=sales(),max=Math.max(1000,Math.ceil(Math.max(...list.flatMap(r=>[r.sale,r.target]))/1000)*1000),step=510/list.length;
 $('#sales .twocol .charthead h3').textContent=salesDimension==='brand'?'五大品牌销售额':'四大品链销售额';
 $('#saleschart').innerHTML=`<svg viewBox="0 0 580 200" role="img" aria-label="${salesDimension==='brand'?'品牌':'品链'}${word()}销售额与目标比较">${[0,max/4,max/2,max*3/4,max].map(v=>`<line x1="48" y1="${165-v/max*140}" x2="568" y2="${165-v/max*140}" stroke="#edf0f6"/><text x="38" y="${169-v/max*140}" text-anchor="end">${fmt(v)}</text>`).join('')}${list.map((r,i)=>{const x=58+step*(i+.5);return `<g class="chartclick" data-sales="${i}"><rect x="${x-25}" y="${165-r.target/max*140}" width="20" height="${r.target/max*140}" rx="3" fill="#e3e7fb"/><rect x="${x+3}" y="${165-r.sale/max*140}" width="20" height="${r.sale/max*140}" rx="3" fill="#7381fb"/><text x="${x+13}" y="${158-r.sale/max*140}" text-anchor="middle" style="fill:#6370da">${fmt(r.sale,r.sale%1?2:0)}</text><text x="${x}" y="191" text-anchor="middle">${r.name}</text></g>`}).join('')}</svg>`;
 });};
// Details share the same cross-tab as the cards, including brand targets.
salesDetail=bindDetail('sales',function(index,view){
 const dimension=salesDimension,opposite=dimension==='brand'?'chain':'brand';view=view||opposite;if(!['chain','brand','channel'].includes(view))view=opposite;if(view===dimension)view=opposite;
 activeSales=index;salesView=view;const parent=index<0?totalSales():sales()[index],cells=salesCrossData();let records;
 if(view==='channel'){
  records=salesChannelData(parent);
 }else if(dimension==='chain')records=brands.map((name,b)=>index<0?sumSalesCells(cells.map(row=>row[b]),name):{...cells[index][b],name});
 else records=chains.map((name,c)=>index<0?sumSalesCells(cells[c],name):{...cells[c][index],name});
 const label=view==='brand'?'品牌':view==='chain'?'品链':'销售渠道',headers=[label,'SKU 总数',word()+'销售额',word()+'销售目标（万元）',word()+'规模达成率',word()+'利润率','年度销售额差额（万元）'];
 const rows=records.map(r=>[r.name,r.sku,fmt(r.sale,2),fmt(r.target,2),salesRateLabel(r),fmt(r.profit,1)+'%',fmt(r.annual-r.ytd,2)]);
 openModal(parent.name+' · 销售明细',`<div class="contextstrip"><div class="tabs"><button data-salesview="${opposite}" class="${view===opposite?'active':''}">分${opposite==='chain'?'品链':'品牌'}</button><button data-salesview="channel" class="${view==='channel'?'active':''}">分渠道</button></div><span class="note">${periodLabel()} · 金额单位：万元</span></div><div class="notice">${dimension==='brand'?'品牌':'品链'}维度 · 本期目标 ${pfMoneyYuan((parent.target)*10000)}。${view==='channel'?'渠道为演示分配。':'品链 × 品牌交叉明细为演示分配。'}各项合计与当前卡片一致，利润率按毛利加权计算。</div><div class="tablewrap">${table(headers,rows)}</div>`);
});
