function dpPlan(source){
 const kind=source.kind;
 return kind==='project'?`1. ${source.dept}复核「${source.stage}」卡点：${source.cause}，形成问题清单及影响范围。\n2. ${source.owner}牵头确认修复方案、所需资源、交付物和节点日期；跨部门资源由对应部门负责人确认。\n3. 同步更新项目台账及后续依赖排期，按日跟进风险变化。\n4. 提交测试报告、评审结论和节点放行记录，由${dpDepartmentName()}负责人验证后解除卡点。`:kind==='quality'?`1. 核对退货与差评订单，按型号、批次、渠道分析原因，必要时暂停异常批次。\n2. 品质部与链主复现问题，输出纠正措施、测试计划和受影响库存清单。\n3. 小批量验证后再扩大修复，跟踪退货率及问题复发情况。\n4. 提交复测报告、整改前后对比、验收结论，验证通过后解除风险。`:kind==='channel'?`1. 分解渠道销售目标差额，核对价格、流量、转化、供货四类原因。\n2. 对照立项及上品计划确定供给缺口，负责人确认资源与上线排期。\n3. 小范围试行内容、组合销售或定价优化，控制预算并每日跟踪。\n4. 提交前后对比与复盘；任务验收后继续跟踪实际销售达成，不直接改写经营数据。`:kind==='process'?`1. 补齐「${source.name}」的缺失内容：${source.cause}。\n2. 责任人提交原始交付物、文档版本和对应项目关联。\n3. 复核完成条件及审阅记录，未验证的问题保持待办。\n4. 由${dpDepartmentName()}负责人验收并留存依据，纳入人员过程评分复盘。`:`1. 确认${source.name}的${source.cause||'经营改善'}问题与现状。\n2. 与品类链主确认可执行方案、责任人、交付时间及资源边界。\n3. 跟进策略试点效果并提交交付物和量化对比。\n4. 由独立验收人复核效果，未达标退回整改；经营指标仍以业务台账为准。`;
}
function dpTaskFor(source){return dpStore.tasks.find(t=>t.source.key===source.key&&t.state!=='已验收')}
function dpDispatch(source){
 const existing=dpTaskFor(source);if(existing){dpTaskDetail(existing.id);return}
 const period={...(source.period||periodFor())},date=bounds(period).cutoff;
 openModal('下发工作任务 · '+source.name,`<div class="dp-callout"><b>来源已关联</b> · ${esc(source.model||source.key)}<br>${esc(source.cause||'按经营建议执行')}<br>验收结果将回写来源风险，可在对应记录中跟进处理。</div><form class="dp-form" id="dp-dispatch-form"><label>责任人员<select name="owner" required>${people.map(n=>`<option ${n===source.owner?'selected':''}>${n}</option>`).join('')}</select></label><label>验收人员<select name="verifier" required><option>${dpDepartmentName()}负责人</option>${people.map(n=>`<option>${n}</option>`).join('')}</select></label><label>预计完成日期<input name="due" type="date" required min="${date}" value="${shiftDate(date,7)}"></label><label>优先级<select name="priority"><option ${source.level==='高危'?'selected':''}>P0</option><option ${source.level!=='高危'?'selected':''}>P1</option><option>P2</option></select></label><label class="full">处理方案（可编辑）<textarea name="plan" required minlength="15">${esc(dpPlan(source))}</textarea></label><label class="full">验收标准<textarea name="criteria" required minlength="10">交付物完整可复核，问题整改验证通过，相关依赖已确认；提供整改前后数据或节点放行记录。</textarea></label><label class="dp-check full"><input name="notify" type="checkbox" checked>生成钉钉通知内容（本地演示，提交后可复制给责任人）</label><p class="red full" id="dp-form-error" role="alert"></p></form>`,false,'责任人、期限、方案、验收标准一并下发');
 $('#dialogactions').innerHTML='<button class="btn" id="dp-cancel">取消</button><button class="btn primary" type="submit" form="dp-dispatch-form">确认下发</button>';$('#dp-cancel').onclick=closeModal;
 $('#dp-dispatch-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),owner=f.get('owner'),verifier=f.get('verifier');if(owner===verifier){$('#dp-form-error').textContent='执行人与验收人需为不同人员。';return}const id='DBS-'+Date.now().toString(36).toUpperCase(),audit=dpAudit('下发任务',id,'指派 '+owner+'；完成期限 '+f.get('due')),task={id,source:JSON.parse(JSON.stringify(source)),period,state:'待执行',owner,verifier,due:f.get('due'),priority:f.get('priority'),plan:f.get('plan').trim(),criteria:f.get('criteria').trim(),notify:f.has('notify')?'待复制通知':'不通知',createdDate:date,createdAt:audit.at,logs:[audit],evidence:'',closedDate:''};const next={...dpStore,tasks:[task,...dpStore.tasks],audit:[audit,...dpStore.audit]};if(dpSave(next)){renderDepartment();toast('任务已下发，可在来源记录中跟进');dpTaskDetail(id)}};
}
function dpTaskDetail(id){
 const t=dpStore.tasks.find(t=>t.id===id);if(!t)return;
 const steps=['待执行','执行中','待验收','已验收'],idx=steps.indexOf(t.state);
 openModal('DBS 任务 · '+t.source.name,`<div class="dp-toolbar-row"><span class="dp-pagebadge">${esc(t.id)}</span><span class="tag ${t.state==='已验收'?'green':t.state==='待验收'?'orange':''}">${esc(t.state)}</span></div><div class="dp-flow">${steps.map((s,i)=>`<span class="${i<=idx?'active':''}">${i+1} ${s}</span>${i<3?'→':''}`).join('')}</div><div class="dp-detail-grid">${[['来源',t.source.model||t.source.key],['责任人',t.owner],['验收人',t.verifier],['完成期限',t.due],['业务周期',periodLabel(t.period)],['通知状态',t.notify]].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="dp-callout"><b>执行方案</b><div style="white-space:pre-wrap">${esc(t.plan)}</div><br><b>验收标准</b><div style="white-space:pre-wrap">${esc(t.criteria)}</div></div>${t.state!=='已验收'?`<form class="dp-form" id="dp-task-form"><label class="full">${t.state==='待验收'?'复核意见':'执行进展 / 交付凭证（文档编号、附件地址或验证结果）'}<textarea name="evidence" required minlength="10" placeholder="请填写可核验的交付物、验证数据和结论">${t.state==='待验收'?'':esc(t.evidence||'')}</textarea></label>${t.state==='待验收'?`<label>实际整改日期<input type="date" name="actual" required max="${DATA_CUTOFF}" min="${t.createdDate}" value="${t.actualDate||DATA_CUTOFF}"></label><label>闭环验证日期<input type="date" name="closed" required max="${DATA_CUTOFF}" min="${t.createdDate}" value="${DATA_CUTOFF}"></label>${t.source.kind==='project'?`<label class="full">经确认的恢复计划上线日期<input name="recovery" type="date" required min="${DATA_CUTOFF}" value="${t.recoveryPlan||shiftDate(DATA_CUTOFF,7)}"></label>`:''}<label class="dp-check full"><input type="checkbox" name="verified" required>已复核交付物及验收标准，关键卡点解除、依赖放行条件满足。</label>`:''}<div class="red full" id="dp-task-error" role="alert"></div></form>`:`<div class="dp-callout">实际整改 ${esc(t.actualDate)} · 闭环验证 ${esc(t.closedDate)}<br>验收结论：${esc(t.review)}</div>`}${t.evidence?`<div class="dp-callout"><b>已提交凭证</b><p style="white-space:pre-wrap">${esc(t.evidence)}</p></div>`:''}<h3>完整操作轨迹</h3>${t.logs.map(l=>`<div class="dp-log"><b>${esc(l.action)}</b> · ${esc(l.actor)}<br>${esc(l.detail)}<br><small>${esc(new Date(l.at).toLocaleString('zh-CN'))}</small></div>`).join('')}`,false,'演示业务日 '+DATA_CUTOFF+' · 操作与验证均留痕');
 $('#dialogactions').innerHTML=`<button class="btn" id="dp-task-close">关闭</button><button class="btn" id="dp-copy-notice">复制钉钉通知</button>${t.state==='待执行'?'<button class="btn primary" id="dp-start-task">开始处理</button>':t.state==='执行中'?'<button class="btn primary" type="submit" form="dp-task-form">提交验收</button>':t.state==='待验收'?'<button class="btn" id="dp-reject-task">退回整改</button><button class="btn primary" type="submit" form="dp-task-form">验收通过并回写</button>':''}`;
 $('#dp-task-close').onclick=closeModal;
 $('#dp-copy-notice').onclick=async()=>{const notice=`【${dpDepartmentName()} DBS 工作通知】\n任务：${t.source.name}（${t.id}）\n责任人：${t.owner}\n预计完成日期：${t.due}\n验收人：${t.verifier}\n优先级：${t.priority}\n处理方案：\n${t.plan}\n验收标准：${t.criteria}\n来源：${t.source.model||t.source.key}`;try{await navigator.clipboard.writeText(notice);dpTaskMutate(t,'复制通知',{notify:'已复制，待人工发送'},'通知内容已复制，未实际发送');toast('已复制通知内容，请粘贴至钉钉发送')}catch(_){openModal('钉钉通知内容',`<textarea style="width:100%;height:330px" readonly>${esc(notice)}</textarea>`,false,'浏览器未允许自动复制，请选中全文复制。')}};
 if($('#dp-start-task'))$('#dp-start-task').onclick=()=>dpTaskMutate(t,'开始处理',{state:'执行中'},'责任人开始执行整改方案');
 if($('#dp-reject-task'))$('#dp-reject-task').onclick=()=>{const reason=$('#dp-task-form textarea').value.trim();if(reason.length<10){$('#dp-task-error').textContent='请填写至少 10 字的退回原因及补充要求。';return}dpTaskMutate(t,'退回整改',{state:'执行中',review:reason},reason)};
 if($('#dp-task-form'))$('#dp-task-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),evidence=f.get('evidence').trim();if(evidence.length<10){$('#dp-task-error').textContent='请补充可核验的内容，至少 10 字。';return}if(t.state==='执行中')dpTaskMutate(t,'提交验收',{state:'待验收',evidence,actualDate:DATA_CUTOFF},evidence);else if(t.state==='待验收'){if(f.get('closed')<f.get('actual')){$('#dp-task-error').textContent='闭环验证日期不能早于实际整改日期。';return}dpTaskMutate(t,'验收通过',{state:'已验收',review:evidence,actualDate:f.get('actual'),closedDate:f.get('closed'),recoveryPlan:f.get('recovery')||''},evidence+(f.get('recovery')?'；确认恢复排期 '+f.get('recovery'):''))}};
}
function dpTaskMutate(t,action,change,detail){const actor=action==='验收通过'||action==='退回整改'?t.verifier:t.owner,audit={...dpAudit(action,t.id,detail),actor},next={...dpStore,tasks:dpStore.tasks.map(x=>x.id===t.id?{...x,...change,logs:[audit,...x.logs]}:x),audit:[audit,...dpStore.audit]};if(dpSave(next)){renderAll();renderDepartment();dpTaskDetail(t.id)}}
function dpOpenRisk(source){
 const task=dpTaskFor(source),done=dpClosed(source.key),isProject=source.kind==='project';
 openModal(source.name+' · 风险与处理',`<div class="dp-detail-head">${riskThumbnail(source.name)}<div><span class="tag ${done?'green':'red'}">${done?'已验收闭环':esc(source.level||'待跟进')}</span><h2>${esc(source.name)}</h2><p>${esc(source.model)} · ${esc(chains[source.chain])} · ${esc(source.owner)}</p></div></div><div class="dp-detail-grid">${[['所属部门',source.dept||dpDepartmentName()],['责任链主',aiOwners[source.chain]],['当前风险',source.metric||source.cause],['发生 / 计划日期',source.date||bounds().cutoff],['关联链路',source.stage||source.kind],['当前处理状态',task?.state|| (done?'已验收':'待分配')]].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="dp-callout danger"><b>偏差与业务影响</b><br>${esc(source.cause)}${isProject?'<br>影响后续量产、上架及销售供给；具体延期归因以项目任务台账为依据。':''}</div><div class="dp-callout"><b>✧ AI 建议处理方案</b><div style="white-space:pre-wrap">${esc(dpPlan(source))}</div></div><p class="dp-notice">建议需负责人确认；验收前保留风险。来源 ${esc(source.key)}</p>`);
 $('#dialogactions').insertAdjacentHTML('afterbegin',`${isProject?'<button class="btn" id="dp-shared-project">项目全链路详情</button>':''}${source.kind==='quality'?'<button class="btn" id="dp-shared-quality">品质指标与趋势</button>':''}<button class="btn primary" id="dp-risk-dispatch">${task?'查看执行进展':done?'查看验收记录':'下发处理任务'}</button>`);
 $('#dp-risk-dispatch').onclick=()=>task?dpTaskDetail(task.id):done?dpTaskDetail(done.id):dpDispatch(source);
 if($('#dp-shared-project'))$('#dp-shared-project').onclick=()=>dpLegacy('projects','risk',()=>projectDetail(source.id));
 if($('#dp-shared-quality'))$('#dp-shared-quality').onclick=()=>dpLegacy('risk','risk',()=>riskDetail(0,source.id));
}
function dpPeriodHTML(id){const p=dpP(id),limit=p.year===2026?(p.mode==='month'?9:3):(p.mode==='month'?12:4);return`<div class="dp-period" data-dp-period="${id}"><div class="period-segment">${[['month','月'],['quarter','季'],['year','年']].map(([m,l])=>`<button type="button" data-dp-mode="${m}" aria-pressed="${m===p.mode}">${l}</button>`).join('')}</div><select data-dp-year aria-label="${id}统计年份">${[2026,2025].map(y=>`<option ${y===p.year?'selected':''}>${y}</option>`).join('')}</select>${p.mode==='year'?'':`<select data-dp-value aria-label="${id}统计周期">${Array.from({length:limit},(_,i)=>`<option value="${i+1}" ${p.value===i+1?'selected':''}>${p.mode==='month'?i+1+' 月':'Q'+(i+1)}</option>`).join('')}</select>`}${['global','ai'].includes(id)?'':`<button class="link" data-dp-follow="${id}" ${dpState.periods[id]?'':'disabled'}>${dpState.periods[id]?'恢复跟随':'跟随全局'}</button>`}</div>`}
function dpChangePeriod(id,key,value){const p={...(id==='global'?dpState.global:dpP(id))};if(key==='mode'){const m=p.mode==='month'?p.value:p.mode==='quarter'?p.value*3:9;p.mode=value;p.value=value==='year'?1:value==='quarter'?Math.ceil(m/3):m}else p[key]=+value;normalizePeriod(p);if(id==='global')dpState.global=p;else dpState.periods[id]=p;dpState.pages={};renderDepartment()}
function dpField(id,name,options,label){const value=dpState.filters[id]?.[name]??'all';return`<select ${name==='brand'?'multiple data-pf-multiple':''} data-dp-filter="${id}" data-field="${name}" aria-label="${label}"><option value="all">全部${label}</option>${options.map((n,i)=>`<option value="${i}" ${pfOptionSelected(value,i)?'selected':''}>${esc(n)}</option>`).join('')}</select>`}
function dpTabs(id,items,value){return`<div class="tabs">${items.map(([v,l])=>`<button data-dp-tab="${id}" data-value="${v}" class="${String(value)===String(v)?'active':''}">${l}</button>`).join('')}</div>`}
function dpMetric(label,value,unit='',note='',cls=''){return`<div class="dp-metric ${cls}"><small>${label}</small><strong>${value}<em>${unit}</em></strong><p>${note}</p></div>`}
function dpProduct(p){return`<div class="dp-product">${riskThumbnail(p.name)}<div><b>${esc(p.name)}</b><small>${esc(p.model)} · ${esc(typeof p.brand==='number'?brands[p.brand]:p.brand||chains[p.chain])}</small></div></div>`}
function dpBars(rows,value,maxValue){const max=maxValue||Math.max(1,...rows.map(r=>r[value]));return`<div class="dp-bars">${rows.map(r=>`<div class="dp-bar"><span>${esc(r.name)}</span><div class="dp-bar-track"><i style="width:${Math.min(100,Math.max(0,r[value]/max*100))}%;background:${r.color||'#8992f8'}"></i></div><b>${fmt(r[value],1)}${value==='rate'?'%':''}</b></div>`).join('')}</div>`}
function dpTable(headers,rows){return`<div class="dp-table">${table(headers,rows)}</div>`}



function dpPaginate(id,rows,size=10){const pages=Math.max(1,Math.ceil(rows.length/size)),page=Math.min(dpState.pages[id]||1,pages);dpState.pages[id]=page;return{rows:rows.slice((page-1)*size,page*size),html:listPager(rows.length,page,size,{attr:'data-dp-page',value:id,delta:'data-delta'})}}

// Shared launch facts keep KPI numerators and drilled product lists identical.
function newLaunchFacts(rows){
 const b=bounds();
 return rows.map(p=>{const actualLaunch=shiftDate(b.cutoff,1-p.days),plannedLaunch=shiftDate(actualLaunch,[0,-5,2,0,-3,1][p.id%6]),inPlan=plannedLaunch>=b.start&&plannedLaunch<=b.end,onTime=inPlan&&actualLaunch<=plannedLaunch&&actualLaunch<=b.cutoff;return {...p,actualLaunch,plannedLaunch,inPlan,onTime,salesSuccess:onTime&&p.sales>0}});
}
function newMetricsForRows(rows){const facts=newLaunchFacts(rows);return {planned:facts.filter(p=>p.inPlan).length,ontime:facts.filter(p=>p.onTime).length,sold:facts.filter(p=>p.salesSuccess).length}}
newMetrics=function(){return newMetricsForRows(newList())};
dpNewMetrics=function(chain=dpState.chain){return newMetricsForRows(productRows(true).filter(r=>chain==='all'||r.chain===+chain))};
const newProductSelection={metric:'all',channel:'all',page:1,key:''};
function productPager(page,total,kind,size=5){return listPager(total,page,size,{attr:'data-page',extra:{'data-product-page':kind}})}
function newSelectionLabel(metric,channel){return metric==='sold'?'按期上线且产生有效销售的产品':metric==='ontime'?'按期上线的产品':channel!=='all'?channels[+channel]+'渠道产品':'全部新品'}
function newMetricButton(key,title,n,denominator,active,scope='director'){
 return `<button type="button" class="newmetric new-linked-metric ${active===key?'selected':''}" data-new-metric="${key}" data-scope="${scope}" aria-pressed="${active===key}"><span>${title}</span><strong class="num">${denominator?fmt(n/denominator*100,1):'—'}<span class="unit">${denominator?'%':''}</span></strong><small class="muted">${key==='sold'?'按期上线且有销售':'按期上线'} ${n} / 本期计划 ${denominator}</small></button>`;
}
function newChannelChart(rows,selected='all',scope='director'){
 const totals=channels.map(ch=>rows.filter(p=>p.channel===ch).reduce((a,p)=>a+p.sales,0)),max=Math.max(1,...totals);
 return `<svg class="new-channel-chart" viewBox="0 0 360 150" role="group" aria-label="各渠道新品${word()}销售额，单位万元">${totals.map((n,i)=>`<g tabindex="0" role="button" data-new-channel="${i}" data-scope="${scope}" aria-pressed="${String(i)===selected}" aria-label="${channels[i]}，${pfMoneyYuan((n)*10000)}，点击查看产品"><rect x="${i*44+6}" y="0" width="42" height="150" rx="5" fill="${String(i)===selected?'#eeedff':'transparent'}"/><rect x="${i*44+16}" y="${112-n/max*80}" width="21" height="${Math.max(2,n/max*80)}" rx="3" fill="${String(i)===selected?'#6961f5':'#98a2fa'}"/><text x="${i*44+26}" y="${104-n/max*80}" text-anchor="middle">${fmt(n,1)}</text><text x="${i*44+26}" y="137" text-anchor="middle">${channels[i]}</text><title>${channels[i]} · ${pfMoneyYuan((n)*10000)} · ${rows.filter(p=>p.channel===channels[i]).length} 款</title></g>`).join('')}</svg>`;
}
function newLinkedRows(rows,metric,channel){return newLaunchFacts(rows).filter(p=>(metric==='all'||(metric==='sold'?p.salesSuccess:p.onTime))&&(channel==='all'||p.channel===channels[+channel]))}
// 新品主表由独立视图维护；旧全部新品弹窗仅保留给部门兼容入口。
renderNew=function(){withPeriod('new',nspRender)};
$('#newchain').onchange=()=>renderNew();
const allNewProductsState={chain:'all',channel:'all',page:1,key:''};
function openAllNewProducts(reset=true){withPeriod('new',()=>{
 const state=allNewProductsState,key=periodKey()+':'+bounds().cutoff;
 if(reset||state.key!==key)Object.assign(state,{chain:'all',channel:'all',page:1,key});
 const all=newLaunchFacts(productRows(true)),periodWord=word(),periodBounds=bounds(),headers=['产品名称','上线天数','所属品类 / 渠道','计划上线日期','实际上线日期',periodWord+'销售额','单品利润率','总退货率','销售状态','产品等级','操作'];
 openModal('新品专项管控 · 全部新品',`<div class="new-all-filters"><label>所属品类<select multiple data-pf-multiple id="new-all-chain" aria-label="全部新品所属品类"><option value="all">全部品类</option>${chains.map((name,i)=>`<option value="${i}" ${pfOptionSelected(state.chain,i)?'selected':''}>${name}</option>`).join('')}</select></label><label>渠道<select id="new-all-channel" aria-label="全部新品渠道"><option value="all">全部渠道</option>${channels.map((name,i)=>`<option value="${i}" ${state.channel===String(i)?'selected':''}>${name}</option>`).join('')}</select></label><button class="link" id="new-all-reset">重置筛选</button><span id="new-all-count" aria-live="polite"></span></div><div class="new-all-table" id="new-all-products-table"></div><div id="new-all-pager"></div>`,false,'当前新品模块统计周期内的全部新品');
 
 const productFilters=pfDefaults();pfMount($('.new-all-filters'),productFilters,()=>{state.page=1;fill()},['brand','attribute','productType']);const filtered=()=>all.filter(p=>pfMatches(p,productFilters)&&pfIncludes(state.chain,p.chain)&&(state.channel==='all'||p.channel===channels[+state.channel]));
 function fill(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/DRAWER_PAGE_SIZE));state.page=Math.max(1,Math.min(state.page,pages));$('#new-all-count').textContent=`筛选 ${rows.length} / 全部 ${all.length} 款新品`;
  $('#new-all-products-table').innerHTML=rows.length?table(headers,rows.slice((state.page-1)*DRAWER_PAGE_SIZE,state.page*DRAWER_PAGE_SIZE).map(p=>[titleProduct(p),p.days+' 天',chains[p.chain]+'<small>'+p.channel+'</small>',p.plannedLaunch,p.actualLaunch,fmt(p.sales,1)+' 万',fmt(p.profit,1)+'%',fmt(p.returnRate,1)+'%',`<span class="tag ${p.state==='整改'?'orange':'green'}">${p.state}</span>`,`<span class="tag">${dpLabel(p.grade)}</span>`,`<div class="new-all-actions"><button class="link" data-new-all-action="ai" data-id="${p.id}">✧ AI 新品评估</button><button class="link" data-new-all-action="trend" data-id="${p.id}">趋势图</button></div>`])):'<div class="dp-empty">当前品类和渠道下暂无新品，请调整筛选条件。<button class="link" id="new-all-empty-reset">重置筛选</button></div>';
  $('#new-all-pager').innerHTML=`${listPager(rows.length,state.page,DRAWER_PAGE_SIZE,{attr:"data-new-all-page"})}`;
  $('#new-all-empty-reset')?.addEventListener('click',resetFilters);
 }
 function resetFilters(){Object.assign(productFilters,pfDefaults());for(const s of $$('.new-all-filters [data-pf-filter]'))pfControlSet(s,'all');pfAttributeSync($('.new-all-filters'));state.chain='all';state.channel='all';state.page=1;pfControlSet($('#new-all-chain'),'all');$('#new-all-channel').value='all';fill()}
 for(const [id,field]of[['new-all-chain','chain'],['new-all-channel','channel']])$('#'+id).onchange=e=>{state[field]=pfControlValue(e.target);state.page=1;fill()};
 $('#new-all-reset').onclick=resetFilters;
 $('#new-all-pager').onclick=e=>{const button=e.target.closest('[data-new-all-page]');if(button&&!button.disabled){state.page=+button.dataset.newAllPage;fill()}};
 $('#new-all-products-table').onclick=e=>{const button=e.target.closest('[data-new-all-action]');if(!button)return;e.stopPropagation();if(button.dataset.newAllAction==='trend')openNewProductTrends(button.dataset.id,true);else{productDetail(true,button.dataset.id);$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn small" id="new-all-back">返回新品列表</button>');$('#new-all-back').onclick=()=>openAllNewProducts(false)}};
 
 fill();
})}
$('#newall').onclick=()=>openAllNewProducts();
const MATRIX_PRODUCT_PAGE_SIZE=9;
const matrixProductPage={page:1,key:''};
const renderMatrixBeforePagination=renderMatrix;
renderMatrix=function(){renderMatrixBeforePagination();withPeriod('matrix',()=>{
 const state=matrixProductPage,key=periodKey()+':'+matrixTab;if(state.key!==key){state.key=key;state.page=1}
 const rows=productRows(false).filter(p=>category(p)===matrixTab).sort((a,b)=>b.sales-a.sales);state.page=Math.min(Math.max(1,state.page),Math.max(1,Math.ceil(rows.length/MATRIX_PRODUCT_PAGE_SIZE)));
 $('#matrixtable').innerHTML=rows.length?table(['产品 / 品牌','渠道','近30天销售额','单品利润率','总退货率','操作'],rows.slice((state.page-1)*MATRIX_PRODUCT_PAGE_SIZE,state.page*MATRIX_PRODUCT_PAGE_SIZE).map(p=>[titleProduct(p),esc(p.channel),fmt(p.sales,1)+' 万',`<span class="${p.profit<config.profit?'orange':'green'}">${fmt(p.profit,1)}%</span>`,fmt(p.returnRate,1)+'%',`<button class="link" data-product="old,${p.id}">AI 策略</button><button class="link" data-matrix-trend="${p.id}">趋势图</button><button class="link" data-matrix-diagnosis="${p.id}">✧ AI 诊断</button>`])):'<div class="dp-empty">该类别暂无产品</div>';
 let pager=$('#matrix-product-pager');if(!pager){pager=document.createElement('div');pager.id='matrix-product-pager';$('#matrixtable').after(pager)}pager.innerHTML=productPager(state.page,rows.length,'matrix',MATRIX_PRODUCT_PAGE_SIZE);
 $('#matrix .matrixlist>.note').textContent='按销售额排序展示当前类别全部产品；ABCD 四类覆盖全部关键产品。';
})};
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-new-metric],[data-new-channel],[data-new-reset],[data-product-page]');if(!b)return;
 if(b.dataset.productPage){const state=b.dataset.productPage==='new'?newProductSelection:matrixProductPage;state.page=+b.dataset.page;(b.dataset.productPage==='new'?renderNew:renderMatrix)();return}
 const scope=b.dataset.scope||b.dataset.newReset;
 if(scope==='department'){
  const f=dpState.filters.new??={};f.metric=b.dataset.newMetric||'all';f.channel=b.dataset.newChannel??'all';dpState.pages.new=1;renderDepartment();$('#dp-new .dp-table')?.scrollIntoView({block:'nearest',behavior:'smooth'});
 }else{newProductSelection.metric=b.dataset.newMetric||'all';newProductSelection.channel=b.dataset.newChannel??'all';newProductSelection.page=1;renderNew();$('#newtable').scrollIntoView({block:'nearest',behavior:'smooth'})}
});
document.addEventListener('keydown',e=>{const b=e.target.closest('[data-new-channel]');if(b&&(e.key==='Enter'||e.key===' ')){e.preventDefault();b.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});

function mountEvidencePages(records){let page=1;const host=$('#dp-person-evidence'),pages=Math.max(1,Math.ceil(records.length/DRAWER_PAGE_SIZE));const render=()=>{host.innerHTML=records.length?dpTable(['记录','日期','扣分原因','操作'],records.slice((page-1)*DRAWER_PAGE_SIZE,page*DRAWER_PAGE_SIZE).map(d=>[esc(d.title),d.date,esc(d.issue),`<button class="link" data-dp-doc="${d.id}">查看依据</button>`])):'<div class="dp-empty">当前周期无扣分记录</div>';host.insertAdjacentHTML('beforeend',`${listPager(records.length,page,DRAWER_PAGE_SIZE,{attr:"data-evidence-page"})}`)};host.addEventListener('click',e=>{const b=e.target.closest('[data-evidence-page]');if(b){page=Math.max(1,Math.min(pages,+b.dataset.evidencePage));render()}});render()}

// Shared four-quadrant view uses the same inclusive boundaries as the lists.
function fourQuadrantSVG(rows,department=false){
 const left=44,right=444,top=28,bottom=223,maxX=Math.max(140,config.high*1.4,...rows.map(p=>p.sales*1.1)),minY=Math.min(0,...rows.map(p=>p.profit*1.1)),maxY=Math.max(26,config.profit*1.5,...rows.map(p=>p.profit*1.1)),x=v=>left+v/maxX*(right-left),y=v=>bottom-(v-minY)/(maxY-minY)*(bottom-top),split=x(config.high),mid=y(config.profit),colors={A:'#38b190',B:'#eab45e',C:'#718bf1',D:'#e2848d'};
 return `<svg viewBox="0 0 460 260" class="${department?'dp-scatter':''}" role="img" aria-label="关键产品 ABCD 四象限：销售额 ${config.high} 万元、利润率 ${config.profit}% 为分界"><text x="44" y="15">单品利润率（%）</text>${[['C',left,top,split-left,mid-top,'#f0f6ff'],['D',left,mid,split-left,bottom-mid,'#fff3f3'],['A',split,top,right-split,mid-top,'#eef9f5'],['B',split,mid,right-split,bottom-mid,'#fff9ed']].map(([g,a,b,w,h,color])=>`<rect data-quadrant="${g}" x="${a}" y="${b}" width="${w}" height="${h}" fill="${color}"/>`).join('')}<line x1="${split}" x2="${split}" y1="${top}" y2="${bottom}" stroke="#c7cedf" stroke-dasharray="4 4"/><line x1="${left}" x2="${right}" y1="${mid}" y2="${mid}" stroke="#c7cedf" stroke-dasharray="4 4"/><text x="${left+8}" y="47">C 低销高利</text><text x="${split+10}" y="47">A 高销高利</text><text x="${left+8}" y="${mid+19}">D 低销低利</text><text x="${split+10}" y="${mid+19}">B 高销低利</text>${[0,config.high,maxX].map(v=>`<text x="${x(v)}" y="245" text-anchor="middle">${fmt(v)}</text>`).join('')}${[...new Set([minY,0,config.profit,maxY])].map(v=>`<text x="35" y="${y(v)+4}" text-anchor="end">${fmt(v,1)}%</text>`).join('')}${rows.map(p=>`<circle ${department?`data-dp-scatter="${p.id}" data-grade="${category(p)}"`:`class="chartclick" data-product="old,${p.id}"`} cx="${x(p.sales)}" cy="${y(p.profit)}" r="5" fill="${colors[category(p)]}" fill-opacity=".8"><title>${esc(p.name)}：${pfMoneyYuan((p.sales)*10000)} / 利润率 ${p.profit}% · ${category(p)} 类</title></circle>`).join('')}</svg>`;
}
const renderMatrixBeforeFourQuadrants=renderMatrix;
renderMatrix=function(){renderMatrixBeforeFourQuadrants();withPeriod('matrix',()=>{$('#matrixchart').innerHTML=fourQuadrantSVG(productRows(false))})};

const dpRiskTitles=['上品计划预警','立项规划预警','项目延期红灯','高危品质风险','渠道销售偏差','工作流程预警'];
const dpRiskCache=new Map(),dpProductCache=new Map();
function dpRemember(r,module){const key=module+'|'+r.key;r.period={...dpP(module)};dpRiskCache.set(key,r);return key}
function dpRiskAction(r,module='risk'){return`<button class="link" data-dp-risk="${esc(dpRemember(r,module))}" data-module="${module}">查看详情</button><button class="link" data-dp-assign="${esc(dpRemember(r,module))}" data-module="${module}">${dpTaskFor(r)?'跟进任务':'立即处理'}</button>`}
function dpRenderRisk(){const lists=dpRiskLists();return`<div class="dp-risk-grid">${lists.map((rows,i)=>`<article class="dp-risk-card"><div class="dp-risk-head"><h3><span class="red">●</span> ${dpRiskTitles[i]}</h3><button class="link" data-dp-risk-all="${i}">全部 ${rows.length} ›</button></div>${rows.slice(0,6).map((r,j)=>`<button class="dp-risk-item" data-dp-risk="${esc(dpRemember(r,'risk'))}" data-module="risk"><span class="dp-rank">${String(j+1).padStart(2,'0')}</span>${riskThumbnail(r.name)}<span class="dp-risk-name"><b>${esc(r.name)}</b><small>${esc(dpState.role==='owner'?r.model:chains[r.chain])} · ${esc(r.owner)}</small></span><strong>${esc(r.metric)}</strong></button>`).join('')||'<div class="dp-empty">本期无未闭环风险</div>'}</article>`).join('')}</div>`}
function dpRiskAll(index){let q='',level='all',sort='risk';const all=dpRiskLists()[index];openModal(dpRiskTitles[index]+' · 完整榜单',`<div class="dp-filter"><input id="dp-risk-search" placeholder="产品 / 型号 / 责任人"><select id="dp-risk-level"><option value="all">全部风险等级</option><option>高危</option><option>中风险</option></select><select id="dp-risk-sort"><option value="risk">风险等级优先</option><option value="date">发生日期倒序</option></select></div><div id="dp-risk-list"></div>`);const render=()=>{const rows=all.filter(r=>(level==='all'||r.level===level)&&(!q||(r.name+r.model+r.owner).includes(q))).sort((a,b)=>sort==='date'?b.date.localeCompare(a.date):(b.level==='高危')-(a.level==='高危')),headers=['风险对象','品类 / 责任人','风险等级','偏差','根因说明','执行状态','操作'],data=rows.map(r=>[dpProduct(r),chains[r.chain]+' / '+r.owner,`<span class="tag red">${r.level}</span>`,esc(r.metric),esc(r.cause),dpTaskFor(r)?.state||'待分配',dpRiskAction(r)]);$('#dp-risk-list').innerHTML=dpTable(headers,data);modalHeaders=headers;modalData=data};render();$('#dp-risk-search').oninput=e=>{q=e.target.value.trim();render()};$('#dp-risk-level').onchange=e=>{level=e.target.value;render()};$('#dp-risk-sort').onchange=e=>{sort=e.target.value;render()};}
function dpRenderAI(){
 const risks=[...dpStore.workItems.filter(r=>dpInScope(r)&&r.period.year===periodFor().year&&r.date<=bounds().cutoff&&!dpClosed(r.key)),...dpUniqueRisks()],blocks=risks.filter(r=>r.kind==='project'),today=risks.filter(r=>(dpStore.priorities[r.key]||(r.level==='高危'?'P0':'P1'))==='P0').slice(0,6),week=risks.slice(0,12),tab=dpState.tab.ai;
 const cards=[['blocks','全品类核心卡点',blocks.length,'高危 '+blocks.filter(r=>r.level==='高危').length+' 项'],['today','今日关键工作',today.length,'P0 优先 · 按风险排序'],['week','本周关键工作',week.length,'关联责任链主与完成期限'],['advice','AI 管理建议',4,'跨部门协同 · 产品结构优化']];
 const rows=tab==='blocks'?blocks:tab==='today'?today:week,page=dpPaginate('ai-'+tab,rows,12);
 return`<div class="dp-grid">${cards.map(([key,title,n,note])=>`<button class="dp-metric ${tab===key?'active':''}" data-dp-tab="ai" data-value="${key}"><small>${title}</small><strong class="${key==='blocks'?'red':'blue'}">${n}<em>项</em></strong><p>${note}</p></button>`).join('')}</div><div class="dp-ai-strip"><span class="ai-logo">✧ AI</span><div><strong>${blocks.length} 个项目存在关键卡点，优先处理红灯项目及高危品质问题。</strong><br>选择工作项查看依据、调整方案并下发；已派发事项可直接跟进执行及验收。</div></div>${tab==='advice'?`<div class="dp-expand">${[['跨部门协同','产品部与品质、采购共同确认关键节点放行，明确外部交付时间与验收资料。','project'],['品类资源优先级','优先安排高危项目与渠道供给不足项；跨部门资源需对方负责人确认。','channel'],['产品结构优化','A 类产品保供给，B 类拆解利润，C 类限额试投，D 类先评估整改价值。','product'],['风险闭环机制','将缺失交付物、未验收事项纳入个人清单；凭证、结论齐全后再闭环。','process']].map(([title,body,kind],i)=>{const source=risks.find(r=>r.kind===kind)||risks[i]||{key:'advice:'+periodKey()+':'+i,kind,name:title,model:'AI-'+i,chain:0,owner:'林悦',cause:body};return`<details ${i===0?'open':''}><summary>${title}</summary><p>现状：${esc(source.cause)}<br>建议：${body}<br>预期收益：减少等待与重复返工，缩短问题关闭时间。<br>执行边界：先确认资源与验收条件，不自动调整部门资源。</p>${dpRiskAction(source,'ai')}</details>`}).join('')}</div>`:dpTable(['优先级','工作 / 核心卡点','责任部门','责任链主','关键链路与影响','执行状态','操作'],page.rows.map(r=>[`<span class="tag ${r.level==='高危'?'red':'orange'}">${dpStore.priorities[r.key]||(r.level==='高危'?'P0':'P1')}</span>`,dpProduct(r),esc(r.dept),esc(aiOwners[r.chain]),`<b class="dp-stage-name">${esc(r.stage||'产品经营 / 工作交付')}</b><small>${esc(r.cause)}</small>`,dpTaskFor(r)?.state||'待下发',dpRiskAction(r,'ai')+`<button class="link" data-dp-work-edit="${esc(dpRemember(r,'ai'))}">调整工作</button>`]))}${tab==='advice'?'':page.html}<p class="dp-footnote">${periodLabel()} · 诊断来自当前周期项目、风险及过程记录；同一项目按编号去重。</p>`;
}
function dpRenderManagement(){
 const scores=dpScoreRows(),dev=dpDeviations(),open=dev.filter(r=>!dpClosed(r.key)),tab=dpState.tab.management,docs=dpDocuments(),dType=+dpState.tab.doc;
 let content='';
 if(tab==='score'){
  const f=dpState.filters.management||{},filtered=scores.filter(r=>f.role===undefined||f.role==='all'||r.role===['品类链主','产品专员'][+f.role]);
  const h=['排名','姓名 / 岗位','所属品类','综合得分','结果指标','过程指标','AI 风险标签','操作'],rows=filtered.map((r,i)=>[i+1,`<b>${r.name}</b><small>${r.role}</small>`,chains[r.chain],`<strong class="${r.improve?'red':'blue'}">${fmt(r.total,1)}</strong>`,fmt(r.result,1),fmt(r.process,1),r.improve?'<span class="tag red">待改进 · 后 20%</span>':r.issues?'<span class="tag orange">过程资料待完善</span>':'—',`<button class="link" data-dp-person="${r.name}">查看个人明细</button>`]);const scorePage=dpPaginate('management-score',rows,5);
  content=`<div class="dp-grid">${dpMetric('部门综合平均分',fmt(dpSum(scores,'total')/Math.max(1,scores.length),1),'分','结果 + 过程加权')}${dpMetric('结果指标平均分',fmt(dpSum(scores,'result')/Math.max(1,scores.length),1),'分','权重 '+dpSum(dpStore.weights.slice(0,4).map(v=>({v})),'v')+'%')}${dpMetric('过程指标平均分',fmt(dpSum(scores,'process')/Math.max(1,scores.length),1),'分','按交付记录计分')}${dpMetric('待改进人员',scores.filter(r=>r.improve).length,'人','末位 20% 重点辅导')}</div><div class="dp-toolbar-row"><div class="dp-filter">${dpField('management','role',['品类链主','产品专员'],'岗位')}</div><button class="link" id="dp-score-config">评分规则配置</button></div>${dpTable(h,scorePage.rows)}${scorePage.html}`;
 }else if(tab==='deviation'){
  const f=dpState.filters.management||{},rows=dev.filter(r=>f.state===undefined||f.state==='all'||(+f.state===0?!dpClosed(r.key):!!dpClosed(r.key))),page=dpPaginate('deviation',rows),h=['偏差类型','偏差说明','品类 / 责任人','发生日期','逾期天数','整改期限','当前状态','操作'],cells=r=>[r.type,esc(r.cause)+'<small>'+esc(r.model)+'</small>',chains[r.chain]+' / '+r.owner,r.date,Math.max(0,Math.floor((Date.parse(bounds().cutoff)-Date.parse(r.date))/86400000)),dpTaskFor(r)?.due||'未指派',dpClosed(r.key)?'<span class="tag green">已验收</span>':dpTaskFor(r)?.state||'待分配',dpRiskAction(r,'management')];
  content=`<div class="dp-grid">${dpMetric('识别偏差',dev.length,'条')}${dpMetric('闭环率',dpPct(dev.length-open.length,dev.length))}${dpMetric('缺失 / 不完整',dev.filter(r=>r.type.includes('缺失')||r.type.includes('不完整')).length,'条')}${dpMetric('未闭环',open.length,'条')}</div><div class="dp-chart-panel"><h3>近三个月工作偏差趋势</h3>${dpBars(Array.from({length:3},(_,i)=>{const m=Math.max(1,+bounds().cutoff.slice(5,7)-2+i),p={year:periodFor().year,mode:'month',value:m};return{name:m+' 月',count:dpDocuments(p).filter(r=>r.issue!=='无偏差').length}}),'count')}</div><div class="dp-filter">${dpField('management','state',['未闭环','已验收'],'状态')}</div>${dpTable(h,page.rows.map(cells))}${page.html}`;
 }else{
  const selected=docs.filter(r=>r.type===dType),page=dpPaginate('documents',selected),h=['文档名称','责任人','所属品类','应交日期','提交状态','完整性','审阅 / 验收','操作'],cells=r=>[esc(r.title)+'<small>'+r.id+'</small>',r.owner,chains[r.chain],r.date,r.state,r.complete?'完整':'待补齐',r.approved?'已审阅':'待验证',`<button class="link" data-dp-doc="${r.id}">查看记录</button>`];
  content=`<div class="dp-docs">${dpDocNames.map((name,i)=>{const a=docs.filter(r=>r.type===i);return`<button class="dp-doc ${i===dType?'active':''}" data-dp-tab="doc" data-value="${i}"><span>${name}</span><b>${a.filter(r=>r.state!=='缺交').length}<small> / ${a.length} 应交</small></b><small>按期率 ${dpPct(a.filter(r=>r.state==='按期提交').length,a.length)}</small></button>`}).join('')}</div>${dpTable(h,page.rows.map(cells))}${page.html}`;
 }
 return dpTabs('management',[['score','人员量化打分'],['deviation','工作偏差复盘'],['documents','过程文档大盘']],tab)+content;
}
function dpPersonDetail(name){const r=dpScoreRows().find(r=>r.name===name),labels=['销售达成','新品上线','上品 / 立项','盈利质量','日报周报','项目闭环','流程合规','文档完整'];if(!r)return;const scorePeriod={...periodFor()},scoreKey=periodKey()+':'+name;const points=r.factors.map((v,i)=>{const a=i*Math.PI/4-Math.PI/2;return`${110+Math.cos(a)*70*v},${90+Math.sin(a)*70*v}`}).join(' ');openModal(name+' · 量化得分与改进',`<div class="dp-detail-head"><div><h2>${name} <span class="blue">${fmt(r.total,1)} 分</span></h2><p>${r.role} · ${chains[r.chain]} · ${periodLabel()}</p></div></div><div class="dp-chart-grid"><svg class="dp-person-radar" viewBox="0 0 220 190" aria-label="个人八项指标达成雷达">${[.5,1].map(s=>`<polygon points="${r.factors.map((_,i)=>`${110+Math.cos(i*Math.PI/4-Math.PI/2)*70*s},${90+Math.sin(i*Math.PI/4-Math.PI/2)*70*s}`).join(' ')}" fill="none" stroke="#e3e6f5"/>`).join('')}<polygon points="${points}" fill="#7773f333" stroke="#857df5"/>${labels.map((l,i)=>`<text x="${110+Math.cos(i*Math.PI/4-Math.PI/2)*87}" y="${94+Math.sin(i*Math.PI/4-Math.PI/2)*87}" text-anchor="middle" font-size="9" fill="#8994ad">${l}</text>`).join('')}</svg><div class="dp-callout"><b>AI 辅导建议</b><p>优先补齐 ${r.issues} 条过程偏差；尚未验收的交付需完善审阅凭证。将较低分维度拆解到每周工作清单。</p>${r.override?'<small>人工修订：'+esc(r.override.reason)+'</small>':''}</div></div>${dpTable(['评分项','权重','达成折算','得分'],labels.map((l,i)=>[l,dpStore.weights[i]+'%',fmt(r.factors[i]*100,1)+'%',fmt(r.scores[i],1)]))}<h3>扣分依据 / 原始记录</h3><div id="dp-person-evidence"></div><form class="dp-form" id="dp-score-override"><label>人工复核综合分<input name="score" type="number" min="0" max="100" step="0.1" required value="${r.total.toFixed(1)}"></label><label>修订原因<input name="reason" required minlength="5" placeholder="填写依据，保留原始分项"></label></form>`);mountEvidencePages(r.docs.filter(d=>d.issue!=='无偏差'));$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn" type="submit" form="dp-score-override">保存复核结果</button><button class="btn primary" id="dp-person-task">下发改进任务</button>');$('#dp-person-task').onclick=()=>dpDispatch({key:'person:'+periodKey(scorePeriod)+':'+name,period:scorePeriod,kind:'process',name:name+'过程改进',model:'SCORE-'+people.indexOf(name),chain:r.chain,owner:name,cause:'补齐过程交付与验收记录',dept:dpDepartmentName()});$('#dp-score-override').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),audit=dpAudit('评分修订',name,f.get('reason'));if(dpSave({...dpStore,overrides:{...dpStore.overrides,[scoreKey]:{score:+f.get('score'),reason:f.get('reason'),at:audit.at}},audit:[audit,...dpStore.audit]})){renderDepartment();closeModal();toast('复核分数已保存，原始分项与修订依据均保留')}}}
function dpScoreConfig(){const labels=['销售达成','新品上线','上品 / 立项','盈利质量','日报周报','项目闭环','流程合规','文档完整'];openModal('人员评分规则',`<p class="dp-notice">总权重需为 100%；修改保留审计记录，所有人员同步重算。销售达成低于 80% 该项不得分；未验证闭环记录不计闭环得分。</p><form id="dp-weights-form" class="dp-form">${labels.map((l,i)=>`<label>${l}权重（%）<input name="w${i}" type="number" min="0" max="100" step="1" value="${dpStore.weights[i]}" required></label>`).join('')}<label class="full">调整依据<input name="reason" required minlength="5"></label><p class="red full" id="dp-weights-error"></p></form>`);$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary" type="submit" form="dp-weights-form">保存并重新评分</button>');$('#dp-weights-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),weights=labels.map((_,i)=>+f.get('w'+i));if(weights.reduce((a,b)=>a+b,0)!==100){$('#dp-weights-error').textContent='各项权重合计必须为 100%。';return}const audit=dpAudit('评分规则调整','人员评分',f.get('reason')+'；'+weights.join('/'));if(dpSave({...dpStore,weights,audit:[audit,...dpStore.audit]})){closeModal();renderDepartment();toast('评分规则已生效')}}}
function dpDocDetail(id){const r=dpWith('management',()=>dpDocuments().find(d=>d.id===id));if(!r)return;const issue=dpWith('management',()=>dpDeviations().find(d=>d.model===id));openModal(r.title+' · 文档记录',`<div class="dp-detail-grid">${[['记录编号',r.id],['责任人',r.owner],['应交日期',r.date],['文档类型',dpDocNames[r.type]],['提交状态',r.state],['审阅结论',r.approved?'已审阅':'待核验']].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="dp-callout"><b>内容预览</b><p>${r.state==='缺交'?'该应交记录尚未提交，需责任人补交。':`本期围绕${esc(names[r.chain][r.type%6])}推进产品需求、项目排期与渠道协同；已梳理关键节点，并同步相关责任部门。`}</p><p>交付物：${r.complete?'需求确认清单、项目跟进台账（演示记录）':'关键结论或附件缺失'}</p><p>AI 审阅：${esc(r.issue)}</p></div><p class="dp-notice">预览为需求演示内容；真实原文、附件及权限需接入文档系统。</p>${issue?dpRiskAction(issue,'management'):''}`)}
function dpRenderSales(){const dim=dpState.tab.sales,f=dpState.filters.sales||{},rows=dpSalesRows(dim,f.brand||'all'),total=sumSalesCells(dpSalesCells().filter(r=>pfIncludes(f.brand,r.brandIndex)),'产品部整体'),h=[dim==='chain'?'品链':dim==='brand'?'品牌':'渠道','SKU 总数',word()+'销售额（万元）',word()+'目标（万元）','规模达成率','利润率','年度销售额差额（万元）',word()+'立项目标 / 实际',word()+'上品目标 / 实际','年度立项目标 / 完成','年度上品目标 / 完成','操作'];
 const pair=(r,stages)=>{if(dim==='brand')return null;return lifeSumRows(stages.flatMap(s=>dim==='channel'?[dpLifeChannels(s)[r.index]]:dpLifeRows(s).filter(x=>x.chain===r.index)))};
 const data=rows.map(r=>{const a=pair(r,[2,3]),b=pair(r,[0,1]);return[r.name,r.sku,fmt(r.sale,2),fmt(r.target,2),r.target?badge(r.sale/r.target*100):'未设目标',fmt(r.profit,1)+'%',fmt(r.annual-r.ytd,2),a?a.target+' / '+a.actual+'<small>达成 '+dpPct(a.actual,a.target)+'</small>':'按品链查看',b?b.target+' / '+b.actual+'<small>达成 '+dpPct(b.actual,b.target)+'</small>':'按品链查看',a?a.yearTarget+' / '+a.yearActual+'<small>达成 '+dpPct(a.yearActual,a.yearTarget)+'</small>':'—',b?b.yearTarget+' / '+b.yearActual+'<small>达成 '+dpPct(b.yearActual,b.yearTarget)+'</small>':'—',`<button class="link" data-dp-sales-detail="${r.index}" data-dim="${dim}">查看明细</button>`]});
 return`<div class="dp-toolbar-row">${dpTabs('sales',[['chain','品链维度'],['brand','品牌维度'],['channel','渠道维度']],dim)}<div class="dp-filter">${dpField('sales','brand',brands,'品牌')}<button class="btn small" id="dp-target-config">⚙ 目标配置</button></div></div><div class="dp-grid">${dpMetric('SKU 总数',fmt(total.sku),'个')}${dpMetric(word()+'销售额',fmt(total.sale,2),'万元','目标 '+fmt(total.target,2)+' 万元')}${dpMetric('规模达成率',dpPct(total.sale,total.target),'','利润率 '+fmt(total.profit,1)+'%')}${dpMetric('年度销售额差额',fmt(total.annual-total.ytd,2),'万元','年度目标 '+fmt(total.annual,2)+' 万元')}</div><div class="dp-chart-grid"><div class="dp-chart-panel"><h3>${dim==='channel'?'各渠道':dim==='brand'?'各品牌':'各品链'}销售额（万元）</h3>${dpBars(rows,'sale')}</div><div class="dp-chart-panel"><h3>规模达成率 · 目标线 100%</h3>${dpBars(rows.map(r=>({...r,rate:r.target?r.sale/r.target*100:0,color:r.target&&r.sale/r.target>=1?'#6ebca7':r.target&&r.sale/r.target>=.8?'#f0ba71':'#ec8a98'})),'rate',120)}</div></div>${dpTable(h,data)}`}
function dpSalesDetail(index,dim){const f=dpState.filters.sales||{},parent=dpSalesRows(dim,f.brand||'all').find(r=>r.index===index);if(!parent)return;const details=dim==='channel'?dpChannelNames.map((name,i)=>dpSalesRows('channel',f.brand||'all')[i]).filter(r=>r.index===index):dim==='chain'?dpSalesCells().filter(r=>r.chain===index&&(pfIncludes(f.brand,r.brandIndex))):dpSalesCells().filter(r=>r.brandIndex===index);openModal(parent.name+' · 经营明细',`<div class="dp-grid">${dpMetric('销售额',fmt(parent.sale,2),'万元')}${dpMetric('目标',fmt(parent.target,2),'万元')}${dpMetric('达成率',dpPct(parent.sale,parent.target))}${dpMetric('年度差额',fmt(parent.annual-parent.ytd,2),'万元')}</div>${dpTable(['经营范围','销售额（万元）','目标（万元）','达成率','利润率'],details.map(r=>[dim==='chain'?brands[r.brandIndex]:dim==='brand'?chains[r.chain]:r.name,fmt(r.sale,2),fmt(r.target,2),dpPct(r.sale,r.target),fmt(r.profit,1)+'%']))}<p class="dp-notice">金额、目标来自总看板同一经营台账。渠道延续原演示分配规则，跨境按 TK / 其他跨境拆分且合计一致。</p>`);if(parent.target&&parent.sale<parent.target*.9){const source={key:'sale:'+periodKey()+':'+dim+':'+index,kind:'channel',name:parent.name+'经营改善',model:'SALE-'+index,chain:dim==='chain'?index:dpState.chain==='all'?0:+dpState.chain,owner:aiOwners[dim==='chain'?index:0],cause:'销售达成 '+dpPct(parent.sale,parent.target)+'，周期缺口 '+fmt(parent.target-parent.sale,2)+' 万元'};$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary" id="dp-sales-task">下发改善任务</button>');$('#dp-sales-task').onclick=()=>dpWith('sales',()=>dpDispatch(source))}}
