function dpNewRules(){openModal('新品评级目标配置',`<form class="dp-form" id="dp-new-rule-form">${chains.map((name,i)=>`<label>${name}月均销售目标（万元）<input type="number" name="c${i}" value="${dpStore.newTargets[i]}" min="1" max="100000" step="1" required></label>`).join('')}<label>目标利润率（%）<input name="margin" type="number" min="1" max="100" step=".1" required value="${dpStore.marginTarget}"></label><label>调整原因<input name="reason" required minlength="5"></label><p class="dp-notice full">A：月均销售≥品类目标且利润达标；B：月均销售≥品类目标且利润未达标；C：月均销售&lt;品类目标且利润达标；D：月均销售&lt;品类目标且利润未达标。利润率≥目标利润率即为达标，所有新品只归入 ABCD 四类。保存后总看板与产品部采用同一新品等级。</p></form>`);$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary" type="submit" form="dp-new-rule-form">保存规则</button>');$('#dp-new-rule-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),audit=dpAudit('新品评级规则','品类目标',f.get('reason'));if(dpSave({...dpStore,newTargets:chains.map((_,i)=>+f.get('c'+i)),marginTarget:+f.get('margin'),audit:[audit,...dpStore.audit]})){renderAll();renderDepartment();closeModal()}}}
