function pbSupplierRisks(){return pbSuppliers().filter(s=>s.state!=='已淘汰').flatMap(s=>pbSupplierDimensions.map((dim,j)=>{const value=[s.delivery,s.costRate,s.quality,s.delay,s.refurb,s.contract?1:0,s.qualified,s.missing.length][j],bad=[value<90||s.stars===1,value<90,value>=.5,value>0,value<90,!!value,value<3,!!value][j];return bad?{...s,key:s.key+':'+j,supplierKey:s.key,kind:'supplier',dimension:dim,metric:value+(['%','%','%',' 天','%',' 次',' 家',' 项'][j]),issue:['交付及时率不足，生产与到货排期未同步。','目标成本达标率偏低，报价缺少材料成本拆解。','抽检质量问题比例超过 0.5%，需定位采购批次。','供应商研发打样节点延期。','翻新批次交付未满足承诺日期。','存在合同履约异常，需采购与法务共同核查。','合格工厂储备不足 3 家，需要推进备选工厂准入。','必备资料缺失：'+s.missing.join('、')][j],level:s.stars===1||[2,5,7].includes(j)?'高危':'中风险',date:pbDate(),due:shiftDate(pbDate(),3),source:'供应商能力评审 · '+s.code}:null}).filter(Boolean))}
function pbSelectionRisks(){const rows=pbSelectionRows(),all=pbPeople.filter(n=>rows.some(r=>r.owner===n)),team=[2,3,6].map((stage,j)=>{const den=pbStageRows([0,2,3][j],rows).length;return den?pbStageRows(stage,rows).length/den:0});return all.flatMap((owner,i)=>{const own=rows.filter(r=>r.owner===owner);return ['意向转化率','确品转化率','爆品转化率','绩差人员'].map((dimension,j)=>{const k=Math.min(j,2),den=pbStageRows([0,2,3][k],own).length,rate=den?pbStageRows([2,3,6][k],own).length/den:0,gap=team[k]?1-rate/team[k]:0;if(gap<.05)return null;const p=own[0];return {...p,key:'SEL-RISK-'+periodKey()+':'+owner+':'+j,kind:'selection',dimension,name:owner+' · '+dimension,rate,team:team[k],metric:fmt(rate*100,1)+'%',level:gap>=.1?'高危':'中风险',date:pbDate(),due:shiftDate(pbDate(),7),issue:'样品验证与运营确认衔接偏慢，转化率低于团队均值 '+fmt(gap*100,1)+'%。',source:'选品逐节点台账 · 个人 / 团队加权比例'}}).filter(Boolean)})}
function pbRiskLists(includeClosed=false){const suppliers=pbSupplierRisks(),orders=pbOrders(),ps=pbProjectRows(),newp=productRows(true).map(p=>{const s=pbSupplierFor(p.chain,p.id);return {...p,key:'QUALITY-'+periodFor().year+'-'+p.id,kind:'quality',tier:s.tier,owner:s.owner,supplier:s.name,supplierKey:s.key,metric:fmt(p.returnRate,1)+'%',level:p.returnRate>=6?'高危':'中风险',issue:'重点核查功能不良、包装破损与使用体验类退货，按采购批次追溯。',date:pbDate(),due:shiftDate(pbDate(),5),source:'总看板新品销售 / 退货统一台账'}}).filter(pbScope).sort((a,b)=>b.returnRate-a.returnRate),cost=orders.filter(r=>r.rate>0||r.fee>r.feeTarget).map(r=>({...r,key:r.key+':cost',kind:'cost',issue:'采购成本或综合费率超出目标，需拆解物料、物流、损耗。',metric:'+'+fmt(r.rate,1)+'%',level:r.rate>8?'高危':'中风险'})).sort((a,b)=>b.rate-a.rate),process=pbScores().filter(r=>r.score<85).map((r,i)=>({...r,key:'PROCESS-'+periodKey()+':'+r.name,kind:'process',name:r.name+' · '+pbDeviationTypes[i%7],dimension:pbDeviationTypes[i%7],metric:r.late+' 次迟报',issue:r.issue}));let lists=[pbSupplierRankRows(suppliers),cost,ps.filter(r=>r.status!=='绿灯').sort((a,b)=>b.delay-a.delay),orders.filter(r=>r.delay>0).sort((a,b)=>b.delay-a.delay).map(r=>({...r,metric:r.delay+' 天'})),newp,pbSelectionNodeRisks(),process.sort((a,b)=>(b.level==='高危')-(a.level==='高危')||b.late-a.late)];if(!includeClosed)lists=lists.map(a=>a.filter(r=>!pbClosed(r)));lists.flat().forEach(pbRemember);return lists}
const pbRiskTitles=['供应商预警','成本管控预警','项目延期预警','订单交付预警','新品高退货率','自选品预警','工作流程预警'];
function pbAllRisks(){return [...new Map(pbRiskLists().flat().map(r=>[r.key,r])).values()]}
function pbPlan(r){return `1. 核查与定责：${r.issue||'复核原始业务记录与目标差额。'}\n2. 纠正动作：${({supplier:'补齐资质与委托加工协议，复核产能、交付及质量能力；至少准备 3 家合格工厂。',cost:'逐项核对目标成本、材料报价、物流与损耗；形成议价与替代物料方案。',order:'确认缺料清单和分批交付排期，安排验收入库并回传订单凭证。',project:'对齐采购卡点对应阶段与交付物，同步供应商排期及下游项目影响。',quality:'隔离异常采购批次，分析退货原因 TOP3，供应商复测通过后再放行。',selection:'复盘流失节点，明确运营需求与样品验收标准，逐项推进意向和确品。',process:'补齐日报周报与关键业务台账，逐条检查闭环证据与协同响应。'})[r.kind]||'补齐过程交付记录，将目标拆解到每周里程碑。'}\n3. 资源建议：责任采购牵头，协调 1 名供应商开发 / 品质专员支持，先确认排期与投入。\n4. 验证标准：上传对应合同、检测报告、入库单或节点确认记录，由负责人复核；业务风险消除后验收销项。`}
function pbLifeScope(fn){const previous=dpState.chain;dpState.chain=pbState.chain;try{return fn()}finally{dpState.chain=previous}}
function pbLifeRows(stage){return lifeChainRows(stage).map((r,chain)=>({...r,chain})).filter(r=>pbState.chain==='all'||r.chain===+pbState.chain)}
function pbLifeChannels(stage){return pbLifeScope(()=>dpLifeChannels(stage))}
function pbLifeRecords(stage,scope,channel='all',chain='all'){return pbLifeScope(()=>dpLifeRecords(stage,scope,periodFor(),channel,chain)).map(r=>({...r,owner:pbOwner(r.chain),supplier:pbSupplierFor(r.chain,+r.channel||0).name}))}

function pbSupplierRankRows(risks){const groups=new Map();risks.forEach(r=>{if(!groups.has(r.supplierKey))groups.set(r.supplierKey,[]);groups.get(r.supplierKey).push(r)});return [...groups.values()].map(list=>{const priority=[...list].sort((a,b)=>(b.dimension==='合规力')-(a.dimension==='合规力')||(b.dimension==='资料完整性')-(a.dimension==='资料完整性')||(b.level==='高危')-(a.level==='高危'))[0];return {...priority,dimension:list.slice(0,2).map(r=>r.dimension).join(' / '),metric:priority.stars+' 星',issue:list.map(r=>r.dimension+'：'+r.issue).join('；'),riskItems:list.length,relatedKeys:list.map(r=>r.key)}}).sort((a,b)=>(b.contract-a.contract)||a.stars-b.stars||b.delay-a.delay)}
function pbSelectionNodeRisks(){const rows=pbSelectionRows(),risks=[];for(const stage of [0,2,4,5])for(const chain of [0,1,2,3]){if(pbState.chain!=='all'&&chain!==+pbState.chain)continue;const chainTarget=pbState.chain==='all'?splitTarget(pbSelectionTarget(stage),[1,1,1,1])[chain]:pbSelectionTarget(stage),owners=pbPeople.filter((_,i)=>i%4===chain),targets=splitTarget(chainTarget,[1,1,1]);owners.forEach((owner,i)=>{const source=rows.find(r=>r.owner===owner);if(!source)return;const target=targets[i],actual=pbStageRows(stage,rows.filter(r=>r.owner===owner)).length,rate=target?actual/target:1;if(rate>=.8)return;risks.push({...source,key:'NODE-'+periodKey()+':'+stage+':'+owner,kind:'selection',name:pbStages[stage]+'推进 · '+owner,dimension:pbStages[stage],target,actual,gap:target-actual,metric:pbPct(actual,target),level:rate<.6?'高危':'中风险',rate,date:pbDate(),due:bounds().end,issue:'计划 '+target+' 款，实际 '+actual+' 款，缺口 '+(target-actual)+' 款；样品验证及运营确认未按节点推进。',source:'自选品节点目标 / 完成台账'})})}return risks.sort((a,b)=>a.rate-b.rate||b.gap-a.gap)}

function pbRenderRisk(){const lists=pbRiskLists();return `<div class="pb-risk-grid">${lists.map((rows,i)=>`<article class="riskcard"><div class="rhead"><h3><i class="riskbadge"></i>${pbRiskTitles[i]} <small>TOP 6</small></h3>${pbBtn('全部 '+rows.length+' ›','risk-list',i)}</div>${rows.slice(0,6).map((r,j)=>`<button class="pb-risk-row" data-pb-action="detail" data-key="${esc(r.key)}"><span class="rank ${j<3?'top':''}">${String(j+1).padStart(2,'0')}</span>${['supplier','person','process'].includes(r.kind)?'<span class="pb-supplier-icon">'+(r.kind==='supplier'?'供':'岗')+'</span>':riskThumbnail(r.name)}<span class="pb-risk-title"><b>${esc(r.name)}</b><small>${esc(r.model||chains[r.chain])} · ${esc(r.owner)} · ${esc(r.dimension||r.type||r.stage||'采购风险')}</small></span><span class="${pbRiskTone(r)}">${esc(r.metric)}</span></button>`).join('')||'<div class="dp-empty">当前范围无未闭环预警</div>'}</article>`).join('')}</div>`}
function pbAIRows(){const risks=pbAllRisks(),dedup=[...new Map(risks.map(r=>[r.supplierKey||r.model||r.key,r])).values()],custom=pbStore.custom.filter(r=>pbScope(r)&&r.period.year===periodFor().year);return [...custom,...dedup].filter(r=>!pbStore.removed.includes(r.key)&&!pbClosed(r)).map(r=>({...r,...pbStore.edits[r.key],priority:pbStore.edits[r.key]?.priority||(r.level==='高危'?'P0':'P1')})).sort((a,b)=>a.priority.localeCompare(b.priority))}
function pbRenderAI(){const rows=pbAIRows(),dev=pbRiskLists()[6],tasks=pbStore.tasks.filter(pbScope).filter(t=>t.state!=='已验收');return `<div class="dp-grid">${pbMetric('核心关键事项',rows.length+'<em>项</em>','P0 '+rows.filter(r=>r.priority==='P0').length+' 项 · 按优先级排序','ai','key')}${pbMetric('工作偏差',dev.length+'<em>项</em>','识别目标、跟进、资源及协同偏差','ai','deviation')}${pbMetric('AI 优化建议',rows.length+'<em>条</em>','对应方案、责任人及计划完成时间','ai','advice')}${pbMetric('待闭环风险',pbAllRisks().length+'<em>个</em>','已派发 '+tasks.length+' 项 · 逾期 '+tasks.filter(t=>t.due<pbDate()).length+' 项','ai','pending','red')}</div><div class="pb-ai-summary"><span class="ai-logo">✧ AI</span><div><b>优先协调供应商准入、采购节点与交付异常</b><p>将高危事项落实到责任采购与验收凭证，跨部门资源建议由部长协调确认。</p></div>${pbBtn('查看完整 AI 诊断','ai','key','btn primary')}</div>`}
function pbScoreCells(r){pbRemember(r);return [esc(r.name)+'<small>'+r.role+'</small>',chains[r.chain],`<b class="${r.score>=80?'green':r.score>=60?'orange':'red'}">${fmt(r.score,1)}</b>`,traffic(r.score>=80?'绿灯':r.score>=60?'黄灯':'红灯'),pbPct(r.closed,r.planned),r.issue,r.late+' 次迟报',pbBtn('得分明细','person',r.key)]}
function pbRenderManagement(){const tab=pbState.tabs.management,scores=pbScores(),risks=pbRiskLists(true)[6],f=pbState.filters.management||{},view=scores.filter(r=>(f.role==='all'||!f.role||r.role===pbRoles[+f.role])&&(f.state==='all'||!f.state||(r.score>=80?'绿灯':r.score>=60?'黄灯':'红灯')===['绿灯','黄灯','红灯'][+f.state])).sort((a,b)=>f.sort==='1'?b.score-a.score:a.score-b.score),planned=pbSum(scores,'planned'),closed=pbSum(scores,'closed');
 const tabs=pbTabs('management',[['score','人员评分与资源'],['deviation','工作偏差复盘'],['process','关键过程指标']]);
 if(tab==='deviation'){return tabs+`<div class="dp-grid">${pbMetric('偏差总数',risks.length+'<em>项</em>','七类管理偏差','modal-set','process')}${pbMetric('高风险偏差',risks.filter(r=>r.level==='高危').length+'<em>项</em>','优先落实责任与期限','modal-set','process')}${pbMetric('已闭环',risks.filter(pbClosed).length+'<em>项</em>','已通过负责人验收','modal-set','process')}${pbMetric('逾期未整改',risks.filter(r=>!pbClosed(r)&&pbTask(r)?.due<pbDate()).length+'<em>项</em>','按计划完成日期判断','modal-set','process')}</div>${pbPage('management-deviation',risks,['偏差事项','根因分类','AI 根因与闭环方向','责任人','整改期限','当前状态','操作'],(r,i)=>[r.name,['供应商管理','选品方向','成本管理','项目管理','流程制度','培训能力','人员管理'][pbPeople.indexOf(r.owner)%7],r.issue,r.owner,pbTask(r)?.due||r.due,pbTask(r)?.state||'待下发',pbActions(r)])}<div class="pb-analysis"><b>近三个月偏差复盘</b>${pbTrend([risks.length+5,risks.length+2,risks.length],chartPeriodDates(3,true))}<p>以过程记录完整性、响应及时性与业务风险为依据，按月复核反复出现的漏项。</p></div>`}
 if(tab==='process'){const subtype=pbState.tabs.process||'supplier';return tabs+pbTabs('process',[['supplier','供应商管理'],['selection','自选品管理'],['quote','报价管理'],['docs','日报 / 周报 / 会议 / 台账']])+(subtype==='supplier'?pbSupplierGradeTable():subtype==='selection'?pbSelectionNodeTable():subtype==='quote'?pbQuoteTable():pbDocumentsTable())}
 return tabs+`<div class="pb-grid-six">${pbMetric('部门人员平均分',fmt(pbSum(scores,'score')/Math.max(1,scores.length),1)+'<em>分</em>','五维评分 · 满分 100','modal-set','people')}${pbMetric('人员状态分布',`<span class="green">${scores.filter(r=>r.score>=80).length}</span> / <span class="orange">${scores.filter(r=>r.score>=60&&r.score<80).length}</span> / <span class="red">${scores.filter(r=>r.score<60).length}</span>`,'绿灯 / 黄灯 / 红灯','modal-set','people')}${pbMetric('整体任务闭环率',pbPct(closed,planned),'按期闭环 '+closed+' / 计划 '+planned,'modal-set','people')}${pbMetric('核心事项投入占比',pbPct(scores.reduce((n,r)=>n+r.raw.filter(d=>d.proactive).length*4,0),scores.reduce((n,r)=>n+r.raw.length*3,0)),'重点任务工时 / 总工时','modal-set','people')}${pbMetric('采购根因红灯',pbProjectRows().filter(r=>r.status==='红灯').length+'<em>项</em>','与总看板采购卡点同源','modal-set','projects','red')}${pbMetric('风险主动检出率',pbPct(scores.reduce((n,r)=>n+pbSum(r.raw,'proactive'),0),scores.reduce((n,r)=>n+pbSum(r.raw,'proactive')+pbSum(r.raw,'riskMissing'),0)),'主动预警 / 已识别风险事件','modal-set','people')}</div><div class="pb-filters">${pbField('management','role',pbRoles,'岗位')}${pbField('management','state',['绿灯','黄灯','红灯'],'人员状态')}${pbField('management','sort',['得分从低到高','得分从高到低'],'排序')}</div>${pbPage('management-score',view,['姓名 / 岗位','品类','AI 得分','状态','任务闭环率','扣分与重点工作','过程问题','操作'],pbScoreCells)}<div class="pb-analysis"><span class="ai-logo">✧ AI</span><div><b>资源分散，建议优先补齐采购节点与过程交付</b><p>${scores.filter(r=>r.score<60).map(r=>r.name).join('、')||'当前无红灯人员'}；关注日报漏交、无凭证闭环与供应商协同。先处理 ${pbProjectRows().filter(r=>r.status==='红灯').length} 个采购根因红灯，再分配常规开发工作。</p></div></div>`}
function pbTrend(values,labels){if(!values.length)return '<div class="dp-empty">当前范围暂无趋势记录</div>';const max=Math.max(1,...values),step=Math.max(1,Math.ceil(values.length/7)),pts=values.map((v,i)=>[35+i*360/Math.max(1,values.length-1),110-v/max*80]);return `<svg class="pb-trend" viewBox="0 0 430 150" role="img" aria-label="周期数据趋势"><path d="M${pts.map(p=>p.join(',')).join(' L')}" stroke="#7d83f7" fill="none" stroke-width="2"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${values.length>20?2:4}" fill="#7d83f7"><title>${labels[i]}：${values[i]}</title></circle>${i%step===0||i===values.length-1?`<text x="${x}" y="${y-9}" text-anchor="middle">${values[i]}</text><text x="${x}" y="140" text-anchor="middle">${labels[i]}</text>`:''}`).join('')}</svg>`}
function pbSupplierCells(r){pbRemember(r);return [esc(r.name)+'<small>'+r.code+'</small>',r.kind===0?'整机供应商':'物料供应商',chains[r.chain],r.grade+' 级 · '+r.stars+' 星',r.state,r.owner,r.date,pbBtn('查看详情','supplier',r.key)]}
function pbSupplierGradeTable(){const rows=pbSuppliers(),groups=[0,1].flatMap(kind=>['S','A','B'].map(grade=>({kind,grade,rows:rows.filter(r=>r.kind===kind&&r.grade===grade)})));return dpTable(['供应商类型','分级','累计数量','本期新增','查看明细'],groups.map(g=>[g.kind?'物料供应商':'整机供应商',g.grade,pbBtn(g.rows.length+' 家','supplier-filter',g.kind+'|'+g.grade),g.rows.filter(r=>r.date>=bounds().start).length,pbBtn('查看明细','supplier-filter',g.kind+'|'+g.grade)]))}
function pbRenderSuppliers(){const all=pbSuppliers(),tab=pbState.tabs.suppliers,state=pbState.tabs.supplierStatus,kind=tab==='machine'?0:tab==='material'?1:null,base=kind===null?all:all.filter(r=>r.kind===kind),rows=base.filter(r=>state==='all'||r.state===state),n=base.length,newCount=base.filter(r=>r.date>=bounds().start).length;
 const tabs=pbTabs('suppliers',[['all','供应商总览'],['machine','整机供应商'],['material','物料供应商'],['risk','供应商风险预警']]);
 if(tab==='risk'){const dim=pbState.tabs.supplierRisk,allRisks=pbSupplierRisks(),risks=allRisks.filter(r=>r.dimension===dim&&!pbClosed(r));return tabs+pbRiskOverview(allRisks)+pbTabs('supplierRisk',pbSupplierDimensions.map(n=>[n,n]))+pbPage('supplier-risk',risks,['预警','供应商 / 品类','核心指标','卡点与 AI 根因','责任采购','期限','状态','操作'],r=>[pbTag(r),esc(r.name)+'<small>'+chains[r.chain]+'</small>',r.dimension+' '+r.metric,r.issue,r.owner,pbTask(r)?.due||r.due,pbTask(r)?.state||'待下发',pbActions(r)])}
 if(kind!==null)return tabs+pbTabs('supplierStatus',[['all','全部状态'],...['已合作','准入储备','意向储备','已注册','已淘汰'].map(n=>[n,n])])+`<div class="dp-grid">${pbMetric('当前状态供应商',rows.length+'<em>家</em>','当前类型、状态与品类范围','supplier-current','current')}${pbMetric(state==='已淘汰'?'淘汰 / 已合作占比':'占当前类型比例',pbPct(rows.length,state==='已淘汰'?base.filter(r=>r.state==='已合作').length:n),'按当前状态集合统计','supplier-current','current')}${pbMetric('本期新增',rows.filter(r=>r.date>=bounds().start).length+'<em>家</em>',periodLabel(),'supplier-current','new')}${pbMetric('低星级供应商',rows.filter(r=>r.stars<2&&r.state!=='已淘汰').length+'<em>家</em>','低于 2 星触发预警','supplier-current','low','red')}</div><div class="pb-distributions">${pbDistribution('星级分布',[1,2,3].map(stars=>[stars+' 星',rows.filter(r=>r.stars===stars).length]),'supplier-star')}${pbDistribution('品类分布',chains.map((c,i)=>[c,rows.filter(r=>r.chain===i).length]),'supplier-chain')}${pbDistribution('采购人员',pbPeople.filter(n=>rows.some(r=>r.owner===n)).map(n=>[n,rows.filter(r=>r.owner===n).length]),'supplier-owner')}</div>${pbPage('supplier-list',rows,['供应商 / 编码','供应商类型','品类','等级 / 星级','合作状态','责任采购','创建日期','操作'],pbSupplierCells)}`;
 return tabs+`<div class="pb-grid-three">${[['供应商总数',all,'all'],['整机供应商',all.filter(r=>r.kind===0),'machine'],['物料供应商',all.filter(r=>r.kind===1),'material']].map(([label,rows,value])=>pbMetric(label,rows.length+'<em>家</em>','本期新增 '+rows.filter(r=>r.date>=bounds().start).length+' · 本年新增 '+rows.filter(r=>r.date.startsWith(String(periodFor().year))).length,'supplier-type',value)).join('')}</div><div class="pb-subheading"><h3>供应商建设目标</h3>${pbBtn('配置目标','targets','supplier','btn small')}</div>${pbSupplierTargets()}<div class="pb-columns"><div><h3>各采购人员供应商分布</h3>${pbPage('supplier-owner',pbPeople.filter(n=>all.some(r=>r.owner===n)),['责任采购','累计数','占比','本年新增','操作'],name=>{const rows=all.filter(r=>r.owner===name);return [name,rows.length,pbPct(rows.length,all.length),rows.filter(r=>r.date.startsWith(String(periodFor().year))).length,pbBtn('查看明细','supplier-owner',name)]})}</div><div><h3>全状态分布</h3>${dpTable(['状态','数量','占比','本年新增','本期新增'],pbStatus.map(state=>{const rows=all.filter(r=>r.state===state);return [state,pbBtn(rows.length+'','supplier-state',state),pbPct(rows.length,all.length),rows.filter(r=>r.date.startsWith(String(periodFor().year))).length,rows.filter(r=>r.date>=bounds().start).length]}))}<p class="dp-footnote">累计收录包含已淘汰历史；总看板储备与合作数量仅统计有效供应商。</p></div></div>`}
function pbSupplierTargets(){const rows=pbSuppliers().filter(r=>r.state!=='已淘汰');return dpTable(['供应商类型','周期目标','实际新增','完成率','年度目标','年度累计新增'],[0,1].filter(t=>pbState.tier==='all'||t===+pbState.tier).map(t=>{const stats=supplierData()[t],ratio=pbState.chain==='all'?1:.25,defaultTarget=Math.round(stats.qt*ratio),target=pbStore.targets[periodKey()+':supplier:'+t+':'+pbState.chain]??defaultTarget,actual=rows.filter(r=>r.kind===t&&r.date>=bounds().start).length;return [['整机供应商','物料供应商'][t],target,actual,badge(target?actual/target*100:0),Math.round(stats.yt*ratio),rows.filter(r=>r.kind===t&&r.date.startsWith(String(periodFor().year))).length]}))}
function pbDistribution(title,items,action){const total=items.reduce((n,r)=>n+r[1],0),max=Math.max(1,...items.map(r=>r[1]));return `<div class="pb-distribution"><h3>${title}</h3>${items.map(([label,n])=>`<button data-pb-action="${action}" data-key="${esc(label)}"><span>${esc(label)}</span><i><em style="width:${n/max*100}%"></em></i><b>${n}</b><small>${pbPct(n,total)}</small></button>`).join('')}</div>`}
function pbRiskOverview(rows){return `<div class="pb-grid-five">${[['预警总项数',rows.length],['高危红单',rows.filter(r=>r.level==='高危'&&!pbClosed(r)).length],['整改中',rows.filter(r=>pbTask(r)&&!pbClosed(r)).length],['已闭环',rows.filter(pbClosed).length],['整改逾期',rows.filter(r=>pbTask(r)?.due<pbDate()&&!pbClosed(r)).length]].map(([l,n])=>pbMetric(l,n+'<em>项</em>','关联整改任务','tasks','all')).join('')}</div>`}
function pbSelectionNodeTable(){return dpTable(['选品节点','本期计划','实际完成','完成率','查看明细'],[0,2,3,4,5,6].map(stage=>{const actual=pbStageRows(stage).length,target=pbSelectionTarget(stage);return [pbStages[stage],target,pbBtn(actual+'','selection-stage',stage),badge(target?actual/target*100:0),pbBtn('查看明细','selection-stage',stage)]}))}
function pbSelectionTarget(stage){return pbStore.targets[periodKey()+':selection:'+stage+':'+pbState.chain]??Math.round((pbState.chain==='all'?1:.25)*[100,90,76,60,48,36,18][stage]*(periodFor().mode==='year'?4:periodFor().mode==='month'?1/3:1))}
function pbRenderSelection(){const tab=pbState.tabs.selection,stage=+pbState.tabs.stage,all=pbSelectionRows(),counts=pbStages.map((_,i)=>pbStageRows(i,all).length),rows=pbStageRows(stage,all),f=pbState.filters.selection||{};
 const tabs=pbTabs('selection',[['overview','全景总览'],['analysis','分指标多维分析'],['risk','选品管理预警']]),filters=`<div class="pb-filters">${pbField('selection','owner',pbPeople,'责任采购')}${pbField('selection','supplier',pbStatus,'供应商状态')}${pbField('selection','ops',pbOps,'运营部门')}${pbField('selection','origin',['运营提需','采购自推'],'运营类型')}${pbBtn('配置目标 / 爆品标准','targets','selection','btn small')}</div>`;
 if(tab==='risk'){const all=pbSelectionRisks(),risks=all.filter(r=>r.dimension===pbState.tabs.selectionRisk&&!pbClosed(r));return tabs+filters+pbRiskOverview(all)+pbTabs('selectionRisk',['意向转化率','确品转化率','爆品转化率','绩差人员'].map(n=>[n,n]))+pbPage('selection-risk',risks,['预警','责任人 / 品类','指标','实际值','团队均值','核心卡点','整改期限','状态','操作'],r=>[pbTag(r),r.owner+'<small>'+chains[r.chain]+'</small>',r.dimension,r.metric,pbPct(r.team,1),r.issue,pbTask(r)?.due||r.due,pbTask(r)?.state||'待下发',pbActions(r)])}
 const cards=`<div class="pb-grid-seven">${counts.map((n,i)=>pbMetric(pbStages[i]+'数量',n+'<em>款</em>','计划 '+pbSelectionTarget(i)+' · '+pbPct(n,pbSelectionTarget(i)),'selection-stage',i)).join('')}</div>`;
 if(tab==='overview')return tabs+filters+cards+`<div class="pb-columns"><div class="pb-funnel"><h3>选品全链路转化</h3>${[0,2,3,4,5,6].map((stage,j)=>`<button data-pb-action="selection-stage" data-key="${stage}" style="--funnel-width:${100-j*9}%"><b>${pbStages[stage]} ${counts[stage]}</b><span>${j?'上层转化 '+pbPct(counts[stage],counts[[0,2,3,4,5,6][j-1]]):'周期到样基数'}</span></button>`).join('')}</div><div class="pb-analysis pb-vertical"><span class="ai-logo">✧ AI</span><h3>聚焦确品与上线前的转化损失</h3><p>意向 → 确品 ${pbPct(counts[3],counts[2])}，立项 → 上线 ${pbPct(counts[5],counts[4])}。优先复盘样品验证标准、运营提需确认和采购打样交期。</p>${pbSelectionNodeTable()}</div></div>`;
 const gran=pbState.tabs.selectionGran||'month',groups=new Map();rows.forEach(r=>{const d=r.dates[stage],date=gran==='day'?d:gran==='week'?shiftDate(d,-((new Date(d+'T00:00:00Z').getUTCDay()+6)%7)):d.slice(0,7);groups.set(date,(groups.get(date)||0)+1)});const dates=[...groups.keys()].sort();
 return tabs+filters+cards+pbTabs('stage',pbStages.map((n,i)=>[String(i),n+'分析']))+`<div class="pb-columns"><div class="pb-chart"><div class="pb-subheading"><h3>${pbStages[stage]}数量趋势</h3>${pbTabs('selectionGran',[['day','日'],['week','周'],['month','月']])}</div>${pbTrend(dates.map(d=>groups.get(d)),dates)}</div>${pbDistribution('人员分布',pbPeople.map(n=>[n,rows.filter(r=>r.owner===n).length]).filter(r=>r[1]),'sample-owner')}</div><div class="pb-distributions">${pbDistribution('品类分布',chains.map((n,i)=>[n,rows.filter(r=>r.chain===i).length]),'sample-chain')}${pbDistribution('供应商状态分布',pbStatus.map(n=>[n,rows.filter(r=>r.supplierState===n).length]),'sample-supplier')}${pbDistribution('运营部门分布',pbOps.map(n=>[n,rows.filter(r=>r.ops===n).length]),'sample-ops')}</div>${pbPage('selection-list',rows,['产品 / 型号','供应商','品类','责任采购','运营部门 / 类型',pbStages[stage]+'日期','当前状态','操作'],r=>{pbRemember(r);return [pbProduct(r),r.supplier,chains[r.chain],r.owner,r.ops+'<small>'+r.origin+'</small>',r.dates[stage],pbStages[r.stage],pbBtn('查看详情','detail',r.key)+(stage>=4?pbBtn('项目详情','project',r.projectId):'')]})}`}
function pbRenderLifecycle(){const stage=+pbState.tabs.lifecycle,rows=pbLifeRows(stage),sum=lifeSumRows(rows),view=pbState.tabs.lifeView;return `<div class="dp-life-grid">${lifeNames.map((n,i)=>{const d=lifeSumRows(pbLifeRows(i));return pbMetric(n,pbPct(d.actual,d.target),'年度 '+d.yearActual+' / '+d.yearTarget,'life-stage',i,d.target&&d.actual/d.target<.8?'red':'blue')}).join('')}</div>${pbTabs('lifecycle',lifeNames.map((n,i)=>[String(i),n]))}${pbTabs('lifeView',[['summary','汇总视图'],['chain','分类目视图']])}${view==='summary'?dpTable(['指标维度','目标值','实际完成','完成率'],[[word(),sum.target,pbBtn(sum.actual+'','life-detail',stage+'|period|all|all'),badge(sum.target?sum.actual/sum.target*100:0)],['年度累计',sum.yearTarget,pbBtn(sum.yearActual+'','life-detail',stage+'|year|all|all'),pbPct(sum.yearActual,sum.yearTarget)]]):dpTable(['业务链群',word()+'目标',word()+'实际',word()+'完成率','年度目标','年度实际','年度完成率','责任采购','配套供应商','操作'],rows.map(r=>[r.name,r.target,pbBtn(r.actual+'','life-detail',stage+'|period|all|'+r.chain),badge(r.target?r.actual/r.target*100:0),r.yearTarget,pbBtn(r.yearActual+'','life-detail',stage+'|year|all|'+r.chain),pbPct(r.yearActual,r.yearTarget),pbOwner(r.chain),pbSupplierLedger().filter(s=>s.chain===r.chain&&s.state==='已合作').length,pbBtn('品类采购视角','scope',r.chain)]))}<p class="dp-footnote">复用总看板完成节点与台账：上品以量产上市为准，立项以评审通过为准；采购补充责任人、供应商与成本信息。</p>`}
function pbRenderChannels(){const stages=[0,1,2,3,4,6],all=stages.map(i=>pbLifeChannels(i)),view=pbState.tabs.channels;return `<div class="pb-grid-seven">${dpChannelNames.map((n,c)=>pbMetric(n,pbPct(all[0][c].actual+all[1][c].actual,all[0][c].target+all[1][c].target),'立项 '+pbPct(all[2][c].actual+all[3][c].actual,all[2][c].target+all[3][c].target),'channel-detail',c)).join('')}</div>${pbTabs('channels',[['channel','按渠道汇总'],['stage','按规划类型对比']])}${view==='channel'?dpTable(['渠道',...stages.map(i=>lifeNames[i]+' 计划 / 实际 / 完成率')],dpChannelNames.map((n,c)=>[n,...all.map((rows,k)=>pbBtn(rows[c].target+' / '+rows[c].actual+' / '+pbPct(rows[c].actual,rows[c].target),'life-detail',stages[k]+'|period|'+c+'|all'))])):dpTable(['规划类型',...dpChannelNames],stages.map((stage,k)=>[lifeNames[stage],...all[k].map((r,c)=>pbBtn(r.target+' / '+r.actual+' / '+pbPct(r.actual,r.target),'life-detail',stage+'|period|'+c+'|all'))]))}<p class="dp-footnote">每个完成项按主渠道归属一次；品质整改、产品下市保留在汇总层，不进入渠道拆分。</p>`}
function pbRenderTasks(){const all=pbStore.tasks.filter(pbScope).filter(t=>t.createdDate>=bounds().start&&t.createdDate<=bounds().cutoff),tab=pbState.tabs.tasks,rows=all.filter(t=>tab==='all'||t.state===tab);return `<div class="dp-grid">${[['待执行',all.filter(t=>t.state==='待执行').length],['执行中',all.filter(t=>t.state==='执行中').length],['待验收',all.filter(t=>t.state==='待验收').length],['已验收',all.filter(t=>t.state==='已验收').length]].map(([n,v])=>pbMetric(n,v+'<em>项</em>','任务状态同步原始风险','tasks',n)).join('')}</div>${pbTabs('tasks',[['all','全部'],...['待执行','执行中','待验收','已验收','退回整改'].map(n=>[n,n])])}${pbPage('tasks-list',rows,['任务编号 / 内容','责任采购 / 品类','计划完成','状态','通知状态','最新进展','操作'],t=>[t.id+'<small>'+esc(t.name)+'</small>',t.owner+'<small>'+chains[t.chain]+'</small>',`<span class="${t.due<pbDate()&&t.state!=='已验收'?'red':''}">${t.due}</span>`,t.state,t.notify,esc(t.evidence||'等待责任人更新'),pbBtn('跟进 / 验收','task',t.id)])}`}

let pbModalSection='risk';
function pbModal(title,body,drawer=false){openModal(title,body,drawer,periodLabel(pbPeriod(pbModalSection))+' · '+(pbState.chain==='all'?'全部品类':chains[+pbState.chain]));}
function pbModalList(title,records,heads,cells){let page=1,q='';pbModal(title,`<div class="pb-filters"><input id="pb-modal-search" placeholder="搜索名称、型号、责任人"></div><div id="pb-modal-table"></div>`);const render=()=>{const rows=records.filter(r=>JSON.stringify(r).toLowerCase().includes(q.toLowerCase())),pages=Math.max(1,Math.ceil(rows.length/DRAWER_PAGE_SIZE));page=Math.max(1,Math.min(page,pages));$('#pb-modal-table').innerHTML=dpTable(heads,rows.slice((page-1)*DRAWER_PAGE_SIZE,page*DRAWER_PAGE_SIZE).map(cells))+listPager(rows.length,page);bindListPager($('#pb-modal-table'),next=>{page=next;render()});};$('#pb-modal-search').oninput=e=>{q=e.target.value.trim();page=1;render()};render()}
function pbOpenRiskList(index){const rows=pbRiskLists()[index];pbModalList(pbRiskTitles[index]+' · 全部',rows,['风险等级','风险对象','品类','核心指标','责任采购','风险说明','操作'],r=>[pbTag(r),esc(r.name),chains[r.chain],r.metric,r.owner,r.issue,pbActions(r)])}
function pbDetails(r){if(!r)return;if(r.kind==='person')return pbPerson(r);const t=pbTask(r),order=r.kind==='order'||r.kind==='cost',s=pbSupplierLedger().find(s=>s.key===r.supplierKey);pbRemember(r);const items=[['品类',chains[r.chain]],['责任采购',r.owner],['供应商',r.supplier||s?.name||r.name],['证据来源',r.source||'采购过程台账'],['记录日期',r.date||pbDate()],['当前状态',t?.state||'待下发']];if(order){const batch=pbOrders().filter(x=>x.type===r.type),ontime=batch.filter(x=>x.actual!=='—'&&x.actual<=x.due).length;items.push(['本期同类型交付及时率',pbPct(ontime,batch.length)],['平均延期天数',fmt(pbSum(batch,'delay')/Math.max(1,batch.length),1)+' 天']);}if(order)items.push(['订单类型',r.type],['订单数量',r.qty+' 件'],['计划交付',r.due],['实际交付',r.actual],['延期天数',r.delay+' 天'],['目标单价',fmt(r.target,2)+' 元'],['实际单价',fmt(r.actualCost,2)+' 元'],['成本偏差率',fmt(r.rate,1)+'%'],['综合费率 / 标准',r.fee+'% / '+r.feeTarget+'%']);if(r.kind==='cost')items.push(['降本目标进度','80%'],['降本实际进度',Math.max(20,80-Math.round(r.rate*2))+'%'],['降本措施','议价复核、替代料评审、物流与损耗拆解']);if(r.kind==='supplier'&&s)items.push(['供应商类型',['整机供应商','物料供应商'][s.kind]],['星级',s.stars+' 星'],['资质有效期',s.expiry],['缺失资料',s.missing.join('、')||'当前资料齐全'],['开发延期',s.delay+' 天']);if(r.kind==='project')items.push(['计划上线',r.plan],['实际上线',r.actual],['责任链主',aiOwners[r.chain]],['项目负责人',r.originalOwner],['卡点阶段',r.stage],['红绿灯',r.status],['单品成本',r.cost+' 元'],['单品售价',r.price+' 元']);if(r.kind==='quality')items.push(['总退货率',fmt(r.returnRate,1)+'%'],['已签收退率',fmt(r.returnRate*.78,1)+'%'],['采购批次','BATCH-'+r.model+'-'+pbDate().slice(0,7)],['退货原因 TOP3','功能不良 / 运输破损 / 使用体验'],['抽检结论','需复核异常批次并形成复测报告']);if(r.kind==='selection'&&r.target!==undefined)items.push(['计划数量',r.target+' 款'],['实际完成',r.actual+' 款'],['缺口数量',r.gap+' 款'],['完成率',r.metric]);if(r.kind==='sample')items.push(['当前阶段',pbStages[r.stage]],['运营部门',r.ops],['运营类型',r.origin],['累计销量',r.volume+' 件'],...r.dates.map((d,i)=>[pbStages[i]+'日期',d||'未达到']));
 pbModal(r.name+' · 采购详情',`<div class="dp-detail-head">${['supplier','process','person','manual'].includes(r.kind)?'<span class="pb-supplier-icon">采</span>':riskThumbnail(r.name)}<div><h2>${esc(r.name)}</h2><p>${esc(r.model||r.code||r.key)}</p></div>${pbTag(r)}</div><div class="dp-detail-grid">${items.map(([l,v])=>`<div><small>${l}</small><strong>${esc(String(v??'—'))}</strong></div>`).join('')}</div><div class="dp-callout ${r.level==='高危'?'danger':''}"><b>核心卡点与影响</b><p>${esc(r.issue||'按计划跟踪开发、交付与验收。')}</p></div><h3>AI 根因分析与闭环方案</h3><div class="pb-plan">${esc(pbPlan(r))}</div><div class="pb-analysis"><b>资源与验收</b><p>责任采购牵头，按计划日期提交凭证；部长核对风险是否解除，确认后才能验收。协调资源需对方确认，不自动修改经营实际。</p></div>${r.kind==='quality'?pbTrend([r.returnRate*.75,r.returnRate*.82,r.returnRate],chartPeriodDates(3)):''}`);
 $('#dialogactions').insertAdjacentHTML('afterbegin',pbBtn(t?'跟进任务':'编辑方案并下发','dispatch',r.key,'btn primary')+(s?pbBtn('供应商详情','supplier',s.key,'btn'):'')+(r.kind==='project'?pbBtn('查看项目全流程','project',r.id,'btn'):r.kind==='sample'&&r.stage>=4?pbBtn('关联项目详情','project',r.projectId,'btn'):''));}
function pbSupplierDetail(key){const s=pbSupplierLedger().find(s=>s.key===key);if(!s||!pbScope(s))return;const risks=pbSupplierRisks().filter(r=>r.supplierKey===s.key);pbModal(s.name+' · 供应商资料',`<div class="dp-detail-head"><span class="pb-supplier-icon">供</span><div><h2>${esc(s.name)}</h2><p>${s.code} · ${['整机供应商','物料供应商'][s.kind]} · ${s.grade} 级 · ${s.stars} 星</p></div><span class="tag">${s.state}</span></div><div class="dp-detail-grid">${[['供应品类',chains[s.chain]],['责任采购',s.owner],['创建时间',s.date],['准入时间',s.admitted],['合作开始',s.cooperation],['资质有效期',s.expiry],['必备资料',s.missing.length?s.missing.join('、'):'当前必备资料齐全'],['合格工厂储备',s.qualified+' 家'],['交付及时率',s.delivery+'%']].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="pb-subheading"><h3>合作范围与关联台账</h3></div><div class="pb-inline-actions">${pbBtn('合作产品','supplier-products',key,'btn')}${pbBtn('历史订单','supplier-orders',key,'btn')}${pbBtn('风险记录 '+risks.length,'supplier-risks',key,'btn')}</div>${dpTable(['风险维度','指标','原因','状态','操作'],risks.map(r=>{pbRemember(r);return[r.dimension,r.metric,r.issue,pbTask(r)?.state||'待处理',pbActions(r)]}))}`);}
function pbPerson(r){pbRemember(r);const labels=['工作事项闭环率','日报规范与完整性','关键业务目标达成','跨部门协同表现','风险前置识别'],weights=[30,15,25,15,15];pbModal(r.name+' · 五维得分与依据',`<div class="dp-grid">${pbMetric('个人 AI 得分',fmt(r.score,1)+'<em>分</em>','原始计算 '+fmt(r.base,1))}${pbMetric('任务闭环率',pbPct(r.closed,r.planned),r.closed+' / '+r.planned)}${pbMetric('周期报告天数',r.raw.length+'<em>天</em>',periodLabel())}${pbMetric('当前状态',r.score>=80?'绿灯':r.score>=60?'黄灯':'红灯',r.role)}</div>${dpTable(['评分维度','权重上限','周期日均得分','计算与扣分依据'],labels.map((l,i)=>[l,weights[i],fmt(r.parts[i],2),['30×按期闭环率；逾期每项−3，缺交付物−2，无理由搁置−5，下限0。','迟报−5，缺卡点/成果−3，无量化−5；未交当日计0。','按目标比例×25；达成率低于50%时本项不超过10。','采购根因红灯−8，响应超时−4，漏传返工−5，下限0。','基础9分；重大主动预警+6，暴露未上报−6，限0–15。'][i]]))}<div class="pb-analysis"><b>AI 改进建议</b><p>${esc(r.issue)} 每周复核关键事项的交付物与闭环证据，优先保障影响供应商准入和采购交付的工作。</p></div><h3>日报 / 任务原始依据</h3><div id="pb-person-proof"></div>${pbState.role==='manager'?`<form class="dp-form" id="pb-score-form"><label>部长复核得分<input name="score" type="number" min="0" max="100" step=".1" required value="${r.score.toFixed(1)}"></label><label>备注 / 调整依据<input name="reason" required minlength="5" value="${esc(r.override?.reason||'')}"></label><button class="btn" type="submit">保存复核备注</button></form>`:''}`);let page=1;const render=()=>{const list=r.raw.slice((page-1)*DRAWER_PAGE_SIZE,page*DRAWER_PAGE_SIZE);$('#pb-person-proof').innerHTML=dpTable(['日期','计划 / 按期闭环','迟报','缺交付物','日报提交','跨部门红灯','五维得分'],list.map(d=>[d.date,d.planned+' / '+d.closed,d.late,d.missing,d.noReport?'未交':'已交',d.red,d.points.map(v=>fmt(v,1)).join(' / ')]))+listPager(r.raw.length,page);bindListPager($('#pb-person-proof'),next=>{page=next;render()});};render();if($('#pb-score-form'))$('#pb-score-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),key=periodKey(pbPeriod(pbModalSection))+':'+r.name;pbAudit('人员评分复核',key,pbStore.scores[key]||r.base,{score:+f.get('score'),reason:f.get('reason')});pbStore.scores[key]={score:+f.get('score'),reason:f.get('reason')};if(pbSave()){renderPurchasing();toast('复核结果与依据已保存');closeModal()}};$('#dialogactions').insertAdjacentHTML('afterbegin',pbBtn('下发改进任务','dispatch',r.key,'btn primary'));}
function pbOpenAI(tab){pbState.aiTab=tab;const all=pbAIRows(),range=pbState.aiRange,end=pbDate(),start=range==='day'?end:range==='week'?shiftDate(end,-6):end.slice(0,7)+'-01',rows=all.filter(r=>(r.date||end)>=start&&(r.date||end)<=end),types=pbDeviationTypes,list=tab==='pending'?pbAllRisks():tab==='deviation'?pbRiskLists()[6]:rows,pageKey='ai-'+tab+'-'+range,pages=Math.max(1,Math.ceil(list.length/DRAWER_PAGE_SIZE)),page=Math.max(1,Math.min(pbState.pages[pageKey]||1,pages));pbState.pages[pageKey]=page;
 const content=tab==='deviation'?types.map(name=>{const group=list.slice((page-1)*DRAWER_PAGE_SIZE,page*DRAWER_PAGE_SIZE).filter(r=>r.dimension===name);return `<div class="pb-subheading"><b>${name}</b><small>${group.length} 项</small></div>`+group.map(r=>`<article class="pb-ai-item"><h3>${esc(r.name)}</h3><p>${esc(r.issue)}</p><small>来源：${esc(r.source)} · 责任人 ${r.owner}</small><div>${pbActions(r)}</div></article>`).join('')}).join(''):list.slice((page-1)*DRAWER_PAGE_SIZE,page*DRAWER_PAGE_SIZE).map(r=>{pbRemember(r);return `<article class="pb-ai-item"><div class="pb-subheading"><span class="tag ${r.level==='高危'?'red':'orange'}">${r.priority||'P1'} · ${r.level}</span><small>${chains[r.chain]}</small></div><h3>${esc(r.name)}</h3><p>${esc(r.issue)}</p>${tab==='advice'?`<div class="pb-plan">${esc(pbPlan(r))}</div>`:''}<dl><dt>责任采购</dt><dd>${r.owner}</dd><dt>计划完成</dt><dd>${r.due||shiftDate(end,3)}</dd><dt>证据来源</dt><dd>${esc(r.source||'人工新增关键事项')}</dd></dl><div class="pb-inline-actions">${pbActions(r)}${pbState.role==='manager'?pbBtn('编辑','ai-edit',r.key)+pbBtn('移除','ai-remove',r.key):''}</div></article>`}).join('');
 pbModal('采购部 AI 智能诊断',`<div class="pb-ai-drawer"><div class="pb-subheading"><small>更新至 ${end}</small>${pbBtn('刷新诊断','ai-refresh',tab)}</div><div class="pb-tabs tabs">${[['key','关键事项'],['deviation','偏差诊断'],['advice','输出建议'],['pending','待闭环']].map(([k,n])=>`<button data-pb-ai-tab="${k}" class="${tab===k?'active':''}">${n}</button>`).join('')}</div><div class="pb-tabs tabs">${[['day','本日'],['week','本周'],['month','本月']].map(([k,n])=>`<button data-pb-ai-range="${k}" class="${range===k?'active':''}">${n}</button>`).join('')}</div><div class="pb-subheading"><small>${start} — ${end}</small>${pbState.role==='manager'?pbBtn('＋ 新增事项','ai-add','new'):''}</div>${content||'<div class="dp-empty">当前范围暂无诊断事项</div>'}${listPager(list.length,page,DRAWER_PAGE_SIZE,{attr:"data-key",extra:{"data-pb-action":"ai-page"}})}</div>`,true);$('#dialogactions').insertAdjacentHTML('afterbegin','');}
function pbEditAI(r){if(pbState.role!=='manager')return;pbModal(r?'编辑关键事项':'新增关键事项',`<form class="dp-form" id="pb-ai-edit-form"><label class="full">事项内容<input name="name" required minlength="3" value="${esc(r?.name||'')}"></label><label>所属品类<select name="chain">${chains.map((n,i)=>`<option value="${i}" ${i===(r?.chain??+(pbState.chain==='all'?0:pbState.chain))?'selected':''}>${n}</option>`).join('')}</select></label><label>优先级<select name="priority">${['P0','P1','P2'].map(n=>`<option ${n===(r?.priority||'P1')?'selected':''}>${n}</option>`).join('')}</select></label><label>责任采购<select name="owner">${pbPeople.map(n=>`<option ${n===r?.owner?'selected':''}>${n}</option>`).join('')}</select></label><label>计划完成<input type="date" name="due" required min="${pbDate()}" value="${r?.due&&r.due>=pbDate()?r.due:shiftDate(pbDate(),3)}"></label><label class="full">问题及行动要求<textarea name="issue" required minlength="10">${esc(r?.issue||'')}</textarea></label><label class="full">修改原因<input name="reason" required minlength="5"></label><button class="btn primary" type="submit">保存事项</button></form>`);$('#pb-ai-edit-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),next={...r,key:r?.key||'MANUAL-'+Date.now(),kind:r?.kind||'manual',name:f.get('name'),chain:+f.get('chain'),owner:f.get('owner'),priority:f.get('priority'),level:f.get('priority')==='P0'?'高危':'中风险',due:f.get('due'),issue:f.get('issue'),date:bounds(pbPeriod(pbModalSection)).cutoff,tier:r?.tier??0,period:{...pbPeriod(pbModalSection)},source:r?.source||'部长新增事项'};if(pbPeople.indexOf(next.owner)%4!==next.chain){toast('责任采购与所属品类不一致，请调整后保存');return}pbAudit(r?'编辑关键事项':'新增关键事项',next.key,r||null,{...next,reason:f.get('reason')});if(r)pbStore.edits[r.key]=next;else pbStore.custom.unshift(next);if(pbSave()){renderPurchasing();pbWith('ai',()=>pbOpenAI('key'))}};}
function pbRemoveAI(r){if(pbState.role!=='manager'||!r)return;pbModal('移除关键事项',`<form class="dp-form" id="pb-ai-remove-form"><div class="full dp-callout">${esc(r.name)}<br>仅移出关键事项清单，原始风险台账保留。</div><label class="full">移除原因<input name="reason" required minlength="5"></label><button type="submit" class="btn primary">确认移除并留痕</button></form>`);$('#pb-ai-remove-form').onsubmit=e=>{e.preventDefault();pbStore.removed.push(r.key);pbAudit('移除关键事项',r.key,r,new FormData(e.target).get('reason'));if(pbSave()){renderPurchasing();pbWith('ai',()=>pbOpenAI('key'))}}}
function pbDispatch(r){if(!r)return;const existing=pbTask(r);if(existing)return pbTaskDetail(existing.id);const selected=pbPeople.filter(n=>pbPeople.indexOf(n)%4===r.chain);pbRemember(r);pbModal('下发采购整改任务',`<form class="dp-form" id="pb-dispatch-form"><div class="full dp-callout"><b>${esc(r.name)}</b><br>${esc(r.issue||'采购执行与交付跟进')}</div><label>指派责任采购<select name="owner">${selected.map(n=>`<option ${n===r.owner?'selected':''}>${n}</option>`).join('')}</select></label><label>预计完成日期<input name="due" type="date" required min="${pbDate()}" value="${r.due>=pbDate()?r.due:shiftDate(pbDate(),3)}"></label><label class="full">整改方案（可编辑）<textarea name="plan" required minlength="15">${esc(pbPlan(r))}</textarea></label><label class="full">验收标准<textarea name="criteria" required minlength="10">交付对应业务凭证，核实卡点解除，原始台账有明确验证结论。</textarea></label><label class="dp-check full"><input type="checkbox" name="notify" checked>钉钉通知责任人</label><small class="full dp-notice">当前为演示通知，保存通知记录；未连接真实钉钉服务。</small><button class="btn primary" type="submit">确认下发</button></form>`);$('#pb-dispatch-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),source={...r};delete source.raw;const t={id:'PB-TASK-'+Date.now(),key:r.key,name:r.name,chain:r.chain,tier:r.tier??0,owner:f.get('owner'),due:f.get('due'),plan:f.get('plan'),criteria:f.get('criteria'),state:'待执行',notify:f.get('notify')?'演示通知已记录':'未通知',source,period:{...pbPeriod(pbModalSection)},createdDate:bounds(pbPeriod(pbModalSection)).cutoff,logs:[{at:new Date().toISOString(),actor:pbActor(),action:'下发任务'}]};pbStore.tasks.unshift(t);pbAudit('下发采购任务',t.id,null,t);if(pbSave()){renderPurchasing();pbTaskDetail(t.id);toast('已写入整改任务')}};}
function pbTaskDetail(id){const t=pbStore.tasks.find(t=>t.id===id);if(!t||!pbScope(t))return;const accept=t.state==='待验收'&&pbState.role==='manager',done=t.state==='已验收';pbModal(t.name+' · 执行与验收',`<div class="dp-flow">${['待执行','执行中','待验收','已验收'].map(s=>`<span class="${t.state===s?'active':''}">${s}</span>`).join('')}</div><div class="dp-detail-grid">${[['任务编号',t.id],['责任采购',t.owner],['预计完成',t.due],['当前状态',t.state],['通知状态',t.notify],['业务范围',chains[t.chain]]].map(([l,v])=>`<div><small>${l}</small><strong>${esc(v)}</strong></div>`).join('')}</div><h3>执行方案</h3><div class="pb-plan">${esc(t.plan)}</div><div class="dp-callout"><b>验收标准</b><p>${esc(t.criteria)}</p>${t.evidence?'<p>交付凭证：'+esc(t.evidence)+'</p>':''}</div>${done?`<div class="tag green">已于 ${t.closedDate} 验收，来源预警已销项</div>`:`<form class="dp-form" id="pb-task-form"><label class="full">${accept?'验收意见':'执行进展 / 交付凭证'}<textarea name="evidence" required minlength="10">${esc(accept?'':t.evidence||'')}</textarea></label>${accept?`<label>实际完成日期<input type="date" name="actual" required min="${t.createdDate}" max="${DATA_CUTOFF}" value="${t.actualDate||DATA_CUTOFF}"></label><label>闭环验证日期<input type="date" name="closed" required min="${t.actualDate||t.createdDate}" max="${DATA_CUTOFF}" value="${DATA_CUTOFF}"></label>${t.source.kind==='project'?`<label class="full">恢复计划上线日期<input name="recovery" type="date" required min="${DATA_CUTOFF}" value="${shiftDate(DATA_CUTOFF,7)}"></label>`:''}<label class="dp-check full"><input type="checkbox" name="verified" required>已核对交付凭证，风险解除并满足验收条件</label>`:''}<div class="full pb-inline-actions">${accept?'<button class="btn primary" type="submit" name="action" value="accept">验收通过并销项</button><button class="btn" type="submit" name="action" value="reject" formnovalidate>退回整改</button>':t.state==='待验收'?'<span class="dp-notice">已提交，等待采购部部长验收。</span>':'<button class="btn" type="submit" name="action" value="progress">保存执行进展</button><button class="btn primary" type="submit" name="action" value="submit">提交验收</button>'}</div></form>`}<h3 style="margin-top:20px">操作轨迹</h3>${t.logs.map(l=>`<div class="dp-log">${esc(l.action)} · ${esc(l.actor)}<small>${l.at}</small></div>`).join('')}`);if($('#pb-task-form'))$('#pb-task-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),action=e.submitter?.value,text=f.get('evidence')?.trim();if(!text||text.length<10){toast('请填写至少 10 字的进展或审核依据');return}const before={...t};if(action==='accept'){if(pbState.role!=='manager')return;if(f.get('closed')<f.get('actual')){toast('验证日期不能早于实际完成日期');return}t.state='已验收';t.actualDate=f.get('actual');t.closedDate=f.get('closed');t.review=text;t.recovery=f.get('recovery')}else if(action==='reject'){if(pbState.role!=='manager')return;t.state='退回整改';t.review=text}else{t.evidence=text;t.state=action==='submit'?'待验收':'执行中'}t.logs.push({at:new Date().toISOString(),actor:pbActor(),action:t.state+'：'+text});pbAudit('采购任务状态变更',t.id,before,t);if(pbSave()){renderAll();renderPurchasing();pbTaskDetail(id);toast(t.state==='已验收'?'验收完成，来源预警已同步销项':'执行状态已更新')}};}
function pbLifeDetail(key){const [stage,scope,channel,chain]=key.split('|'),rows=pbLifeRecords(+stage,scope,channel,chain);pbModalList(lifeNames[+stage]+' · '+(scope==='year'?'年度累计':'周期')+'完成明细',rows,['产品图片 / 名称','型号','品类','品牌','完成日期','对应供应商','责任采购','完成记录'],r=>[pbProduct(r),r.model,chains[r.chain],r.brand,r.date,r.supplier,r.owner,r.id])}
function pbQuoteTable(){const rows=pbOrders().map((r,i)=>({...r,key:r.key+':quote',kind:'quote',phase:['首轮报价','样机报价','量产报价'][i%3],due:shiftDate(r.due,-7),quoted:i%4!==0,issue:i%4===0?'报价资料不完整，待核对模具费、翻新费与物料清单。':'报价已提交，等待成本复核。'}));rows.forEach(pbRemember);return `<div class="pb-grid-three">${pbMetric('待报价任务',rows.filter(r=>!r.quoted).length+'<em>项</em>','按采购订单关联报价')}${pbMetric('超期待报价',rows.filter(r=>!r.quoted&&r.due<pbDate()).length+'<em>项</em>','需补齐成本构成')}${pbMetric('报价及时率',pbPct(rows.filter(r=>r.quoted).length,rows.length),'已报价 / 全部报价任务')}</div>${pbPage('quotes',rows,['报价任务','供应商','报价阶段','计划报价日期','当前状态','责任采购','操作'],r=>[r.name,r.supplier,r.phase,r.due,r.quoted?'已报价':'待报价',r.owner,pbActions(r)])}`}
function pbDocumentsTable(){const kinds=['日报','周报','会议记录','供应商台账','样品台账','报价台账','翻新费台账','模具费台账'],kind=pbState.tabs.document||'0',rows=pbScores().flatMap(r=>r.raw.filter((d,i)=>kind==='0'||kind==='1'?kind==='0'||i%7===0:i%14===0).map(d=>({key:'PB-DOC-'+kind+'-'+r.name+'-'+d.date,kind:'document',name:kinds[+kind]+' · '+r.name,owner:r.name,chain:r.chain,tier:r.tier,date:d.date,level:d.noReport?'高危':d.missing?'中风险':'低风险',issue:d.noReport?'记录未提交':d.missing?'交付附件待补齐':'事项、量化结果与凭证完整',source:'采购过程记录 · '+kinds[+kind],state:d.noReport?'缺交':d.late?'迟交':'按期提交'})));rows.forEach(pbRemember);return pbTabs('document',kinds.map((n,i)=>[String(i),n]))+pbPage('documents',rows,['过程记录','责任采购','品类','日期','提交状态','完整性','操作'],r=>[r.name,r.owner,chains[r.chain],r.date,r.state,r.issue,pbActions(r)])}
function pbTargets(type){if(pbState.role!=='manager'){toast('目标配置由采购部部长维护');return}const stages=type==='supplier'?[0,1]:[0,1,2,3,4,5,6];pbModal(type==='supplier'?'供应商建设目标':'选品目标与爆品标准',`<form class="dp-form" id="pb-target-form">${stages.map(i=>{const key=periodKey()+':'+type+':'+i+':'+pbState.chain,value=pbStore.targets[key]??(type==='supplier'?Math.round(supplierData()[i].qt*(pbState.chain==='all'?1:.25)):pbSelectionTarget(i));return `<label>${type==='supplier'?['整机供应商','物料供应商'][i]+'新增':pbStages[i]+'目标'}<input type="number" min="0" step="1" required name="target-${i}" value="${value}"></label>`}).join('')}${type==='selection'?chains.map((n,i)=>`<label>${n}爆品销量标准<input type="number" min="1" step="1" required name="hot-${i}" value="${pbStore.hot[i]}"></label>`).join(''):''}<label class="full">配置原因<input name="reason" required minlength="5"></label><button class="btn primary">保存配置</button></form>`);$('#pb-target-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),before=JSON.parse(JSON.stringify(pbStore.targets));for(const i of stages)pbStore.targets[periodKey(pbPeriod(pbModalSection))+':'+type+':'+i+':'+pbState.chain]=+f.get('target-'+i);if(type==='selection')pbStore.hot=chains.map((_,i)=>+f.get('hot-'+i));pbAudit('更新采购目标',type,before,{targets:pbStore.targets,reason:f.get('reason')});if(pbSave()){renderPurchasing();closeModal();toast('已保存目标，实际数量按台账计算')}};}
function pbRules(){pbModal('采购部指标口径',dpTable(['指标','口径'],[['角色范围','部长查看全品类；产品链主按所属品类展示。当前为演示视角，正式权限需由服务端校验。'],['项目灯色','直接沿用总看板项目状态；文档的3/10天采购预警建议仅作采购关注阈值，不覆盖统一项目灯色。'],['新品口径','统一复用总看板上架≤120天的新品台账，保持跨看板退货率一致。'],['供应商数量','有效供应商储备 / 合作与总看板一致；采购总览另展示已淘汰历史记录。'],['人员五维评分','30 / 15 / 25 / 15 / 15 分；逐日计算，周期得分为每日五维得分平均。复核保留原始值与修改原因。'],['供应商质量','抽检质量问题比例≥0.5%预警，与销售总退货率分开计算。'],['选品转化','统计本期到达节点的记录；跨期转化可能超过100%，不强制截断。'],['生命周期','完成项、目标及分渠道分配复用总看板与产品部，不独立虚构完成数量。'],['通知与验收','演示通知只保存本地记录；验收需交付凭证与部长确认，不把点击完成直接视为业务指标达标。']]))}

