const srPreviousRender=renderRisks;renderRisks=function(){srPreviousRender();withPeriod('risk',()=>{for(const k of [3,4,5]){const card=$$('#riskrail .riskcard')[k];card.querySelector('.rhead').insertAdjacentHTML('afterend',`<div class="qr-card-filter"><label class="sr-filter-label">产品属性 <select data-risk-season="${k}" aria-label="${k===3?'库存':k===4?'滞销':'延期项目'}产品属性">${srSeasonOptions(k)}</select></label></div>`);for(const button of card.querySelectorAll('[data-riskitem]')){const id=+button.dataset.riskitem.split(',')[1],r=riskRows(k).find(r=>r.id===id),name=button.querySelector('.rname');if(r&&name)name.innerHTML=`${esc(r.name)}<small class="sr-card-attribute">${r.attribute}</small>`}if(!riskRows(k).length)card.insertAdjacentHTML('beforeend','<div class="empty">当前属性暂无风险产品</div>')}})};
