function svLevel(r){return `<span class="tag ${r.closed?'green':r.level==='高危'?'red':r.level==='中风险'?'orange':'blue'}">${r.closed?'已闭环':r.level==='高危'?'● 红灯':r.level==='中风险'?'● 黄灯':'一般提醒'}</span>${r.overdue?'<small class="red">整改逾期 · 已升级</small>':''}`;}
