function sdEvidence(r){return r.categoryId===0?`当前 ${r.value} 家 / 目标 ${r.target} 家，缺口 ${r.gap} 家`:r.categoryId===1?`${r.stage}延期 ${r.value} 天${r.impactLaunch?'，影响项目上线':''}`:r.categoryId===2?`缺失 ${r.value} 项：${r.missing.join('、')}`:r.categoryId===3?`当前 ${r.value} 星，低于 2 星准入预警线`:`${r.dimension}：${r.metric}；预警条件 ${r.rule}`;}
function sdImpact(r){return r.categoryId===0?'供方备选不足，项目交付与议价空间受限':r.categoryId===1?r.impactLaunch?'影响项目上线，需优先协调资源':'压缩后续评审与交付时间':r.categoryId===2?'影响准入及合作保障，存在合规风险':r.categoryId===3?'交付与品质稳定性不足':'影响供应稳定性，需专项改善';}
function sdDetail(r){if(!r)return;const t=pbTask(r),a=svAI(r);openModal(r.name+' · 风险详情',`<div class="sd-detail"><div class="sd-detail-title"><div><h2>${esc(r.name)}</h2><p>${sdNames[r.categoryId]} · ${chains[r.chain]}${r.categoryId===0?'':' · '+esc(r.supplier)}</p></div>${svLevel(r)}</div><div class="sr-callout ${r.level==='高危'?'danger':''}"><b>风险原因</b><p>${esc(sdEvidence(r))}</p></div>${svInfo([['对应项目',r.project],['责任采购',r.owner],['处理状态',r.state],['预计解决日期',t?.due||'待责任人确认']])}<div class="sd-detail-section"><h3>业务影响</h3><p>${esc(a.impact)}</p></div><div class="sd-detail-section sd-advice"><h3>✧ AI 建议</h3><p>${esc(a.resource)}</p></div>${t?`<div class="sd-detail-section"><h3>最新进展</h3><p>${esc(t.evidence||t.logs.at(-1)?.action||'等待责任采购更新')}</p>${r.overdue?`<p class="red">已逾期 ${svDays(bounds().cutoff,t.due)} 天，需采购负责人优先跟进。</p>`:''}</div>`:''}</div>`,false,periodLabel(periodFor('suppliers'))+' · 截至 '+bounds().cutoff);}
renderSuppliers=function(){withPeriod('suppliers',()=>{const all=sdRows(),red=all.filter(r=>r.level==='高危').length,overdue=all.filter(r=>r.overdue).length,rows=all.filter(r=>r.categoryId===sdState.category),pages=Math.max(1,Math.ceil(rows.length/5));sdState.page=Math.max(1,Math.min(sdState.page,pages));$('#suppliergrid').classList.add('sr-full');$('#suppliergrid').innerHTML=`<div class="sd-center"><div class="sd-summary"><span><b>${all.length}</b> 项待解决风险<span class="sd-divider">|</span><span class="red">${red} 项高危</span><span class="sd-divider">|</span>${overdue} 项逾期</span><small>高危风险优先展示</small></div><div class="sd-categories" role="tablist" aria-label="供应链风险分类">${sdNames.map((name,i)=>{const group=all.filter(r=>r.categoryId===i);return `<button type="button" role="tab" aria-selected="${sdState.category===i}" class="${sdState.category===i?'active':''}" data-sd-category="${i}"><span>${name}</span><strong>${group.length}<em>项</em></strong><small>${group.filter(r=>r.level==='高危').length} 项高危</small></button>`}).join('')}</div><div class="sd-list-title"><b>${sdNames[sdState.category]}</b><small>共 ${rows.length} 项</small></div><div class="sd-table">${dpTable(['风险等级','风险事项','业务影响','责任采购','处理进度','操作'],rows.slice((sdState.page-1)*5,sdState.page*5).map(r=>{const t=pbTask(r);return [svLevel(r),`<b>${esc(r.name)}</b><small>${esc(sdEvidence(r))}</small>`,`<span>${sdImpact(r)}</span><small>${esc(r.project)}</small>`,r.owner,`<span class="${r.overdue?'red':''}">${r.overdue?'整改逾期':r.state}</span><small>${t?'预计 '+t.due:'待确认解决日期'}</small>`,`<button class="link" type="button" data-sd-detail="${esc(r.key)}">查看详情</button>`]}))}</div>${rows.length?'':'<div class="dp-empty">当前周期该类风险已全部解决</div>'}${listPager(rows.length,sdState.page,5,{attr:"data-sd-page"})}</div>`;});};
// The same director-level drilldown also applies to the supplier high-risk ranking.
const sdOperationalDetail=svDetail;svDetail=function(r){if(svState.context==='director')return withPeriod('suppliers',()=>sdDetail(r));return sdOperationalDetail(r);};
const sdPriorDescription=periodDescription;periodDescription=function(id){return id==='suppliers'?sdPriorDescription(id).replace(/<span>[^<]*<\/span>$/,'<span>风险与储备按截止日统计；新增目标、实际及红绿灯按所选周期计算。</span>'):sdPriorDescription(id);};
document.addEventListener('click',e=>{const b=e.target.closest('[data-sd-category],[data-sd-page],[data-sd-detail]');if(!b)return;if(b.hasAttribute('data-sd-category')){sdState.category=+b.dataset.sdCategory;sdState.page=1;renderSuppliers();}else if(b.hasAttribute('data-sd-page')){sdState.page=+b.dataset.sdPage;renderSuppliers();}else withPeriod('suppliers',()=>sdDetail(sdRows().find(r=>r.key===b.dataset.sdDetail)));});

const scView={kind:0,page:1};
function scActive(){return sdRows().filter(r=>r.categoryId===0&&r.ruleVersion==='category-v2');}
function scTask(r){const t=pbTask(r);return t&&t.createdDate<=bounds().cutoff?t:null;}
function scStatus(g){return scActive().filter(r=>r.categoryGroup===g.id);}
function scTotals(groups){return groups.reduce((a,g)=>{for(const k of ['quarterTarget','quarterActual','yearNew','yearTarget','yearActual','periodTarget','periodActual'])a[k]+=g[k];return a;},{quarterTarget:0,quarterActual:0,yearNew:0,yearTarget:0,yearActual:0,periodTarget:0,periodActual:0});}
// Compare actual progress with elapsed calendar days at the same data cutoff.
function scGoalStatus(actual,target,start,end,cutoff){
 const day=86400000,stamp=d=>Date.parse(d+'T00:00:00Z'),days=Math.round((stamp(end)-stamp(start))/day)+1,elapsed=Math.max(0,Math.min(days,Math.round((stamp(cutoff)-stamp(start))/day)+1)),progress=elapsed/days*100;
 if(!(target>0))return {tone:'neutral',label:'未设目标',progress,elapsed,days,rate:null};
 const rate=actual/target*100;
 if(!elapsed)return {tone:'neutral',label:'未开始',progress,elapsed,days,rate};
 const ok=actual*days>=target*elapsed;
 return {tone:ok?'green':'red',label:ok?'绿灯':'红灯',progress,elapsed,days,rate};
}
function scTargets(g){
 const year=periodFor().year,cutoff=g.cutoff||bounds().cutoff,quarter=g.quarter||Math.ceil(+cutoff.slice(5,7)/3),qStart=iso(new Date(Date.UTC(year,(quarter-1)*3,1))),qEnd=iso(new Date(Date.UTC(year,quarter*3,0))),q=scGoalStatus(g.periodActual,g.periodTarget,bounds().start,bounds().end,cutoff),y=scGoalStatus(g.yearActual,g.yearTarget,year+'-01-01',year+'-12-31',cutoff);
 const indicator=(status,start,end)=>`<span class="sc-goal-status ${status.tone}" title="${start} 至 ${end}；截至 ${cutoff}，已过 ${status.elapsed}/${status.days} 天。完成率低于时间进度为红灯，达到或超过为绿灯。"><i aria-hidden="true"></i>${status.label}<em>时间进度 ${fmt(status.progress,1)}%</em></span>`;
 return `<div class="sc-targets">${[[{month:'本月目标',quarter:'本季度目标',year:'本年度目标'}[periodFor().mode],g.periodTarget+' 家','新增供应商目标',null],[word()+'实际达成',g.periodActual+' 家','完成率 '+pbPct(g.periodActual,g.periodTarget),q,bounds().start,bounds().end],['本年度新增',g.yearNew+' 家','按新增供应商去重',null],['本年度目标',g.yearTarget+' 家','全年新增目标',null],['年度实际达成',pbPct(g.yearActual,g.yearTarget),g.yearActual+' / '+g.yearTarget+' 家',y,year+'-01-01',year+'-12-31']].map(([label,value,sub,status,start,end])=>`<div${status?' data-sc-goal="'+(status===q?'quarter':'year')+'"':''}><small>${label}</small><b class="${status?'sc-goal-value '+status.tone:''}">${value}</b><span>${sub}</span>${status?indicator(status,start,end):''}</div>`).join('')}</div>`;
}
function scCount(g,m){const n=g.counts[m.key],gap=Math.max(0,m.target-n);return `<b class="${gap?'red':'green'}">${gap?'缺 '+gap+' 家':'已达标'}</b><small><button type="button" class="link sc-existing-count" data-sc-members="${g.id}" data-sc-stage="${m.key}" aria-label="查看${g.name}${m.label}已有${n}家供应商">已有 ${n} 家</button><span> · 标准 ${m.target} 家</span></small>`;}
function scRosterRows(g,stage){return stage==='all'?[...new Map(g.rows.map(s=>[s.key,s])).values()]:(g.pool[stage]||[]);}
function scRoster(g){let stage='all',page=1;const size=DRAWER_PAGE_SIZE,root=$('#sc-roster');if(!root)return;const paint=()=>{const rows=scRosterRows(g,stage),pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(page,pages);root.innerHTML=`<div class="sc-roster-heading"><h3>现有供应商 <span class="sc-muted">${rows.length} 家</span></h3><small>截至 ${g.cutoff}</small></div><div class="tabs sc-roster-tabs">${[{key:'all',label:'全部',count:scRosterRows(g,'all').length},...scMetricsFor(g).map(m=>({...m,count:g.counts[m.key]}))].map(m=>`<button type="button" data-sc-roster-stage="${m.key}" class="${stage===m.key?'active':''}">${m.label} ${m.count}</button>`).join('')}</div><div class="sc-roster-table">${dpTable(['供应商名称','注册时间','合作产品','采购人员','当前状态'],rows.slice((page-1)*size,page*size).map(s=>[`<b>${esc(s.name)}</b><small>${esc(s.code)}</small>`,s.date,esc(s.cooperationProducts||'暂无合作'),esc(s.owner),s.strategic?'战略合作':esc(s.state)]))}</div>${rows.length?'':'<div class="dp-empty">当前范围暂无'+(scMetrics.find(m=>m.key===stage)?.label||'')+'供应商</div>'}${listPager(rows.length,page,size,{attr:"data-sc-roster-page"})}`;};root.scSelect=key=>{stage=key;page=1;paint();root.scrollIntoView({block:'start',behavior:'smooth'})};root.onclick=e=>{const tab=e.target.closest('[data-sc-roster-stage]'),pager=e.target.closest('[data-sc-roster-page]');if(tab){stage=tab.dataset.scRosterStage;page=1;paint()}else if(pager){page=+pager.dataset.scRosterPage;paint()}};paint();}
function scMaterialTable(rows){return dpTable(['品牌','核心物料','准入储备缺口','风险状态','责任采购','操作'],rows.map(g=>[`<b>${g.brand}</b><small>${g.grade}级品牌</small>`,g.material,scCount(g,scMetricsFor(g)[0]),`<span class="tag ${g.counts.admission<5?'red':'green'}">${g.counts.admission<5?'● 红灯':'● 绿灯'}</span>`,g.owner,`<button type="button" class="link" data-sc-detail="${g.id}">查看详情</button>`]));}
function scOverview(){const groups=scGroups().filter(g=>g.kind===scView.kind),active=scActive(),rows=groups.filter(g=>active.some(r=>r.categoryGroup===g.id)).sort((a,b)=>Number(scStatus(b).some(r=>r.level==='高危'))-Number(scStatus(a).some(r=>r.level==='高危'))||scStatus(b).length-scStatus(a).length),pages=Math.max(1,Math.ceil(rows.length/5)),total=scTotals(groups);scView.page=Math.max(1,Math.min(scView.page,pages));return `<div class="sc-overview"><div class="sc-toolbar"><div class="tabs"><button data-sc-kind="0" class="${scView.kind===0?'active':''}">整机供应商</button><button data-sc-kind="1" class="${scView.kind===1?'active':''}">物料供应商</button></div><span>${scView.kind===1?'A / B 级品牌 · 核心物料准入储备 &lt;5 家标红':'三级类目准入储备 &lt;3 家预警'}</span></div>${scTargets(total)}<div class="sd-list-title"><b>${scView.kind===1?'核心物料不足':'三级类目储备不足'} <span class="sc-muted">${rows.length} ${scView.kind===1?'项':'个类目'}</span></b><small>目标为当前类型合计 · ${periodLabel()}</small></div><div class="sc-table ${scView.kind===1?'sc-material-table':''}">${scView.kind===1?scMaterialTable(rows.slice((scView.page-1)*5,scView.page*5)):dpTable(['三级类目','准入储备缺口','责任采购','操作'],rows.slice((scView.page-1)*5,scView.page*5).map(g=>[`<b>${g.name}</b><small>${g.path}</small>`,...scMetricsFor(g).map(m=>scCount(g,m)),g.owner,`<button type="button" class="link" data-sc-detail="${g.id}">查看详情</button>`]))}</div>${!rows.length?'<div class="dp-empty">当前范围的供应商储备均已达标</div>':''}${listPager(rows.length,scView.page,5,{attr:"data-sc-page"})}</div>`;}
function scDetail(id){const g=scGroups().find(x=>x.id===id);if(!g)return;const risks=scStatus(g);openModal(g.name+(g.coreMaterial?' · 核心物料不足':' · 类目供应商预警'),`<div class="sd-detail"><div class="sd-detail-title"><div><h2>${g.name}</h2><p>${g.kind?'物料供应商':'整机供应商'} · ${g.path}</p></div><span class="tag red">${risks.length} 项不足</span></div><div class="sc-pools">${scMetricsFor(g).map(m=>`<article><h3>${m.label}缺口</h3>${scCount(g,m)}</article>`).join('')}</div><div class="sd-detail-section sc-shortages"><h3>需要补充哪些供应商</h3>${dpTable([g.coreMaterial?'品牌 / 核心物料':'供应商类型 / 三级类目','缺口类型','待补数量','补充要求'],scMetricsFor(g).filter(m=>g.counts[m.key]<m.target).map(m=>[`${g.kind?'物料供应商':'整机供应商'}<small>${esc(g.path)}</small>`,m.label,`<b class="red">缺 ${m.target-g.counts[m.key]} 家</b>`,esc({intent:'开发可供应'+g.name+'的候选供方，完成初筛与意向确认',admission:'补充'+g.name+'合格供方，完成资质、样品及验厂评审',strategic:'引入'+g.name+'战略供方，确认产能保障并签署合作协议'}[m.key])]))}</div><section class="sd-detail-section" id="sc-roster" data-category="${g.id}"></section>${scTargets(g)}<div class="sd-detail-section"><h3>责任采购</h3><p>${g.owner} · ${g.coreMaterial?g.brand:chains[g.chain]}</p></div><div class="sd-detail-section sd-advice"><h3>✧ AI 建议</h3><p>围绕${g.name}补充供方：${risks.map(r=>`${scMetrics.find(m=>m.key===r.reserveStage).label}缺口 ${r.gap} 家`).join('、')}。由${g.owner}优先推进候选供方评估、验厂准入与战略合作洽谈，保障${g.coreMaterial?'核心物料':'该类目'}供应连续性。</p></div></div>`,false,periodLabel()+' · 数量截至 '+g.cutoff);}
let scRenderPeriod='';
const scPriorRender=renderSuppliers;renderSuppliers=function(){const key=periodKey(periodFor('suppliers'));if(key!==scRenderPeriod){scRenderPeriod=key;scView.page=1;sdState.page=1;}scPriorRender();if(sdState.category===0)withPeriod('suppliers',()=>{const anchor=$('#suppliergrid .sd-list-title');while(anchor.nextElementSibling)anchor.nextElementSibling.remove();anchor.outerHTML=scOverview();});};
const scPriorDetail=sdDetail;sdDetail=function(r){if(r?.ruleVersion==='category-v2')return scDetail(r.categoryGroup);return scPriorDetail(r);};
const scPriorRules=svRules;svRules=function(){scPriorRules();$('#dialogbody .sr-rules p').textContent='满足任一项即触发供应商数量不达标预警：自研品项目意向储备少于5家；自研品项目准入储备少于3家；三级产品类目准入储备少于3家；A级品牌（美的、海尔、苏泊尔）或B级品牌（康佳、创维）的电机、电池、电源线、线路板准入储备少于5家。按对应项目、类目或品牌与物料去重统计，等于阈值不预警。核心物料不足标红。';};
document.addEventListener('click',e=>{const b=e.target.closest('[data-sc-kind],[data-sc-page],[data-sc-detail]');if(!b)return;if(b.hasAttribute('data-sc-kind')){scView.kind=+b.dataset.scKind;scView.page=1;renderSuppliers();}else if(b.hasAttribute('data-sc-page')){scView.page=+b.dataset.scPage;renderSuppliers();}else withPeriod('suppliers',()=>scDetail(b.dataset.scDetail));});

// Director assignments use the same risk keys and task store as procurement execution.
function scInPeriod(period,fn){const previous=localPeriods.suppliers,context=svState.context,role=svState.role;localPeriods.suppliers={...period};svState.context='director';svState.role='manager';try{return withPeriod('suppliers',fn)}finally{if(previous)localPeriods.suppliers=previous;else delete localPeriods.suppliers;svState.context=context;svState.role=role}}
const scSummaryDetail=scDetail;
scDetail=function(id){
 scSummaryDetail(id);const g=scGroups().find(x=>x.id===id);if(!g)return;
 scRoster(g);
 const period={...periodFor()},risks=scStatus(g),available=risks.filter(r=>!scTask(r)),existing=risks.map(r=>scTask(r)).filter(Boolean),draftKey=periodKey(period)+'|'+bounds(period).cutoff+'|'+id,draft=svData().categoryDrafts?.[draftKey];
 const plan='1. 补足储备：'+risks.map(r=>`${scMetrics.find(m=>m.key===r.reserveStage).label}补 ${r.gap} 家，达到 ${r.target} 家`).join('；')+'。\n2. 采购推进评估、验厂准入及战略合作洽谈，按预计日期完成。\n3. 提交供应商编码和评审凭证，按'+(g.coreMaterial?'品牌与核心物料':'三级类目')+'去重核验达标后验收。';
 $('#dialogbody').insertAdjacentHTML('beforeend',`${existing.length?`<div class="sc-existing"><h3>已下发任务</h3>${existing.map(t=>`<div><span><b>${esc(t.name)}</b><small>${esc(t.owner)} · 预计 ${t.due} · ${esc(t.state)}</small></span><button class="link" type="button" data-sc-task="${esc(t.id)}">查看进度</button></div>`).join('')}</div>`:''}${available.length?`<form id="sc-assign" class="sc-assign"><h3>整改方案与任务分配</h3><fieldset class="sc-risk-choices"><legend>选择下发的预警事项</legend>${available.map(r=>`<label><input type="checkbox" name="risk" value="${esc(r.key)}" ${!draft?.keys||draft.keys.includes(r.key)?'checked':''}> ${scMetrics.find(m=>m.key===r.reserveStage).label}不足 <span class="red">缺口 ${r.gap} 家</span></label>`).join('')}</fieldset><label class="sc-full">详细处理方案（支持编辑）<textarea name="plan" required minlength="15" rows="5">${esc(draft?.plan??plan)}</textarea></label><label>处理负责人 <em>*</em><select name="owner" required><option value="">请选择处理负责人</option>${pbPeople.map(n=>`<option value="${n}" ${n===(draft?.owner??g.owner)?'selected':''}>${n}</option>`).join('')}</select></label><label>预计处理日期 <em>*</em><input type="date" name="due" required min="${g.cutoff}" value="${esc(draft?.due||'')}"><small>北京时间，当天 23:59 前完成</small></label><fieldset class="sc-collaborators sc-full"><legend>协调人员（可多选）</legend>${pbPeople.map(n=>`<label><input type="checkbox" name="collaborators" value="${n}" ${draft?.collaborators?.includes(n)?'checked':''}> ${n}</label>`).join('')}</fieldset><div class="sc-notification sc-full"><label><input type="checkbox" name="notify" ${draft?.notify===false?'':'checked'}> 通过钉钉通知处理负责人及协调人员 <span class="tag orange">未接入</span></label><p>当前保存本地任务与通知待发送记录，尚未向人员发送真实消息。</p><details><summary>预览钉钉通知内容与接收人员</summary><div id="sc-notice-preview"></div></details></div></form>`:'<div class="sc-complete">当前预警均已下发，可在上方查看进度。</div>'}`);
 $('#dialogactions').innerHTML=`<span class="sc-footer-note">演示数据 · 任务同步整改任务</span>${available.length?'<button class="btn small" id="sc-save" type="button">保存方案</button><button class="btn primary small" form="sc-assign" type="submit" id="sc-send">分配并加入钉钉待发</button>':''}<button class="btn small" id="modalclose">关闭</button>`;$('#modalclose').onclick=closeModal;
 document.querySelectorAll('[data-sc-task]').forEach(b=>b.onclick=()=>scInPeriod(period,()=>svTaskView(b.dataset.scTask)));
 const form=$('#sc-assign');if(!form)return;
 const values=()=>{const f=new FormData(form),owner=String(f.get('owner')||'');return {keys:f.getAll('risk'),owner,due:String(f.get('due')||''),plan:String(f.get('plan')||'').trim(),collaborators:f.getAll('collaborators').filter(n=>n!==owner),notify:!!f.get('notify')}};
 const notification=v=>({recipients:[v.owner,...v.collaborators].filter(Boolean),content:`【${g.coreMaterial?'核心物料不足':'三级类目储备不足'}整改】\n${g.coreMaterial?'品牌 / 核心物料':'类目'}：${g.path}\n统计周期：${periodLabel(period)}（${bounds(period).start} 至 ${g.cutoff}）\n供应商类型：${g.kind?'物料供应商':'整机供应商'}\n事项：${available.filter(r=>v.keys.includes(r.key)).map(r=>r.name).join('、')}\n处理负责人：${v.owner||'待选择'}\n预计处理日期：${v.due||'待填写'}（北京时间 23:59）\n处理方案：\n${v.plan}`,status:'待发送（未接入钉钉）'});
 const preview=()=>{const v=values(),n=notification(v);form.querySelectorAll('[name="collaborators"]').forEach(c=>{c.disabled=c.value===v.owner;if(c.disabled)c.checked=false});$('#sc-notice-preview').textContent=(v.notify?'接收人员：'+(n.recipients.join('、')||'待选择'):'未勾选通知，仅下发任务')+'\n\n'+n.content;$('#sc-send').textContent=v.notify?'分配并加入钉钉待发':'分配下发任务'};
 form.addEventListener('input',preview);form.addEventListener('change',preview);preview();
 $('#sc-save').onclick=()=>{const v=values();if(v.plan.length<15){toast('请填写至少 15 字的处理方案');return}const prior=svData().categoryDrafts;svData().categoryDrafts={...prior,[draftKey]:v};if(!svPersist()){svData().categoryDrafts=prior;return}toast('方案已保存，可继续分配任务')};
 form.onsubmit=e=>{e.preventDefault();scInPeriod(period,()=>{const v=values();if(!v.keys.length){toast('请至少选择一项预警');return}if(!pbPeople.includes(v.owner)||!v.due||v.due<g.cutoff||v.plan.length<15){toast('请填写负责人、有效预计处理日期和详细方案');return}const fresh=scStatus(g),selected=fresh.filter(r=>v.keys.includes(r.key)&&!scTask(r));if(!selected.length){toast('所选预警已下发或已解除，请查看现有任务');scDetail(id);return}const n=notification(v),now=Date.now(),tasks=selected.map((r,i)=>({id:'PB-SR-CAT-'+now+'-'+i,key:r.key,name:r.name,chain:r.chain,tier:r.tier,owner:v.owner,due:v.due,plan:v.plan,criteria:svAI(r).criteria,milestones:svDefaultMilestones(r,v.due),collaborators:v.collaborators,state:'待执行',source:{...r},period:{...period},createdDate:g.cutoff,notify:v.notify?'钉钉待发送（未接入）':'未通知',notification:v.notify?{...n}:null,logs:[{at:new Date().toISOString(),actor:'产品链总监',action:'分配整改至 '+v.owner+'，预计 '+v.due+' 完成'+(v.notify?'；已加入钉钉待发送记录':'')}],attachments:[]}));const before=[...pbStore.tasks],drafts=svData().categoryDrafts;pbStore.tasks.unshift(...tasks);svData().categoryDrafts={...drafts};delete svData().categoryDrafts[draftKey];if(!svPersist()){pbStore.tasks=before;svData().categoryDrafts=drafts;return}svRefreshUI();scDetail(id);toast('已下发 '+tasks.length+' 项整改任务'+(v.notify?'，钉钉通知已加入待发送记录':''));});};
};

// Reuse the detail roster instead of opening a second modal and losing assignment drafts.
document.addEventListener('click',e=>{const b=e.target.closest('[data-sc-members]');if(!b)return;const id=b.dataset.scMembers,stage=b.dataset.scStage;withPeriod('suppliers',()=>{if($('#sc-roster')?.dataset.category!==id)scDetail(id);$('#sc-roster')?.scSelect(stage);});});

