function rdRules(k){const range=k===0?'本月截至所选结束日，对比上月完整自然月；趋势使用所选日期。':k===6?'本期近30天，对比紧邻的前30天。':k===2?'截止日所在月份。':'采用当前榜单的截止日与统计周期。';return `<div class="rd-rule-content"><div class="rd-rule-scope"><b>统计范围</b><span>${range}</span></div>${table(['指标','怎么算','如何判定'],rdRuleRows(k).map(row=>row.map(esc)))}${k===0?'<p>退货、处罚规则适用抖音、天猫、京东、拼多多；快手、视频号仅启用进线环比规则，其他阈值待配置。</p>':k===1?'<p>多风险取最高等级，资金冻结按金额优先排序；拼多多三项指标为品质退款率、品质求助平台率、品质文本情感分。其他店铺类型不套用上述评分阈值。</p>':''}<p class="rd-rule-demo">演示数据 · 阈值沿用当前看板配置。</p></div>`}
function rdKind(){if($('#dialog').dataset.rdKind!==undefined)return +$('#dialog').dataset.rdKind;if($('#qr-handle-form'))return 0;const title=$('#dialogtitle').textContent;for(const [i,word] of ['品质','店铺','亏损','库存','滞销','延期项目','退货恶化'].entries())if(title.includes(word))return i;if(title.includes('重大风险事项')||title.includes('供应商')&&/预警|风险/.test(title))return 7;return -1}
function rdFold(node,label){if(!node||node.closest('.rd-fold'))return;const fold=document.createElement('details');fold.className='rd-fold';const summary=document.createElement('summary');summary.textContent=label;fold.append(summary);node.before(fold);fold.append(node)}
function rdTable(t){if(t.dataset.rdTable||t.classList.contains('rp-data-table')||t.closest('.up-todo-table'))return;t.dataset.rdTable='true';const hs=[...t.querySelectorAll('thead th')];if(!hs.length)return;t.classList.add('rd-readable-table');const weights=hs.map(h=>/名称|产品 \/|风险事件/.test(h.textContent)?2.1:/风险原因|核心风险|业务影响|轨迹|平台处罚风险等级/.test(h.textContent)?1.8:/主营产品|卡点/.test(h.textContent)?1.5:/序号|缩略图/.test(h.textContent)?.55:1),sum=weights.reduce((a,b)=>a+b,0);hs.forEach((h,i)=>h.style.setProperty('width',(weights[i]/sum*100)+'%','important'));for(const tr of t.querySelectorAll('tbody tr'))[...tr.cells].forEach((td,i)=>{if(hs[i])td.dataset.label=hs[i].textContent});}
function rdDecorate(){
 const dialog=$('#dialog'),body=$('#dialogbody'),title=$('#dialogtitle').textContent,k=rdKind(),list=k>=0&&(/完整榜单|重大风险事项/.test(title)),detail=k>=0&&!list&&(!!body.querySelector('#risk-handle-form,#qr-handle-form,.sd-detail,.project-control-detail,.ir-detail-summary'));
 dialog.classList.toggle('rd-list-dialog',list);dialog.classList.toggle('rd-detail-dialog',detail);if(!list&&!detail)return;
 body.querySelectorAll('table').forEach(rdTable);
 body.querySelectorAll('details.br-rules,details.qr-rules').forEach(d=>{if(d.dataset.rdRules)return;d.dataset.rdRules='true';d.innerHTML='<summary>指标口径与数据说明</summary>'+rdRules(k);d.open=false;d.querySelectorAll('table').forEach(rdTable)});
 const note=body.querySelector('.risk-data-note');if(note&&!note.dataset.rdRules&&!note.querySelector('details')){note.dataset.rdRules='true';const d=document.createElement('details');d.className='br-rules';d.dataset.rdRules='true';d.innerHTML='<summary>指标口径与数据说明</summary>'+rdRules(k);note.replaceWith(d);d.querySelectorAll('table').forEach(rdTable)}
 if(list){body.querySelectorAll('.br-risk-tags').forEach(tags=>{if(tags.dataset.rdCompact)return;tags.dataset.rdCompact='true';const items=[...tags.children];if(items.length>2){const rest=document.createElement('details');rest.className='rd-extra-causes';const summary=document.createElement('summary');summary.textContent='另 '+(items.length-1)+' 项风险';rest.append(summary,...items.slice(1));tags.append(rest)}})}
 if(!detail)return;
 const primary=body.querySelector('.risk-analysis'),anchor=body.querySelector('.risk-context')||body.querySelector('.qr-detail-metrics');if(primary&&anchor&&!primary.dataset.rdPosition){primary.dataset.rdPosition='true';anchor.after(primary)}
 rdFold(body.querySelector('.sd-detail .sc-targets'),'查看类目季度 / 年度目标');
 const links=body.querySelector('.pdd-link-panel');if(links)rdFold(links,'查看'+(links.querySelector('h3')?.textContent||'产品链接异常明细'));

 body.querySelectorAll('.risk-plan-head h3').forEach(h=>{if(h.textContent!=='处理方案 · 三步执行')h.textContent='处理方案 · 三步执行'});
 body.querySelectorAll('#risk-plan,#qr-plan').forEach(t=>{if(t.rows!==4)t.rows=4});
 for(const [selector,label] of [['.ir-detail-summary','查看库存汇总明细'],['.qrb-business','查看业务判定明细 / 配置目标'],['.sb-business','查看店铺风险判定明细'],['.rr-comparison','查看两期数据对照']])rdFold(body.querySelector(selector),label);
 body.querySelectorAll('.risk-ding details[open]').forEach(d=>{if(!d.dataset.rdPreview){d.dataset.rdPreview='true';d.open=false}});
 const analysis=body.querySelector('.risk-analysis');if(analysis&&!analysis.dataset.rdSummary){analysis.dataset.rdSummary='true';const ps=[...analysis.querySelectorAll(':scope > p')];if(ps.length>1){const head=document.createElement('div');head.className='rd-decision';const titles=['风险结论','重点动作'];for(const [i,p] of [ps[0],ps.at(-1)].entries()){const cell=document.createElement('div'),small=document.createElement('small');small.textContent=titles[i];cell.append(small,p.cloneNode(true));head.append(cell)}analysis.querySelector('h3').after(head);const evidence=document.createElement('div');evidence.className='rd-analysis-evidence';ps.forEach(p=>evidence.append(p));analysis.append(evidence);rdFold(evidence,'展开分析依据');}analysis.querySelectorAll(':scope > small').forEach(n=>n.hidden=true)}
}
const rdPreviousModal=openModal;openModal=function(...args){delete $('#dialog').dataset.rdKind;$('#dialog').classList.remove('rd-list-dialog','rd-detail-dialog');return rdPreviousModal(...args)};
// Legacy lists rebuild on filters/pagination. Decorate only new nodes, without replacing controls or handlers.
const rdObserver=new MutationObserver(()=>{rdObserver.disconnect();try{rdDecorate()}finally{rdObserver.observe($('#dialogbody'),{childList:true,subtree:true})}});rdObserver.observe($('#dialogbody'),{childList:true,subtree:true});

// Concise, data-specific director conclusions replace repetitive paragraphs.
const rdPreviousRiskDetail=riskDetail;riskDetail=function(k,id){rdPreviousRiskDetail(k,id);$('#dialog').dataset.rdKind=k;if(k===0||k===5)return;withPeriod('risk',()=>{const p=riskRows(k).find(r=>r.id===+id),a=$('#dialogbody .risk-analysis');if(!p||!a)return;const fact=k===1?`${p.channel} · 店铺分 ${fmt(p.score,2)}；${p.frozenAmount?'冻结 '+fmt(p.frozenAmount)+' 元':p.signals?.[0]?.label||p.risks?.[0]||'命中店铺风险规则'}`:k===2?`本月亏损 ${brLossAmount(p.loss)} 万元，亏损率 ${fmt(p.lossRate,1)}%。`:k===3?`高危货值 ${pfMoneyYuan((p.amount)*10000)}；首要风险：${irReasonText(p.reasons[0])}。`:k===4?`连续低动销 ${p.days} 天，积压 ${pfMoneyYuan((p.amount)*10000)}。`:`${p.channel}退货率 ${fmt(p.returnRate,1)}%，环比 ${rrSigned(p.growth,1,'%')}。`;
 const effect=['','影响店铺流量、回款与经营稳定性。','持续侵蚀单品收益，需确认止损方案。','占用库存资金，需按风险优先级处置。','积压占用资金，需结合季节窗口消化。','','退货成本及收退压力增加，需核实异常批次。'][k];
 a.innerHTML=`<h3>✧ AI 决策摘要</h3><div class="rd-decision">${[['风险信号',fact],['经营影响',effect],['优先动作',rdActions[k][1]]].map(([h,p])=>`<div><small>${h}</small><p>${esc(p)}</p></div>`).join('')}</div>`;a.dataset.rdSummary='true';if(k===4){const dl=$('.sr-evidence dl');if(dl)rdFold(dl,'查看滞销判定依据')}
 });};
qrAnalysis=function(o){const m=o.monthly;return m.risks.length?`${o.platform}命中 ${m.risks.join('、')}。${m.penaltyHit?'优先核对处罚与申诉时限。':'优先核查异常订单与问题批次。'}由品质、运营及客服协同处理，按目标复核验收。`:'当前平台未命中已配置预警规则，保持监测。'};

// The director supplier ranking remains complete and paginated instead of rendering hundreds of rows.
const rdPreviousMajor=svMajor;svMajor=function(){if(svState.context!=='director')return rdPreviousMajor();const rows=svScoped().filter(r=>!r.closed&&r.level==='高危');let page=1;openModal('供应商高危预警 · 完整榜单','<div class="rd-supplier-total"></div><div id="rd-supplier-table"></div><div id="rd-supplier-pages"></div><details class="br-rules"><summary>指标口径与数据说明</summary></details>',false,periodLabel(svContextPeriod()));const fill=()=>{const pages=Math.max(1,Math.ceil(rows.length/DRAWER_PAGE_SIZE));$('#dialogbody .rd-supplier-total').textContent=`共 ${rows.length} 项高危风险 · 逾期优先`;$('#rd-supplier-table').innerHTML=dpTable(['风险事件 / 触发条件','业务影响','责任部门 / 采购','发生日期','整改期限','当前状态','最近跟进 / 责任轨迹','操作'],rows.slice((page-1)*DRAWER_PAGE_SIZE,page*DRAWER_PAGE_SIZE).map(r=>{const t=pbTask(r);return[esc(r.name)+'<small>'+esc(r.rule)+'</small>',esc(svAI(r).impact),'采购部 / '+r.owner,r.date,t?.due||'待下发',r.state,esc(t?.logs.at(-1)?.action||'尚未下发')+'<small>'+esc(t?.logs.at(-1)?.actor||r.owner)+'</small>',svButton('查看详情','detail',r.key)]}));mountListPager($('#rd-supplier-pages'),rows.length,page,next=>{page=next;fill()});};fill()};

// Quantity checks use independent project, category and brand/material scopes.
function sqCategory(p){const leaf=[['扫地机器人','洗地机'],['破壁机','空气炸锅'],['循环扇','暖风机'],['剃须刀','吹风机']][p.chain].find(n=>p.name.includes(n));return leaf?scPaths[p.chain].find(path=>path.endsWith('/'+leaf)):chains[p.chain]+'/'+p.name;}
function sqUsesMaterial(p,material){if(material==='电池')return /扫地|洗地|无线|手持|剃须|牙刷|按摩|筋膜/.test(p.name);if(material==='电机')return /扫地|洗地|吸尘|除螨|破壁|料理|风|净化|剃须|牙刷|按摩|筋膜/.test(p.name);return true;}
function sqProjectCell(r,plain=false){const ps=r.relatedProjects||projects().filter(p=>p.id===r.projectId);if(!ps.length)return plain?'未关联项目':'<span class="sc-muted">未关联项目</span>';if(plain)return ps.map(p=>p.name+' / '+p.model).join('；');const p=ps[0];return `<div class="sw-project">${riskThumbnail(p.name)}<div><span>${esc(p.name)}</span><small>${esc(p.model)}</small>${ps.length>1?`<small>等 ${ps.length} 个项目</small>`:''}</div></div>`;}
const sqOriginalQuantity=scQuantityObservations;

scQuantityObservations=function(ledger){
 const ps=projects(),cutoff=bounds().cutoff;
 const category=sqOriginalQuantity(ledger).map(r=>{const related=ps.filter(p=>r.coreMaterial?p.brand===r.brand&&sqUsesMaterial(p,r.material):sqCategory(p)===r.categoryPath);return {...r,quantityRule:r.coreMaterial?'核心物料准入储备不足':'三级类目准入储备不足',name:(r.coreMaterial?r.brand+' · '+r.material:r.category)+' · 准入储备不足',relatedProjects:related,projectId:related[0]?.id??null,project:related.length?related.map(p=>p.name+' '+p.model).join('、'):'未关联项目'};});
 const self=ps.filter(p=>p.type.startsWith('自研'));
 const assigned=new Map(self.map(p=>[p.id,[]]));
 ledger.filter(s=>s.kind===0&&s.date<=cutoff).forEach(s=>{const eligible=self.filter(p=>sqCategory(p)===s.categoryPath);if(eligible.length)assigned.get(eligible[Math.abs(s.id)%eligible.length].id).push(s);});
 const project=self.flatMap(p=>[{key:'intent',label:'意向储备',target:5},{key:'admission',label:'准入储备',target:3}].map(m=>{const members=[...new Map(assigned.get(p.id).filter(s=>s.state===(m.key==='intent'?'意向储备':'准入储备')).map(s=>[s.key,s])).values()],value=members.length,rule='自研品产品寻源：'+m.label+'供应商数量 < '+m.target+' 家';return {kind:'supplier-risk',tier:0,chain:p.chain,supplierType:'整机',supplierKey:null,supplier:p.name+'项目储备池',originalState:m.key==='intent'?'意向储备':'准入储备',owner:members[0]?.owner||pbPeople[p.chain],key:svKey('project-reserve-'+p.id+'-'+m.key),categoryId:0,ruleVersion:'project-v1',quantityRule:'自研品'+m.label+'不足',categoryPath:sqCategory(p),reserveStage:m.key,dimension:svTabs[0],name:'自研 · '+p.name+' · '+m.label+'不足',project:p.name+' '+p.model,projectId:p.id,relatedProjects:[p],date:cutoff,due:shiftDate(cutoff,7),department:'采购部',value,target:m.target,gap:Math.max(0,m.target-value),metric:value+' / '+m.target+' 家',rule,level:'高危',issue:rule+'；当前 '+value+' 家，缺 '+Math.max(0,m.target-value)+' 家。',memberKeys:members.map(s=>s.key),source:'自研项目寻源台账 · 项目内供应商去重 · 演示数据'};}));
 return [...category,...project];
};
const sqDetailBase=sdDetail;
sdDetail=function(r){sqDetailBase(r);if(r?.categoryId!==0)return;const members=(r.memberKeys||[]).map(k=>svLedger().find(s=>s.key===k)).filter(Boolean);$('#dialogbody').insertAdjacentHTML('afterbegin',`<div class="sr-callout"><b>${esc(r.quantityRule||r.rule)}</b><p>${esc(r.rule)}；已有 ${r.value} 家，缺 ${r.gap} 家</p>${sqProjectCell(r)}${r.relatedProjects?.length>1?`<details class="sq-projects"><summary>查看关联项目（${r.relatedProjects.length}项）</summary>${r.relatedProjects.map(p=>sqProjectCell({relatedProjects:[p]})).join('')}</details>`:''}</div>`);if(r.ruleVersion==='project-v1')$('#dialogbody').insertAdjacentHTML('beforeend',`<h3>当前项目${r.reserveStage==='intent'?'意向':'准入'}储备供应商</h3>${dpTable(['供应商名称','注册时间','采购人员'],members.map(s=>[esc(s.name),s.date,esc(s.owner)]))}`);};

// Four warning views share the canonical risk ledger and its permission scope.
const swTypes=['供应商数量预警','引入延期预警','信息缺失预警','劣质供应商预警'];
const swStatuses=['已注册','意向储备','准入储备','已合作','已淘汰'];
function swSupplierState(r){return r.categoryId===0?({intent:'意向储备',admission:'准入储备',strategic:'已合作'}[r.reserveStage]||r.originalState):r.originalState;}
function swMissing(r){const contract=n=>/合同|协议|意向单|评估表/.test(n);return {fields:(r.missing||[]).filter(n=>!contract(n)),contracts:(r.missing||[]).filter(contract)};}
function swTimeline(r,s,cutoff){
 const date=d=>d&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&d<=cutoff?d:'未完成';
 const intent=s&&s.state!=='已注册'?date(shiftDate(s.date,2)):'未完成',admission=s&&['准入储备','已合作'].includes(s.state)?date(s.admitted):'未完成',cooperation=s?.state==='已合作'?date(s.cooperation):'未完成';
 const stages=['意向储备','准入储备','合作落地'],activeIndex=stages.indexOf(r.stage),activeDate=date(r.actualDate),dates=[intent,admission,cooperation];
 // A later milestone cannot be completed before the delayed prerequisite.
 let previous=null;
 return stages.map((stage,i)=>{const active=i===activeIndex;let actual=active?activeDate:dates[i];
  if(!active&&i>activeIndex&&(activeDate==='未完成'||actual<activeDate||previous==='未完成'))actual='未完成';
  if(!active&&i<activeIndex&&activeDate!=='未完成'&&actual>activeDate)actual='未完成';
  if(actual!=='未完成'&&previous&&previous!=='未完成'&&actual<previous)actual='未完成';
  previous=actual;
  return {stage,name:active||actual!=='未完成'?(s?.name||r.supplier):'—',date:actual,active,target:active?r.targetDate:null,days:active?r.value:0};});
}
function swHeaders(type){return [
 ['采购人员','供应商类型','供应商状态','产品类目','产品项目','预警事项 / 缺口','操作'],
 ['采购人员','产品类目','产品项目','意向储备供应商名称','意向储备完成时间','准入储备供应商名称','验厂完成时间','合作供应商名称','供应商落地确认时间','操作'],
 ['采购人员','供应商名称','供应商类型','供应商状态','缺失必填信息','缺失合同','操作'],
 ['采购人员','供应商名称','供应商类型','供应商状态','星级','操作']
 ][type];}
function swCells(r,ledger,cutoff,plain=false){
 const s=ledger.find(s=>s.key===r.supplierKey),category=r.coreMaterial?r.brand+' / '+r.material:r.categoryPath||chains[r.chain],project=r.projectId!=null?r.project:'未关联项目',state=swSupplierState(r),missing=swMissing(r),action=plain?'':`<button type="button" class="link" data-sw-detail="${esc(r.key)}">查看详情</button> <button type="button" class="link" data-sw-handle="${esc(r.key)}">立即处理</button>`,safe=v=>plain?String(v):esc(String(v)),list=items=>items.length?items.map(safe).join(plain?'、':'<br>'):'—';
 if(r.categoryId===0)return [safe(r.owner),safe(r.supplierType),safe(state),safe(category),sqProjectCell(r,plain),plain?r.name+'：缺 '+r.gap+' 家；已有 '+r.value+' / 目标 '+r.target+' 家':`<span class="tag ${r.level==='高危'?'red':'orange'}">${r.level==='高危'?'红灯':'黄灯'}</span><b>${esc(r.quantityRule||r.name)}</b><small>缺 ${r.gap} 家 · 已有 ${r.value} / 目标 ${r.target} 家</small>`,action];
 if(r.categoryId===1)return [safe(r.owner),safe(category),safe(project),...swTimeline(r,s,cutoff).flatMap(t=>[safe(t.name),plain?t.date+(t.active?'；目标 '+t.target+'；延期 '+t.days+' 天':''):`<span class="${t.active?'red':''}">${t.date}</span>${t.active?`<small>目标 ${t.target}</small><small class="red">延期 ${t.days} 天</small>`:''}`]),action];
 if(r.categoryId===2)return [safe(r.owner),safe(r.supplier),safe(r.supplierType),safe(state),list(missing.fields),list(missing.contracts),action];
 return [safe(r.owner),safe(r.supplier),safe(r.supplierType),safe(state),plain?r.value+' 星':`<b class="red">${r.value} 星</b><small class="red">低于 2 星</small>`,action];
}
function swOpenWarnings({procurement=false,redOnly=false,initialType=0}={}){
 if(svState.role==='other'){toast('当前视角无明细权限');return;}
 const period={...periodFor()},range=bounds(period),ledger=svLedger(),source=(procurement?pbSupplierRisks():svScoped()).filter(r=>!r.closed&&r.categoryId<4&&(!redOnly||r.level==='高危'));
 let type=initialType,page=1,owner='all',kind='all',state='all',query='';
 const run=fn=>{const previous=localPeriods.suppliers,context=svState.context;localPeriods.suppliers={...period};svState.context='director';try{return withPeriod('suppliers',fn)}finally{if(previous)localPeriods.suppliers=previous;else delete localPeriods.suppliers;svState.context=context;}};
 const select=(id,label,values)=>`<label>${label}<select id="${id}"><option value="all">全部</option>${values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`;
 openModal('供应商预警 · 全部',`<div class="sw-controls"><label>预警类型<select id="sw-type">${swTypes.map((name,i)=>`<option value="${i}" ${i===type?'selected':''}>${name}</option>`).join('')}</select></label>${select('sw-owner','采购人员',[...new Set(source.map(r=>r.owner))])}${select('sw-kind','供应商类型',['整机','物料'])}${select('sw-state','供应商状态',swStatuses)}<label>搜索<input id="sw-query" type="search" placeholder="供应商 / 品类 / 项目"></label></div><div class="sw-count" id="sw-count"></div><div id="sw-table"></div><div id="sw-pages"></div>`,false,periodLabel(period)+' · 截至 '+range.cutoff+(redOnly?' · 高危风险':''));
 $('#dialogsub').textContent=periodLabel(period)+' · '+range.start+' — '+range.cutoff+(redOnly?' · 高危风险':'');
 $('#dialog').classList.add('sw-dialog');
 
 const dispatch=r=>run(()=>{svDispatch(r);const form=$('#sr-dispatch');if(form){const submit=form.onsubmit;form.onsubmit=e=>run(()=>submit(e));}});
 const filtered=()=>source.filter(r=>r.categoryId===type&&(type!==3||r.value<2)&&(owner==='all'||r.owner===owner)&&(kind==='all'||r.supplierType===kind)&&(state==='all'||swSupplierState(r)===state)&&(!query||[r.supplier,r.name,r.quantityRule,r.project,r.categoryPath,r.brand,r.material,chains[r.chain]].join(' ').toLowerCase().includes(query.toLowerCase())));
 const fill=()=>{const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/DRAWER_PAGE_SIZE));page=Math.min(page,pages);$('#sw-count').textContent=swTypes[type]+' · '+rows.length+' 条'+(type===3?' · 星级＜2星触发预警':'');$('#sw-table').innerHTML=dpTable(swHeaders(type),rows.slice((page-1)*DRAWER_PAGE_SIZE,page*DRAWER_PAGE_SIZE).map(r=>swCells(r,ledger,range.cutoff)));$('#sw-table table').classList.add('sw-table');const heads=swHeaders(type);$$('#sw-table tbody tr').forEach(tr=>[...tr.cells].forEach((td,i)=>td.dataset.label=heads[i]||''));mountListPager($('#sw-pages'),rows.length,page,next=>{page=next;fill()});};
 $('#sw-type').onchange=e=>{type=+e.target.value;page=1;fill()};for(const [id,set] of [['sw-owner',v=>owner=v],['sw-kind',v=>kind=v],['sw-state',v=>state=v]])$('#'+id).onchange=e=>{set(e.target.value);page=1;fill()};$('#sw-query').oninput=e=>{query=e.target.value.trim();page=1;fill()};
 
 $('#sw-table').onclick=e=>{const button=e.target.closest('[data-sw-detail],[data-sw-handle]');if(!button)return;const key=button.dataset.swDetail||button.dataset.swHandle,r=source.find(r=>r.key===key);if(!r||!svPermission(r))return;run(()=>{if(button.dataset.swHandle){if(r.categoryId===0&&r.categoryGroup){scDetail(r.categoryGroup);$('#sc-assign')?.scrollIntoView({block:'start'});}else dispatch(r);}else{svDetail(r);if(r.categoryId!==0||!r.categoryGroup){$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn primary small" id="sw-detail-handle">立即处理</button>');$('#sw-detail-handle').onclick=()=>dispatch(r);}if(r.categoryId===1){const cells=swCells(r,ledger,range.cutoff,true);$('#dialogbody').insertAdjacentHTML('afterbegin',svInfo(swHeaders(1).slice(0,-1).map((h,i)=>[h,cells[i]])));}}});};fill();
}
