 if(type===2){const agreed=6000+i*1000,moldUnit=4+i%4*1.5,picked=i<10?agreed+(i%3)*400:agreed-1800,amortized=i<10?i===8?picked:agreed:picked;Object.assign(r,{moldTotal:round(agreed*moldUnit),moldUnit,agreed,picked,amortized,amortizedAmount:round(amortized*moldUnit)});if(i>=14)Object.assign(r,{moldTotal:0,agreed:0,picked:0,amortized:0,amortizedAmount:0});}
