 if(type===4){const [name,average,unit,source]=materials[i],swing=i<10?[.08,-.075,0,.11,-.09][i%5]:i===10?.05:i===11?-.05:.02,previousAverage=i<10&&i%3===2?round(average/1.08):average;Object.assign(r,{name,model:'',category:'大宗原材料',unit,source:source+'（模拟行情，非实时数据）',today:round(average*(1+swing)),lastToday:round(average*.96),average,lastAverage:previousAverage});if(i>=14)Object.assign(r,{average:0,lastAverage:0});}
