function cwRecordSource(period=pbPeriod('risk')){return cwDataMode==='demo'?cwDemoRecords(period):cwStore.records;}
function cwDownloadDemo(type){const rows=cwDemoRecords().filter(r=>r.type===type);downloadCsv(cwFields[type].map(f=>f.label),rows.map(r=>cwFields[type].map(f=>f.computed?'':r[f.key]??'')),cwTypes[type]+'-测试数据');}
const cwCommitImported=cwCommit;cwCommit=function(...args){const batch=cwCommitImported(...args);if(batch)cwSetDataMode('imported');return batch;};

function cwParseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false,closed=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'){if(text[i+1]==='"'){cell+='"';i++}else{quoted=false;closed=true}}else cell+=ch;}else if(ch==='"'){if(cell||closed)throw Error('CSV引号格式错误');quoted=true;}else if(ch===','){row.push(cell);cell='';closed=false;}else if(ch==='\r'||ch==='\n'){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell='';closed=false;}else{if(closed&&!/\s/.test(ch))throw Error('CSV引号后存在多余字符');cell+=ch;}}if(quoted)throw Error('CSV存在未闭合引号');if(cell||row.length){row.push(cell);rows.push(row)}return rows.filter(r=>r.some(c=>String(c).trim()));}
