async function cwReadFile(file){if(file.size>5*1024*1024)throw Error('单次文件不能超过5MB');if(/\.xlsx$/i.test(file.name))return cwReadXlsx(await file.arrayBuffer());if(!/\.csv$/i.test(file.name))throw Error('请选择xlsx或CSV文件；旧版xls请另存为xlsx');const data=await file.arrayBuffer();let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(data)}catch(_){text=new TextDecoder('gb18030').decode(data)}return cwParseCSV(text);}
function cwValidate(type,table,images={}){const fields=cwFields[type],errors=[],valid=[],seen=new Set();if(table.length<2)return {valid,errors:[{row:1,field:'数据',message:'文件没有数据行'}]};if(table.length>3001)return {valid,errors:[{row:1,field:'数据',message:'单次最多3000条，请拆分文件'}]};const headers=table[0].map(s=>String(s).trim());const expected=new Set(fields.map(f=>f.label));headers.forEach((h,i)=>{if(!expected.has(h))errors.push({row:1,field:h||'第'+(i+1)+'列',message:'模板外字段，请使用当前类型模板'});if(headers.indexOf(h)!==i)errors.push({row:1,field:h,message:'表头重复'})});fields.filter(f=>f.required&&!headers.includes(f.label)).forEach(f=>errors.push({row:1,field:f.label,message:'缺少必填列'}));if(errors.length)return {valid,errors};
 for(let i=1;i<table.length;i++){const source=table[i],r={},start=errors.length;if(source.length>headers.length)errors.push({row:i+1,field:'数据列',message:'数据列数多于表头，请检查CSV分隔符或使用xlsx'});for(const f of fields){let v=String(source[headers.indexOf(f.label)]??'').trim();const error=message=>errors.push({row:i+1,field:f.label,message});if(!v){if(f.required)error('必填项为空');else r[f.key]='';continue}if(['number','integer','percent','signed'].includes(f.type)){const clean=v.replace(/,/g,'').replace(/%$/,'');if(!(f.type==='signed'?/^[+-]?\d+(?:\.\d+)?$/:/^\d+(?:\.\d+)?$/).test(clean))error('请填写非负数值'+(f.type==='percent'?'；5%填5或5%':''));else{r[f.key]=+clean;if(!Number.isFinite(r[f.key])||Math.abs(r[f.key])>Number.MAX_SAFE_INTEGER)error('数值超出可精确处理范围');if(f.type==='integer'&&!Number.isSafeInteger(r[f.key]))error('台数必须为整数');if(f.type==='percent'&&r[f.key]>100)error('百分比须在0到100之间')}}else if(f.type==='date'){v=v.replaceAll('/','-');const d=new Date(v+'T00:00:00Z');if(!/^\d{4}-\d{2}-\d{2}$/.test(v)||!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==v)error('日期格式为YYYY-MM-DD');else if(v>new Date().toLocaleDateString('sv-SE'))error('数据日期不能晚于今天');else r.date=v;}else if(f.type==='image'){const img=images[v]||v;if(!/^https:\/\//i.test(img)&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(img))error('图片请填写https地址，或选择对应文件名的PNG/JPG/WebP图片');else r.image=img;}else{if(v.length>250)error('内容不能超过250字');r[f.key]=v;}}
 if(r.chainName){r.chain=chains.indexOf(r.chainName);if(r.chain<0)errors.push({row:i+1,field:'所属品链',message:'请填写：'+chains.join('、')});}r.tier=0;
 if(type===1&&r.quarterSaving>r.yearSaving)errors.push({row:i+1,field:'季度累计降本额',message:'不能大于年度累计降本额'});
 if(type===1&&r.cut>r.sealed)errors.push({row:i+1,field:'单台累计降价额',message:'不能大于封样报价'});
 if(type===2&&r.amortized>r.picked)errors.push({row:i+1,field:'实际摊销台数',message:'不能大于实际提货台数'});
 const key=cwIdentity(type,r)+'|'+r.date;if(seen.has(key))errors.push({row:i+1,field:'记录编号',message:'同编号、报价阶段、日期在文件内重复'});seen.add(key);
 if(errors.length===start){const result=cwEvaluate(type,r);for(const f of fields.filter(f=>f.computed&&r[f.key]!==''&&r[f.key]!==undefined)){const expected=result.d[f.key];if(expected===null||Math.abs(r[f.key]-expected)>.011)errors.push({row:i+1,field:f.label,message:'与基础指标计算结果不符，预期 '+(expected===null?'无法计算':expected.toFixed(2))+'；可留空自动计算'});}}
 if(errors.length===start)valid.push({...r,type,sourceRow:i+1});
 }return {valid,errors};}
function cwTemplate(type){downloadCsv(cwFields[type].map(f=>f.label),[],cwTypes[type]+'-导入模板');}

function cwProductImage(r){return r.image?`<img src="${esc(r.image)}" alt="${esc(r.name)}" loading="lazy" referrerpolicy="no-referrer">`:riskThumbnail(r.name);}
let cwSelected=0;
const cwNumber=(v,suffix='')=>!Number.isFinite(v)?'—':suffix.trim()==='元'?pfMoneyYuan(v):fmt(v,suffix==='%'?1:2)+suffix;
function cwProduct(r){return `<div class="cw-product">${cwProductImage(r)}<span>${esc(r.name)}<small>${esc(r.model||'')}</small></span></div>`;}
function cwMetrics(items){return `<div class="cw-metrics">${items.map(([label,value,tone=''])=>`<div><small>${label}</small><span class="${tone}">${value}</span></div>`).join('')}</div>`;}
function cwHeaders(type){return [
 ['采购 / 类目 / 类型','产品名称 / 图片','供应商 / 报价阶段','目标 / 实际成本','目标 / 实际费率','预警原因 / 超出幅度','操作'],
 ['采购 / 类目 / 类型','产品名称 / 图片','供应商','封样报价 / 单台降本','累计降本额','降本进度','预警原因 / 超出幅度','操作'],
 ['采购 / 类目 / 类型','产品名称','模具摊销标准','提货 / 摊销台数','实际摊销金额','剩余台数 / 金额','预警原因 / 超出幅度','操作'],
 ['采购 / 类目 / 类型','产品名称','目标 / 预估','出厂价 / 联检费','退货 / 实际分摊','实际翻新费率','预警原因 / 超出幅度','操作'],
 ['物料名称 / 单位','当日 / 去年同期价','近30天 / 去年同期均价','涨跌金额','当日涨跌幅度','30天均价波动','预警原因 / 超出幅度','操作']
 ][type];}
function cwResultHTML(result,detailed=false){return `<div class="cw-result">${result.alerts?.length?result.alerts.map(a=>`<div class="cw-alert"><span>${esc(a.label)}</span><b>${esc(a.value)}</b>${a.extra?`<small>${esc(a.extra)}</small>`:''}${detailed?`<small class="cw-basis">${esc(a.basis)}</small>`:''}</div>`).join(''):`<span class="tag ${result.status==='正常'?'green':'orange'}">${result.status}</span>`}${result.pending.map(h=>`<small class="orange">${esc(h)}</small>`).join('')}</div>`;}

function cwCells(r){const {d}=r.result,base=`<b>${esc(r.owner)}</b><small>${esc(r.category||r.chainName)}</small><small>${esc(r.productType||'')}</small>`,money=v=>cwNumber(v,' 元'),pct=v=>cwNumber(v,'%'),n=v=>fmt(v,0)+' 台',details=`<button class="link" data-cw-detail="${esc(cwIdentity(r.type,r))}">查看详情</button>`,result=cwResultHTML(r.result);
 const cells=[
 ()=>[base,cwProduct(r),`${esc(r.supplier)}<small>${esc(r.stage)}</small>`,cwMetrics([['目标',money(r.target)],['实际',money(r.actual),r.actual>r.target?'red':'']]),cwMetrics(cwRates.map((name,i)=>[name,pct(r['targetRate'+i])+' / '+pct(r['actualRate'+i]),r['actualRate'+i]>r['targetRate'+i]?'red':''])),result,details],
 ()=>[base,cwProduct(r),esc(r.supplier),cwMetrics([['封样报价',money(r.sealed)],['单台累计降价额',money(r.cut)],['单台累计降本率',pct(d.unitSavingRate)]]),cwMetrics([['季度累计',money(r.quarterSaving)],['年度累计',money(r.yearSaving)],['年度目标',money(r.yearTarget)]]),cwMetrics([['实际进度',pct(d.actualProgress),r.result.hits.length?'red':''],['应完成进度',pct(d.expectedProgress)]]),result,details],
 ()=>[base,cwProduct(r),cwMetrics([['模具费摊销总额',money(r.moldTotal)],['单台摊销模具费',money(r.moldUnit)],['约定摊销台数',n(r.agreed)]]),cwMetrics([['实际提货台数',n(r.picked)],['实际摊销台数',n(r.amortized)]]),money(r.amortizedAmount),cwMetrics([['剩余摊销台数',n(d.remainingUnits)],['剩余摊销金额',money(d.remainingAmount)]]),result,details],
 ()=>[base,cwProduct(r),cwMetrics([['目标翻新费率',pct(r.refurbTarget)],['预估单台翻新费',money(r.estimated)]]),cwMetrics([['单台出厂价',money(r.price)],['联检确认单台翻新费',money(r.confirmed),r.confirmed>r.estimated?'red':'']]),cwMetrics([['工厂退货率',pct(r.factoryReturn)],['实际单台分摊翻新费',money(r.allocated)]]),`<span class="${d.actualRefurbRate>r.refurbTarget?'red':''}">${pct(d.actualRefurbRate)}</span>`,result,details],
 ()=>[`${esc(r.name)}<small>${esc(r.unit)}</small><small>${esc(r.source)}</small>`,cwMetrics([['当日价',cwNumber(r.today)],['去年同期当日价',cwNumber(r.lastToday)]]),cwMetrics([['近30天均价',cwNumber(r.average)],['去年同期30天均价',cwNumber(r.lastAverage)]]),cwNumber(d.change),`<span class="${Math.abs(d.changeRate)>5?'red':''}">${pct(d.changeRate)}</span>`,`<span class="${Math.abs(d.averageChange)>5?'red':''}">${pct(d.averageChange)}</span>`,result,details]
 ];return cells[r.type]();}

function cwOpen(type=cwSelected){cwSelected=type;let status='预警',query='',page=1;const period={...pbPeriod('risk')};const paint=()=>{const all=cwRows(type,period),rows=all.filter(r=>(status==='全部'||(status==='待补数据'?r.result.pending.length>0:r.result.status===status))&&(!query||[r.owner,r.name,r.model,r.supplier,r.category].join(' ').includes(query))),pages=Math.max(1,Math.ceil(rows.length/DRAWER_PAGE_SIZE));page=Math.min(page,pages);$('#cw-summary').innerHTML=`<span>${cwDataMode==='demo'?'测试数据':'已导入'} <b>${all.length}</b> 条</span><span class="red">预警 ${all.filter(r=>r.result.status==='预警').length}</span><span class="orange">待补数据 ${all.filter(r=>r.result.pending.length).length}</span><span class="green">正常 ${all.filter(r=>r.result.status==='正常').length}</span>`;$('#cw-rules').textContent=cwRules[type]+' 数据来源：'+cwSources[type];$('#cw-table').innerHTML=dpTable(cwHeaders(type),rows.slice((page-1)*DRAWER_PAGE_SIZE,page*DRAWER_PAGE_SIZE).map(cwCells));const heads=cwHeaders(type);$$('#cw-table tbody tr').forEach(tr=>[...tr.cells].forEach((td,i)=>td.dataset.label=heads[i]||''));if(!all.length)$('#cw-table').innerHTML='<div class="cw-empty"><b>当前范围尚无导入数据</b><p>下载本类模板，填写后导入即可自动判定预警。</p><button class="btn primary" id="cw-empty-import">导入数据</button></div>';else if(!rows.length)$('#cw-table').innerHTML='<div class="cw-empty">当前筛选无匹配记录，可切换“全部”查看已导入数据。</div>';mountListPager($('#cw-pages'),rows.length,page,next=>{page=next;paint()});$('#cw-empty-import')?.addEventListener('click',()=>cwImport(type));$('#cw-table').onclick=e=>{const b=e.target.closest('[data-cw-detail]');if(b){const r=rows.find(r=>cwIdentity(type,r)===b.dataset.cwDetail);if(r)cwDetail(r)}};$('#dialogsub').textContent=periodLabel(period)+' · 截至 '+cwRange(period).cutoff+(cwDataMode==='demo'?' · 模拟数据，仅供演示':' · 手工导入台账');};
 openModal('成本管控预警 · 全部',`<div class="cw-toolbar"><label>数据来源<select id="cw-source"><option value="demo" ${cwDataMode==='demo'?'selected':''}>测试数据</option><option value="imported" ${cwDataMode==='imported'?'selected':''}>导入数据</option></select></label><label>预警类型<select id="cw-type">${cwTypes.map((n,i)=>`<option value="${i}" ${i===type?'selected':''}>${n}</option>`).join('')}</select></label><label>判定结果<select id="cw-status">${['预警','全部','正常','待补数据'].map(n=>`<option>${n}</option>`).join('')}</select></label><input id="cw-query" type="search" placeholder="采购人员 / 产品 / 供应商"><button class="btn" id="cw-template">下载模板</button><button class="btn" id="cw-demo-file">下载测试数据</button><button class="btn primary" id="cw-import">导入数据</button></div><div class="cw-summary" id="cw-summary"></div><details class="cw-rulebox"><summary>指标口径与导入记录</summary><p id="cw-rules"></p><p>金额单位：元；百分比5%填5或5%。按记录编号、报价阶段和数据日期识别重复，同日重导更新；历史快照保留。</p><div>${cwStore.batches.slice(0,5).map(b=>`<p>${esc(b.at.slice(0,16).replace('T',' '))} · ${cwTypes[b.type]} · ${esc(b.file)} · 新增${b.added} / 更新${b.updated}</p>`).join('')||'暂无导入记录'}</div></details><div id="cw-table"></div><div id="cw-pages"></div>`);$('#dialog').classList.add('cw-dialog');$('#cw-type').onchange=e=>{type=+e.target.value;cwSelected=type;page=1;paint()};$('#cw-status').onchange=e=>{status=e.target.value;page=1;paint()};$('#cw-query').oninput=e=>{query=e.target.value.trim();page=1;paint()};$('#cw-source').onchange=e=>{cwSetDataMode(e.target.value);page=1;renderPurchasing();paint()};$('#cw-demo-file').onclick=()=>cwDownloadDemo(type);$('#cw-template').onclick=()=>cwTemplate(type);$('#cw-import').onclick=()=>cwImport(type);paint();}
function cwDetail(r){const result=r.result,fields=cwFields[r.type].filter(f=>!['image','name','model'].includes(f.key)&&!f.computed),plan=[['核对立项目标与当前报价阶段的成本、四项费率。','与供应商复核报价差额并提交议价方案。','更新审批台账，成本与费率达标后复核。'],['确认年度降本目标与实际完成额。','按进度缺口拆解议价、替代料及采购量计划。','回填降本台账，复核实际进度是否追平。'],['核对约定台数、提货及已摊销金额。','通知供应商停止继续分摊，确认后续采购单价。','核对结算；对超摊部分办理冲回。'],['复核联检确认费与预估费差额。','核查工厂退货及分摊凭证，确认降费方案。','更新实际分摊翻新费，复核费率达标。'],['核对物料规格、价格单位与取价日期。','采购评估备货节奏、替代料及锁价方案。','更新同口径价格记录并复查波动。']][r.type];openModal(r.name+' · 成本预警详情',`<div class="cw-detail-top">${r.type===4?`<h2>${esc(r.name)}</h2>`:cwProduct(r)}${cwResultHTML(result,true)}</div><div class="cw-rulebox"><b>判定依据</b><p>${esc(cwRules[r.type])}</p>${r.type===2&&result.d.excess?`<p class="red">已超摊 ${cwNumber(result.d.excess,'元')}，需核对结算。</p>`:''}</div><div class="cw-detail-fields">${fields.map(f=>`<div><small>${f.label}</small><b>${esc(String(r[f.key]??'—'))}${f.type==='percent'?'%':''}</b></div>`).join('')}${Object.entries(result.d).map(([key,v])=>`<div><small>${({costDelta:'实际－目标成本（元）',unitSavingRate:'单台累计降本率（%）',actualProgress:'实际完成进度（%）',expectedProgress:'应完成进度（%）',remainingUnits:'剩余摊销台数',remainingAmount:'剩余摊销金额（元）',excess:'超摊金额（元）',actualRefurbRate:'实际翻新费率（%）',change:'涨跌金额',changeRate:'当日涨跌幅度（%）',averageChange:'30天均价波动（%）'})[key]}</small><b>${cwNumber(v)}</b></div>`).join('')}</div><div class="cw-plan"><b>处理建议</b>${plan.map((line,i)=>`<p>${i+1}. ${line}</p>`).join('')}</div>`,false,r.date+' · '+cwTypes[r.type]+(r.demo?' · 模拟数据，仅供演示':''));$('#dialog').classList.add('cw-dialog');$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn" id="cw-back">返回列表</button>');$('#cw-back').onclick=()=>cwOpen(r.type);}
function cwImport(type){let validated=null,filename='',images={},busy=false;openModal(cwTypes[type]+' · 导入数据',`<div class="cw-import-help"><b>1 下载模板 → 2 选择文件 → 3 核对预览 → 4 确认导入</b><p>支持Excel（.xlsx，单工作表）和CSV，最多3000条 / 5MB。必填列不能缺失，错误行需修正后重新导入。公式请先粘贴为值。</p><p>所属品链填写：${chains.join('、')}。金额单位为元，百分比5%填5或5%。计算字段可留空；填写时会校验与基础指标是否一致。产品图片可填https地址，或填文件名并先选择同名图片；图片可留空。</p><button class="btn" id="cw-import-template">下载当前模板</button><details><summary>字段说明（必填项标 *）</summary><div class="cw-field-list">${cwFields[type].map(f=>`<span>${f.label}${f.required?' *':f.computed?'（自动计算，可留空）':''}</span>`).join('')}</div></details></div><div class="cw-import-files"><label>可选：先选择产品图片<input id="cw-images" type="file" multiple accept="image/png,image/jpeg,image/webp"><small>单张不超过200KB，合计不超过1MB。</small></label><label>选择数据文件<input id="cw-file" type="file" accept=".xlsx,.csv"></label></div><div id="cw-preview" aria-live="polite"><div class="cw-empty">等待选择数据文件</div></div>`);$('#dialog').classList.add('cw-dialog');$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn" id="cw-import-back">返回列表</button><button class="btn primary" id="cw-confirm" disabled>确认导入</button>');$('#cw-import-back').onclick=()=>cwOpen(type);$('#cw-import-template').onclick=()=>cwTemplate(type);
 $('#cw-images').onchange=async e=>{try{if([...e.target.files].reduce((sum,f)=>sum+f.size,0)>1024*1024)throw Error('图片合计不能超过1MB');const next={};for(const f of e.target.files){if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>200*1024)throw Error('请选PNG/JPG/WebP图片，每张不超过200KB');if(next[f.name])throw Error('图片文件名重复');next[f.name]=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f)})}images=next;validated=null;$('#cw-confirm').disabled=true;$('#cw-file').value='';$('#cw-preview').textContent='已选择 '+Object.keys(images).length+' 张图片，请选择数据文件。';}catch(error){images={};validated=null;$('#cw-confirm').disabled=true;$('#cw-preview').textContent=error.message;}};
 $('#cw-file').onchange=async e=>{const file=e.target.files[0];if(!file||busy)return;busy=true;validated=null;$('#cw-confirm').disabled=true;$('#cw-preview').textContent='正在校验文件…';try{const table=await cwReadFile(file);if(!document.contains(e.target))return;validated=cwValidate(type,table,images);filename=file.name;const {valid,errors}=validated,risks=valid.filter(r=>cwEvaluate(type,r).status==='预警').length,pending=valid.filter(r=>cwEvaluate(type,r).pending.length).length;let page=1;const preview=()=>{const view=valid.slice((page-1)*DRAWER_PAGE_SIZE,page*DRAWER_PAGE_SIZE);$('#cw-preview').innerHTML=`<div class="cw-summary"><span>有效 ${valid.length} 条</span><span class="red">错误 ${errors.length} 项</span><span>预警 ${risks} 条</span><span>待补数据 ${pending} 条</span></div>${errors.length?`<div class="cw-rulebox"><b class="red">请修正错误后重导，本次尚未入库</b>${errors.slice(0,12).map(err=>`<p>第${err.row}行 · ${esc(err.field)}：${esc(err.message)}</p>`).join('')}<button class="btn small" id="cw-errors">下载全部错误</button></div>`:''}<div class="cw-preview-table">${dpTable(['原始行号','产品 / 物料','采购人员','数据日期','判定结果'],view.map(r=>[r.sourceRow,type===4?esc(r.name):cwProduct(r),esc(r.owner),r.date,cwResultHTML(cwEvaluate(type,r))]))}</div>${listPager(valid.length,page)}<p class="dp-notice">确认后保存到当前浏览器。相同编号、报价阶段和数据日期将更新；不删除其他记录。数据不会写入HTML文件，请保留原始导入文件。</p>`;bindListPager($('#cw-preview'),next=>{page=next;preview()});$('#cw-errors')?.addEventListener('click',()=>downloadCsv(['行号','字段','错误'],errors.map(e=>[e.row,e.field,e.message]),'成本导入错误'));};preview();$('#cw-confirm').disabled=!!errors.length||!valid.length;}catch(error){if($('#cw-preview'))$('#cw-preview').textContent='导入失败：'+error.message;}finally{busy=false;}};
 $('#cw-confirm').onclick=()=>{if(!validated||validated.errors.length||!validated.valid.length)return;const batch=cwCommit(type,validated.valid,filename);if(!batch)return;renderPurchasing();cwOpen(type);toast('已导入：新增 '+batch.added+' 条，更新 '+batch.updated+' 条');};}
const cwPreviousOpen=pbOpenRiskList;pbOpenRiskList=function(index){if(index===1)return cwOpen();return cwPreviousOpen(index);};
const cwPreviousDetails=pbDetails;pbDetails=function(r){if(r?.kind==='imported-cost')return cwDetail({...r,type:r.costType,result:cwEvaluate(r.costType,r)});return cwPreviousDetails(r);};
const cwPreviousRender=pbRenderRisk;pbRenderRisk=function(){const root=document.createElement('div');root.innerHTML=cwPreviousRender();const card=root.querySelectorAll('.riskcard')[1];if(card){const rows=cwRisks().filter(r=>r.costType===cwSelected&&!pbClosed(r));card.innerHTML=`<div class="rhead"><h3><i class="riskbadge"></i>成本管控预警 <small>${cwDataMode==='demo'?'测试':'导入'}</small></h3>${pbBtn('全部 '+rows.length+' ›','risk-list',1)}</div><div class="sw-rank-filter"><select data-cw-rank aria-label="成本预警类型">${cwTypes.map((name,i)=>`<option value="${i}" ${i===cwSelected?'selected':''}>${name}</option>`).join('')}</select></div>${rows.slice(0,6).map((r,i)=>`<button class="sw-rank-row" data-pb-action="detail" data-key="${esc(pbRemember(r))}"><span class="rank top">${i+1}</span><span class="pb-rank-product">${r.costType===4?'':cwProductImage(r)}<span class="sw-rank-name">${esc(r.name)}${r.result.alerts.length>1?`<small class="cw-more-alerts">另 ${r.result.alerts.length-1} 项异常</small>`:''}</span></span><span class="sw-rank-value cw-rank-value" title="${esc(r.issue)}">${esc(r.metric)}</span></button>`).join('')||'<div class="cw-empty">暂无导入预警<br><button class="link" data-cw-import>导入成本数据</button></div>'}`;}return root.innerHTML;};pbRenderers.risk=pbRenderRisk;
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-cw-rank')){cwSelected=+e.target.value;renderPurchasing();}});
document.addEventListener('click',e=>{if(e.target.closest('[data-cw-import]'))cwImport(cwSelected);});
const cwPreviousModal=openModal;openModal=function(...args){$('#dialog').classList.remove('cw-dialog');return cwPreviousModal(...args);};

// Director and procurement use the same ranking markup, lists and project detail.
let pdrSeason='四季品';
for(const [id,title] of pbModules)moduleNames['pb-'+id]=title;
function pdrRows(){const scoped=new Map(pbProjectRows().map(r=>[r.id,r]));return drRows().filter(r=>scoped.has(r.id)).map(r=>({...scoped.get(r.id),...r,kind:'project',riskLevel:r.level,level:'高危',owner:scoped.get(r.id).owner,issue:r.cause,metric:r.value}));}
function pdrContext(){return pbWith('risk',()=>({procurement:true,period:{...pbPeriod('risk')},season:pdrSeason,ids:pdrRows().filter(r=>!pbClosed(r)).map(r=>r.id)}));}
function plRows(){return brLossRows().map(r=>{const s=pbSupplierFor(r.chain,r.id);return {...r,key:'LOSS-'+periodKey()+'-'+r.id,kind:'loss-warning',riskLevel:r.level,level:'高危',tier:s.tier,owner:s.owner,metric:r.value,issue:r.desc,source:'总看板亏损产品统一台账',date:pbDate()};}).filter(pbScope);}
function plContext(){return pbWith('risk',()=>({period:{...pbPeriod('risk')},ids:plRows().filter(r=>!pbClosed(r)).map(r=>r.id)}));}
function prSharedCard(k,rows,procurement=false){const delayed=k===5,title=procurement?(delayed?'项目延期预警':'亏损产品预警'):riskTitles[k],season=procurement?pdrSeason:riskSeasonState[5];return `<div class="rhead"><h3><i class="riskbadge"></i>${title}</h3><button class="link" ${procurement?`data-pr-open="${k}"`:`data-risk="${k}"`}>全部 ${rows.length} ›</button></div>${delayed?`<div class="qr-card-filter"><label class="sr-filter-label">产品属性 <select ${procurement?'data-pdr-season':'data-risk-season="5"'} aria-label="延期项目产品属性">${srSeasonOptions(5,season,!procurement)}</select></label></div>`:''}<div class="riskfoot" style="margin:0 0 3px"><span>风险对象</span><span>${delayed?'延迟天数':'月度亏损金额'}</span></div>${rows.slice(0,6).map((r,i)=>`<button class="riskline" ${procurement?`data-pr-detail="${k},${r.id}"`:`data-riskitem="${k},${r.id}"`}><span class="rank ${i<3?'top':''}">${String(i+1).padStart(2,'0')}</span>${riskThumbnail(r.name)}<span class="rname" title="${esc(r.name)}">${esc(r.name)}</span><span class="rvalue">${r.value}</span></button>`).join('')||'<div class="empty">当前范围暂无风险项目</div>'}`;}
const prPreviousRenderDirector=renderRisks;renderRisks=function(){prPreviousRenderDirector();withPeriod('risk',()=>{for(const k of [2,5]){const card=$$('#riskrail .riskcard')[k];card.classList.add('pr-shared-card');card.innerHTML=prSharedCard(k,riskRows(k));}});};
pbRiskTitles.push('亏损产品预警');
const prPreviousLists=pbRiskLists;pbRiskLists=function(includeClosed=false){const lists=prPreviousLists(includeClosed);lists[2]=pdrRows().filter(r=>includeClosed||!pbClosed(r));lists[7]=plRows().filter(r=>includeClosed||!pbClosed(r));[...lists[2],...lists[7]].forEach(pbRemember);return lists;};
const prPreviousRender=pbRenderRisk;pbRenderRisk=function(){const root=document.createElement('div');root.innerHTML=prPreviousRender();const cards=root.querySelectorAll('.riskcard');for(const [index,k] of [[2,5],[7,2]]){const card=cards[index];if(!card)continue;const rows=(k===5?pdrRows().filter(r=>r.attribute===pdrSeason):plRows()).filter(r=>!pbClosed(r));card.classList.add('pr-shared-card');card.innerHTML=prSharedCard(k,rows,true);}return root.innerHTML;};pbRenderers.risk=pbRenderRisk;
function prOpen(k){pbModalSection='risk';if(k===5)return drOpenList(pdrContext());const context=plContext();brState.lossPage=1;return drRun(context,()=>brOpenList(2,context));}
function prDetail(k,id){pbModalSection='risk';const context=k===5?pdrContext():plContext();if(!context.ids.includes(+id))return toast('当前范围没有该风险记录');return k===5?drOpenDetail(+id,context):drRun(context,()=>riskDetail(2,+id));}
const prPreviousOpen=pbOpenRiskList;pbOpenRiskList=function(index){return index===2?prOpen(5):index===7?prOpen(2):prPreviousOpen(index);};
const prPreviousDetails=pbDetails;pbDetails=function(r){if(r?.kind==='project')return drOpenDetail(r.id,{period:{...pbPeriod(pbModalSection)},ids:[r.id]});if(r?.kind==='loss-warning')return drRun({period:{...pbPeriod(pbModalSection)}},()=>riskDetail(2,r.id));return prPreviousDetails(r);};
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-pdr-season')){pdrSeason=e.target.value;renderPurchasing();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-pr-open],[data-pr-detail]');if(!b)return;if(b.hasAttribute('data-pr-open'))prOpen(+b.dataset.prOpen);else{const [k,id]=b.dataset.prDetail.split(',').map(Number);prDetail(k,id);}});

// Delivery warnings share the procurement order ledger and the selected period.
const odTypes=['交付不达标预警','翻新延期预警'];let odSelected=0;
function odDeliveryDecision(onTime,total){const rate=total>0?onTime/total*100:null;return {rate,hit:rate!==null&&rate<97,gap:rate===null?null:Math.max(0,97-rate)};}
function odRefurbDecision(type,start,end){const limit=type==='首次'?60:45,elapsed=Math.max(0,Math.round((Date.parse(end)-Date.parse(start))/86400000));return {limit,elapsed,delay:Math.max(0,elapsed-limit),hit:elapsed>limit};}
function odRows(includeNormal=false){const orders=pbOrders(),groups=new Map(),cutoff=pbDate(),out=[];
 for(const r of orders.filter(r=>r.type==='新机')){const key=[r.supplierKey,r.model,r.owner].join('|');if(!groups.has(key))groups.set(key,{...r,key:'DELIVERY-'+periodKey()+'-'+key,kind:'delivery-warning',warningType:0,orders:[],total:0,onTime:0,planOwner:['沈舟','王洋','李晴','赵宁'][r.chain]});const g=groups.get(key);const seed=+r.key.split('-').at(-1)+ +r.due.slice(5,7),onTimeQty=r.actual!=='—'&&r.actual<=r.due?r.qty:Math.floor(r.qty*[.94,.965,.91,.975,.88,.95][seed%6]);g.orders.push({...r,onTimeQty});g.total+=r.qty;g.onTime+=onTimeQty;}
 for(const r of groups.values()){const d=odDeliveryDecision(r.onTime,r.total);Object.assign(r,d,{metric:fmt(d.rate,1)+'%',issue:`交付及时率 ${fmt(d.rate,1)}%，低于97%目标 ${fmt(d.gap,1)}%；按时交付 ${fmt(r.onTime)} / 应交付 ${fmt(r.total)} 件。`,level:'高危',date:cutoff,due:shiftDate(cutoff,7),source:'采购订单及分批到货记录 · 按应交付件数加权（测试数据）'});if(includeNormal||d.hit)out.push(r);}
 for(const r of orders.filter(r=>r.type==='翻新机')){const index=+r.key.split('-').at(-1),refurbType=Math.floor(index/12)%2?'后续':'首次',limit=refurbType==='首次'?60:45,start=shiftDate(r.due,-limit),end=r.actual==='—'?cutoff:r.actual,d=odRefurbDecision(refurbType,start,end);if(!includeNormal&&!d.hit)continue;out.push({...r,...d,key:'REFURB-'+r.key,orderKey:r.key,kind:'refurb-warning',warningType:1,refurbType,start,end,planOwner:['沈舟','王洋','李晴','赵宁'][r.chain],delayedQty:d.hit?r.qty:0,metric:'超期 '+d.delay+' 天',issue:`${refurbType}翻新用时 ${d.elapsed} 天，标准 ${limit} 天，超期 ${d.delay} 天；延期翻新 ${fmt(d.hit?r.qty:0)} 件。`,level:'高危',date:cutoff,orders:[r],source:'采购翻新订单台账 · 翻新起始日期为测试数据'});}
 return out.sort((a,b)=>a.warningType-b.warningType||(a.warningType===0?a.rate-b.rate:b.delay-a.delay));
}
function odOptions(){return odTypes.map((t,i)=>`<option value="${i}" ${i===odSelected?'selected':''}>${t}</option>`).join('');}
function odTableHeads(type){return type===0?['序号','供应商名称','产品名称','采购责任人','计划责任人','交付及时率','预警原因','操作']:['序号','供应商名称','产品名称','采购责任人','计划责任人','翻新类型','延期翻新数量','延期天数','操作'];}
function odCells(r,i,plain=false){const base=[i+1,esc(r.supplier),plain?r.name+' / '+r.model:pbProduct(r),esc(r.owner),esc(r.planOwner)];return r.warningType===0?[...base,plain?fmt(r.rate,1)+'%':`<strong class="red">${fmt(r.rate,1)}%</strong>`,plain?'低于目标 '+fmt(r.gap,1)+'%':`<span class="red">低于目标 ${fmt(r.gap,1)}%</span><small>目标 97%</small>`,plain?'':pbBtn('查看详情','detail',r.key)]:[...base,r.refurbType,fmt(r.delayedQty)+' 件',plain?r.delay+' 天':`<strong class="red">${r.delay} 天</strong><small>用时 ${r.elapsed} / 标准 ${r.limit} 天</small>`,plain?'':pbBtn('查看详情','detail',r.key)];}
function odOpen(){pbModalSection='risk';const period={...pbPeriod('risk')},all=pbWith('risk',()=>odRows().filter(r=>!pbClosed(r)));all.forEach(r=>pbWith('risk',()=>pbRemember(r)));const productFilters=pfDefaults();let page=1;
 pbModal('订单交付预警 · 全部',`<div class="br-list-tools"><label>预警类型 <select id="od-type">${odOptions()}</select></label><span class="note">测试数据 · ${periodLabel(period)} · 截至 ${bounds(period).cutoff}</span></div><div id="od-table"></div><div id="od-pages"></div><details class="od-rules"><summary>指标口径</summary><p>交付及时率＝按时交付件数 ÷ 本期应交付件数，低于97%预警；按分批到货记录累计按时交付件数，已到期未交付计入分母。翻新用时＝完成日期（未完成取统计截止日期）− 翻新起始日期；首次超过60天、后续超过45天预警。延期天数为超过对应标准的天数；达到边界不预警。</p></details>`);
 $('#dialog').classList.add('od-dialog');
 function fill(){const rows=all.filter(r=>r.warningType===odSelected&&pfMatches(r,productFilters)),pages=Math.max(1,Math.ceil(rows.length/DRAWER_PAGE_SIZE));page=Math.max(1,Math.min(page,pages));$('#od-table').innerHTML=rows.length?table(odTableHeads(odSelected),rows.slice((page-1)*DRAWER_PAGE_SIZE,page*DRAWER_PAGE_SIZE).map((r,i)=>odCells(r,(page-1)*DRAWER_PAGE_SIZE+i))):'<div class="empty">当前周期及范围暂无此类预警</div>';$('#od-table').querySelectorAll('table').forEach(rdTable);mountListPager($('#od-pages'),rows.length,page,next=>{page=next;fill()});$('#od-table').onclick=e=>{const b=e.target.closest('[data-pb-action="detail"]');if(!b)return;e.stopPropagation();odDetail(rows.find(r=>r.key===b.dataset.key),period)};}
 pfMount($('#od-type').closest('.br-list-tools'),productFilters,()=>{page=1;fill()});$('#od-type').onchange=e=>{odSelected=+e.target.value;page=1;fill();renderPurchasing()};fill();
}
function odDetail(r,period={...pbPeriod(pbModalSection)}){if(!r)return;pbModalSection='risk';const refurb=r.warningType===1,metrics=refurb?[['翻新类型',r.refurbType],['延期翻新数量',fmt(r.delayedQty)+' 件'],['延期天数',r.delay+' 天'],['实际 / 标准用时',r.elapsed+' / '+r.limit+' 天']]:[['交付及时率',fmt(r.rate,1)+'%'],['目标及时率','97%'],['低于目标',fmt(r.gap,1)+'%'],['按时 / 应交付',fmt(r.onTime)+' / '+fmt(r.total)+' 件']];
 openModal(r.name+' · '+odTypes[r.warningType]+'详情',`<div class="od-hero">${riskThumbnail(r.name)}<div><h3>${esc(r.name)}</h3><small>${esc(r.model)} · ${esc(r.supplier)}</small></div><span class="tag red">${odTypes[r.warningType]}</span></div><div class="od-metrics">${metrics.map(([n,v])=>`<div><small>${n}</small><strong>${v}</strong></div>`).join('')}</div><div class="od-owners"><span>采购责任人：<b>${esc(r.owner)}</b></span><span>计划责任人：<b>${esc(r.planOwner)}</b></span>${refurb?`<span>翻新起始日期：${r.start}</span><span>${r.actual==='—'?'统计截止':'完成日期'}：${r.end}</span>`:''}</div><div class="od-summary"><b>预警原因</b><p>${esc(r.issue)}</p><b>处理重点</b><p>${refurb?'采购确认返工物料及产能，计划负责人锁定剩余翻新数量和完成日期。':'采购核对未交付批次，计划负责人协调排产与到货日期，优先补齐逾期缺口。'}</p></div><h3>关联订单</h3>${table(['订单编号','产品名称','应交付数量',...(refurb?[]:['按时交付数量']),'计划交付日期','最终交付日期'],r.orders.map(o=>[o.key,pbProduct(o),fmt(o.qty)+' 件',...(refurb?[]:[fmt(o.onTimeQty)+' 件']),o.due,o.actual==='—'?'未完成':o.actual]))}`,false,periodLabel(period)+' · 截至 '+bounds(period).cutoff+' · 测试数据');$('#dialog').classList.add('od-dialog');$('#dialogbody').querySelectorAll('table').forEach(rdTable);$('#dialogactions').insertAdjacentHTML('afterbegin','<button class="btn small" id="od-back">返回榜单</button>'+pbBtn(pbTask(r)?'跟进任务':'下发任务','dispatch',r.key,'btn primary'));$('#od-back').onclick=odOpen;pbWith('risk',()=>pbRemember(r));
}
const odPreviousLists=pbRiskLists;pbRiskLists=function(includeClosed=false){const lists=odPreviousLists(includeClosed);lists[3]=odRows().filter(r=>includeClosed||!pbClosed(r));lists[3].forEach(pbRemember);return lists;};
const odPreviousOpen=pbOpenRiskList;pbOpenRiskList=function(index){return index===3?odOpen():odPreviousOpen(index);};
const odPreviousDetail=pbDetails;pbDetails=function(r){return r&&['delivery-warning','refurb-warning'].includes(r.kind)?odDetail(r):odPreviousDetail(r);};
const odPreviousRender=pbRenderRisk;pbRenderRisk=function(){const root=document.createElement('div');root.innerHTML=odPreviousRender();const card=root.querySelectorAll('.riskcard')[3],rows=odRows().filter(r=>r.warningType===odSelected&&!pbClosed(r));if(card)card.innerHTML=`<div class="rhead"><h3><i class="riskbadge"></i>订单交付预警</h3>${pbBtn('全部 '+rows.length+' ›','risk-list',3)}</div><div class="sw-rank-filter"><select data-od-rank aria-label="订单交付预警类型">${odOptions()}</select></div>${rows.slice(0,6).map((r,i)=>`<button class="sw-rank-row" data-pb-action="detail" data-key="${esc(pbRemember(r))}"><span class="rank ${i<3?'top':''}">${String(i+1).padStart(2,'0')}</span><span class="pb-rank-product">${riskThumbnail(r.name)}<span class="sw-rank-name">${esc(r.name)}<small>${r.warningType===0?'低于97%目标 '+fmt(r.gap,1)+'%':r.refurbType+' · 延期 '+fmt(r.delayedQty)+' 件'}</small></span></span><span class="sw-rank-value">${r.metric}</span></button>`).join('')||'<div class="empty">当前范围暂无预警</div>'}`;return root.innerHTML;};pbRenderers.risk=pbRenderRisk;
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-od-rank')){odSelected=+e.target.value;renderPurchasing();}});
