function riskRangeText(){const w=riskRange();return w.start+' — '+w.end}
function riskDailyRows(start,end,make){const rows=[];for(let date=start;date<=end;date=shiftDate(date,1))rows.push({date,...make(date)});return rows}
function riskMonthDays(date){const [year,month]=date.split('-').map(Number);return new Date(Date.UTC(year,month,0)).getUTCDate()}
function riskDailyWeight(date,id){return 1+.18*Math.sin((Math.floor(Date.parse(date)/86400000)+id*13)*.31)}
function riskShopPeriod(r,w=riskRange()){
 const referenceStart=DATA_CUTOFF.slice(0,7)+'-01';
 const referenceWeight=riskDailyRows(referenceStart,DATA_CUTOFF,d=>({weight:riskDailyWeight(d,r.id)})).reduce((s,p)=>s+p.weight,0);
 const perDay=(r.referenceGsv??(4+r.id*.27)*10)/referenceWeight;
 const points=riskDailyRows(w.start,w.end,d=>({gsv:perDay*riskDailyWeight(d,r.id)}));
 // 罚款是离散事件，不按天数比例分摊。
 const events=[];for(let month=w.start.slice(0,7);month<=w.end.slice(0,7);month=riskMonthShift(month,1)){
  const date=month+'-'+String(5+r.id%5).padStart(2,'0');if((r.sourceQualityFine??r.qualityFine)>0&&date>=w.start&&date<=w.end)events.push({date,amount:r.sourceQualityFine??r.qualityFine});
 }
 return {...w,points,gsv:points.reduce((s,p)=>s+p.gsv,0),target:(4+r.id*.27)*w.days,fine:events.reduce((s,e)=>s+e.amount,0),events};
}
function riskLossPeriod(r){
 const w=riskRange(),baseFactor=snapshotFactor();
 const points=riskDailyRows(w.start,w.end,date=>{
  const day=Number(date.slice(8)),month=date.slice(0,7),days=riskMonthDays(date),factor=.70+(Number(date.slice(0,4))-2025)*.12+Number(date.slice(5,7))*.02;
  const weights=Array.from({length:days},(_,i)=>riskDailyWeight(month+'-'+String(i+1).padStart(2,'0'),r.id));
  const share=weights[day-1]/weights.reduce((s,n)=>s+n,0),monthlySalesUnits=Math.round((1680-r.id*81+2*43)*factor);
  const before=weights.slice(0,day-1).reduce((s,n)=>s+n,0)/weights.reduce((s,n)=>s+n,0),after=before+share;
  const sales=Math.round(monthlySalesUnits*after)-Math.round(monthlySalesUnits*before),returned=Math.round(sales*(.046+r.id%3*.001));
  return {sales,returns:returned,rate:qrRate(returned,sales),gmv:(r.sourceMonthlySales??r.monthlySales)*share,loss:(r.sourceLoss??r.loss)*factor/baseFactor*share};
 });
 const sales=qrSum(points,'sales'),returned=qrSum(points,'returns'),gmv=qrSum(points,'gmv'),loss=qrSum(points,'loss'),rate=qrRate(returned,sales),received=Math.floor(returned*[.78,.85,.92][r.id%3]);
 return {...w,points,sales,returned,rate,received,receivedRate:qrRate(received,sales),gmv,gsv:gmv*(1-rate/100),loss};
}
function riskInventorySeries(r){
 const w=riskRange();return {name:'销量',color:'#7885f5',points:riskDailyRows(w.start,w.end,date=>{
  const day=Math.floor(Date.parse(date)/86400000),volume=r.slow||r.ledgerId!==undefined?((r.id+day)%7===0?2:(r.id+day)%5===0?1:0):Math.round(12+(r.id%13)*2+6*Math.sin(day*.5+r.id));return {volume};
 })};
}
function riskTrendBuckets(points){
 const size=Math.max(1,Math.ceil(points.length/6)),groups=[];
 for(let i=0;i<points.length;i+=size){const group=points.slice(i,i+size),sales=qrSum(group,'sales'),returns=qrSum(group,'returns');groups.push({date:group.at(-1).date,sales,returns,rate:qrRate(returns,sales)})}return groups;
}
const riskRangePreviousObservation=riskObservation;
riskObservation=function(k,r){
 if(activeModule!=='risk'||![1,2,3,4].includes(k))return riskRangePreviousObservation(k,r);
 const w=riskRange();let daily;
 if(k===2)daily=riskLossPeriod(r).points;
 else if(k===3||k===4)daily=riskInventorySeries(r).points.map(p=>({...p,sales:p.volume,returns:0}));
 else daily=riskDailyRows(w.start,w.end,date=>{const sales=Math.round((35+r.id*4)*riskDailyWeight(date,r.id));return {sales,returns:Math.round(sales*.095)}});
 const shipped=qrSum(daily,'sales'),returned=qrSum(daily,'returns');return {start:w.start,cutoff:w.end,shipped,returned,rate:qrRate(returned,shipped),unsold:false,points:riskTrendBuckets(daily)};
};
const riskRangeLabel=periodLabel,riskRangeWord=word,riskRangeKey=periodKey;
periodLabel=function(p=periodFor()){return p.mode==='day'?p.start+' — '+p.end:riskRangeLabel(p)};
word=function(p=periodFor()){return p.mode==='day'?'期间':riskRangeWord(p)};
periodKey=function(p=periodFor()){return p.mode==='day'?'day:'+p.start+':'+p.end:riskRangeKey(p)};
// 亏损榜的权威粒度为全公司 SPU；平台明细仅用于详情分析。
// 保留现有公司样例规模，渠道拆分为守恒的演示分配，不把原金额重复算六遍。
const lossPreviousPeriod=riskLossPeriod;
const lossChannelWeights=[32,13,8,20,15,12];
const lossLedgerCache=new Map();let lossLedgerWindow='';
function lossAllocate(total,weights){
 const sign=total<0?-1:1,count=Math.abs(Math.round(total)),sum=weights.reduce((s,n)=>s+n,0);
 if(!sum)return weights.map(()=>0);
 const raw=weights.map(n=>count*n/sum),parts=raw.map(Math.floor),remaining=count-parts.reduce((s,n)=>s+n,0);
 const order=raw.map((n,i)=>({i,fraction:n-parts[i]})).sort((a,b)=>b.fraction-a.fraction||a.i-b.i);
 for(let i=0;i<remaining;i++)parts[order[i].i]++;
 return parts.map(n=>n*sign);
}
function lossCompanyLedger(r){
 const w=riskRange(),windowKey=w.start+'|'+w.end+'|'+snapshotFactor();
 if(windowKey!==lossLedgerWindow){lossLedgerWindow=windowKey;lossLedgerCache.clear()}
 const key=[r.spuId||r.id,r.sourceLoss??r.loss,r.sourceMonthlySales??r.monthlySales].join('|');
 if(lossLedgerCache.has(key))return lossLedgerCache.get(key);
 const source=lossPreviousPeriod(r),weights=lossChannelWeights.map((_,i)=>lossChannelWeights[(i+r.id)%lossChannelWeights.length]);
 // 沿用原公司已收退件数，按逐日退货量分配，避免拆渠道时改变总量。
 const dailyReceived=lossAllocate(source.received,source.points.map(p=>p.returns));
 const channels=qrPlatforms.map(platform=>({platform,points:[]}));
 for(const [pointIndex,point] of source.points.entries()){
  const gmvCents=Math.round(point.gmv*1000000),refundCents=point.sales?Math.round(gmvCents*point.returns/point.sales):0;
  const received=dailyReceived[pointIndex],profitCents=-Math.round(point.loss*1000000);
  const sales=lossAllocate(point.sales,weights),returns=lossAllocate(point.returns,sales),receipts=lossAllocate(received,returns);
  const gross=lossAllocate(gmvCents,weights),refunds=lossAllocate(refundCents,returns),profits=lossAllocate(profitCents,weights);
  channels.forEach((channel,i)=>{
   const gsvCents=gross[i]-refunds[i];
   channel.points.push({date:point.date,sales:sales[i],returns:returns[i],received:receipts[i],gmvCents:gross[i],refundCents:refunds[i],gsvCents,profitCents:profits[i],costCents:gsvCents-profits[i],gmv:gross[i]/1000000,loss:-profits[i]/1000000,rate:qrRate(returns[i],sales[i])});
  });
 }
 const company=source.points.map((point,index)=>{
  const row={date:point.date};
  for(const field of ['sales','returns','received','gmvCents','refundCents','gsvCents','profitCents','costCents'])row[field]=channels.reduce((sum,channel)=>sum+channel.points[index][field],0);
  return {...row,gmv:row.gmvCents/1000000,loss:-row.profitCents/1000000,rate:qrRate(row.returns,row.sales)};
 });
 const ledger={...w,company,channels};lossLedgerCache.set(key,ledger);return ledger;
}
riskLossPeriod=function(r){
 const ledger=lossCompanyLedger(r),platform=r.lossPlatform||'all',points=platform==='all'?ledger.company:ledger.channels.find(c=>c.platform===platform)?.points;
 if(!points)throw new Error('未知亏损分析平台：'+platform);
 const sum=field=>points.reduce((total,p)=>total+p[field],0),sales=sum('sales'),returned=sum('returns'),received=sum('received'),gsvCents=sum('gsvCents'),profitCents=sum('profitCents');
 return {...riskRange(),platform,points,sales,returned,received,rate:qrRate(returned,sales),receivedRate:qrRate(received,sales),gmv:sum('gmvCents')/1000000,gsv:gsvCents/1000000,loss:-profitCents/1000000,profitCents,gsvCents,gmvCents:sum('gmvCents'),refundCents:sum('refundCents'),costCents:sum('costCents')};
};
const lossPreviousRows=brLossRows;
brLossRows=function(){return lossPreviousRows().map(r=>({...r,channel:'全公司',performanceScope:'company',lossPlatform:'all'}))};
// 渠道切换只更新诊断数据，保留抽屉标签、处理表单与上一层榜单。
const lossPreviousDetail=riskDetail;
riskDetail=function(kind,id){
 const result=lossPreviousDetail(kind,id);if(kind!==2||!wfDirector())return result;
 withPeriod('risk',()=>{
  const product=brLossRows().find(r=>r.id===+id);if(!product)return;
  const body=$('#dialogbody'),metrics=body.querySelector('.risk-detail-metrics');
  metrics.insertAdjacentHTML('beforebegin',`<div class="loss-scope-tools"><select id="loss-detail-platform" aria-label="亏损产品统计范围"><option value="all">全公司</option>${qrPlatforms.map(n=>`<option value="${n}">${n}</option>`).join('')}</select></div>`);
  const render=()=>withPeriod('risk',()=>{
   const platform=$('#loss-detail-platform').value,scope=platform==='all'?'全公司':platform,r={...product,lossPlatform:platform},period=riskLossPeriod(r);
   const facts=rfFacts(2,r);
   metrics.innerHTML=facts.map(m=>`<div><small>${m.name}</small><strong>${rfCell(m)}</strong><span>${esc(m.rule)}</span></div>`).join('');
   body.querySelector('.risk-context').innerHTML=[['型号',product.model],['品类',chains[product.chain]],['品牌',product.brand],['统计范围',scope],['当前责任人',product.owner]].map(([label,value])=>`<span>${label}：<b>${esc(value)}</b></span>`).join('');
   const buckets=riskTrendBuckets(period.points);
   body.querySelector('.risk-trends').innerHTML=`<div><h3>所选周期发货销量趋势 <span>${scope} · ${fmt(period.sales)}件</span></h3>${riskTrendChart(buckets,'sales','#7b88fa','所选周期发货销量趋势','件')}</div><div><h3>所选周期退货率趋势 <span>${scope}</span></h3>${riskTrendChart(buckets,'rate','#e56570','所选周期退货率趋势','%')}</div>`;
   const signal=body.querySelector('.risk-analysis .rd-decision>div p');
   if(signal)signal.textContent=`${scope}：所选周期${period.loss>0?'亏损':'盈利'} ${pfMoneyYuan((Math.abs(period.loss))*10000)}，利润率 ${period.gsv?fmt(-period.loss/period.gsv*100,1)+'%':'—'}。`;
   $('#dialogsub').textContent=period.start+' — '+period.end+' · '+scope;
   body.dataset.lossPlatform=platform;
  });
  $('#loss-detail-platform').onchange=render;render();
 });return result;
};
// 快捷日期即时应用；手选范围在选完结束日后应用，未选完时关闭不改变筛选。
const riskCalendar={panel:null,start:'',end:'',anchor:'',month:'',preset:'',focusDate:''};
function riskCalendarCount(){return innerWidth<=700?1:2}
function riskCalendarFirst(end){return riskMonthShift(end.slice(0,7),1-riskCalendarCount())}
function riskMonthShift(month,step){const [y,m]=month.split('-').map(Number);return iso(new Date(Date.UTC(y,m-1+step,1))).slice(0,7)}
function riskPresetRange(key){
  const end=DATA_CUTOFF,date=new Date(end+'T00:00:00Z'),offset=(date.getUTCDay()+6)%7,month=end.slice(0,7);
  if(key==='today')return[end,end];
  if(key==='yesterday')return[shiftDate(end,-1),shiftDate(end,-1)];
  if(['7','15','30'].includes(key))return[shiftDate(end,1-Number(key)),end];
  if(key==='week')return[shiftDate(end,-offset),end];
  if(key==='lastweek')return[shiftDate(end,-offset-7),shiftDate(end,-offset-1)];
  if(key==='month')return[month+'-01',end];
  const previous=riskMonthShift(month,-1);return[previous+'-01',shiftDate(month+'-01',-1)];
}
const riskDatePresets=[['today','今日'],['yesterday','昨日'],['7','近7日'],['15','近15日'],['30','近30日'],['week','本周'],['lastweek','上周'],['month','本月'],['lastmonth','上月']];
function riskCalendarMonth(month){
  const [year,m]=month.split('-').map(Number),first=month+'-01',offset=(new Date(first+'T00:00:00Z').getUTCDay()+6)%7;
  const start=shiftDate(first,-offset),focus=riskCalendar.focusDate||riskCalendar.start;
  return `<section class="risk-calendar-month"><h3>${year}年 ${m}月</h3><div class="risk-calendar-week">${['一','二','三','四','五','六','日'].map(n=>`<span>${n}</span>`).join('')}</div><div class="risk-calendar-grid" role="grid" aria-label="${year}年${m}月">${Array.from({length:42},(_,i)=>{
    const day=shiftDate(start,i),outside=day.slice(0,7)!==month,disabled=outside||day<riskDateMin||day>DATA_CUTOFF;
    const edge=day===riskCalendar.start||day===riskCalendar.end,inside=day>=riskCalendar.start&&day<=riskCalendar.end;
    return `<button type="button" role="gridcell" data-risk-date="${day}" aria-label="${day}" aria-selected="${inside}" tabindex="${day===focus&&!disabled?0:-1}" class="${outside?'outside ':''}${inside?'in-range ':''}${edge?'range-edge ':''}${day===riskCalendar.start?'range-start ':''}${day===riskCalendar.end?'range-end':''}" ${disabled?'disabled':''}>${Number(day.slice(8))}</button>`;
  }).join('')}</div></section>`;
}
function positionRiskCalendar(){
  const panel=riskCalendar.panel,trigger=$('#risk-date-trigger');if(!panel||!trigger)return;
  const r=trigger.getBoundingClientRect(),w=panel.offsetWidth,h=panel.offsetHeight;
  panel.style.left=Math.max(12,Math.min(innerWidth-w-12,r.right-w))+'px';
  panel.style.top=Math.max(12,Math.min(innerHeight-h-12,r.bottom+8))+'px';
}
function renderRiskCalendar(){
  const panel=riskCalendar.panel;if(!panel)return;
  panel.innerHTML=`<div class="risk-calendar-body"><nav class="risk-calendar-presets" aria-label="快捷日期">${riskDatePresets.map(([key,name])=>`<button type="button" data-risk-preset="${key}" aria-pressed="${riskCalendar.preset===key}">${name}</button>`).join('')}</nav><div class="risk-calendar-months"><div class="risk-calendar-nav"><button type="button" data-risk-month="-1" aria-label="上一月" ${riskCalendar.month<=riskDateMin.slice(0,7)?'disabled':''}>‹</button><button type="button" data-risk-month="1" aria-label="下一月" ${riskMonthShift(riskCalendar.month,riskCalendarCount()-1)>=DATA_CUTOFF.slice(0,7)?'disabled':''}>›</button></div>${riskCalendarMonth(riskCalendar.month)}${riskCalendarCount()===2?riskCalendarMonth(riskMonthShift(riskCalendar.month,1)):''}</div></div>`;
  positionRiskCalendar();
}
function closeRiskCalendar(focus=true){
  riskCalendar.panel?.remove();riskCalendar.panel=null;
  const trigger=$('#risk-date-trigger');trigger?.setAttribute('aria-expanded','false');
  if(focus)trigger?.focus({preventScroll:true});
}
function openRiskCalendar(){
  if(riskCalendar.panel){closeRiskCalendar();return}
  const p=periodFor('risk');Object.assign(riskCalendar,{start:p.start,end:p.end,anchor:'',month:riskCalendarFirst(p.end),focusDate:p.start,preset:''});
  riskCalendar.preset=riskDatePresets.find(([key])=>{const range=riskPresetRange(key);return range[0]===p.start&&range[1]===p.end})?.[0]||'';
  const panel=document.createElement('div');panel.id='risk-date-popover';panel.className='risk-date-popover';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','选择风险回看日期');document.body.append(panel);riskCalendar.panel=panel;
  $('#risk-date-trigger').setAttribute('aria-expanded','true');renderRiskCalendar();
  panel.querySelector(`[data-risk-preset="${riskCalendar.preset}"]`)?.focus({preventScroll:true});
  if(!riskCalendar.preset)(panel.querySelector('[tabindex="0"]')||panel.querySelector('button:not(:disabled)')).focus({preventScroll:true});
}
document.addEventListener('click',event=>{
  if(event.target.closest('#risk-date-trigger'))return openRiskCalendar();
  const button=event.target.closest('#risk-date-popover button');if(!button)return;
  if(button.dataset.riskPreset){
    const [start,end]=riskPresetRange(button.dataset.riskPreset);
    if(riskApplyRange(start,end))closeRiskCalendar();
  }else if(button.dataset.riskMonth){riskCalendar.month=riskMonthShift(riskCalendar.month,Number(button.dataset.riskMonth));renderRiskCalendar();riskCalendar.panel.querySelector(`[data-risk-month="${button.dataset.riskMonth}"]`).focus({preventScroll:true})}
  else if(button.dataset.riskDate){
    const day=button.dataset.riskDate;riskCalendar.preset='';riskCalendar.focusDate=day;
    if(!riskCalendar.anchor){riskCalendar.anchor=day;riskCalendar.start=riskCalendar.end=day}
    else{
      const [start,end]=[riskCalendar.anchor,day].sort();
      if(riskApplyRange(start,end))closeRiskCalendar();
      return;
    }
    renderRiskCalendar();riskCalendar.panel.querySelector(`[data-risk-date="${day}"]:not(:disabled)`)?.focus({preventScroll:true});
  }
});
document.addEventListener('pointerdown',event=>{if(riskCalendar.panel&&!event.target.closest('#risk-date-popover,#risk-date-trigger'))closeRiskCalendar(false)});
document.addEventListener('keydown',event=>{
  if(!riskCalendar.panel)return;
  if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();closeRiskCalendar();return}
  if(event.key==='Tab'){
    const controls=[...riskCalendar.panel.querySelectorAll('button:not(:disabled)')].filter(n=>n.checkVisibility()&&n.tabIndex>=0),first=controls[0],last=controls.at(-1);
    if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}
  }
  const date=event.target.dataset.riskDate;if(!date)return;
  const offsets={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7};if(offsets[event.key]===undefined)return;
  event.preventDefault();const next=shiftDate(date,offsets[event.key]);if(next<riskDateMin||next>DATA_CUTOFF)return;
  riskCalendar.focusDate=next;
  if(next.slice(0,7)<riskCalendar.month)riskCalendar.month=next.slice(0,7);
  if(next.slice(0,7)>riskMonthShift(riskCalendar.month,riskCalendarCount()-1))riskCalendar.month=riskCalendarFirst(next);
  renderRiskCalendar();riskCalendar.panel.querySelector(`[data-risk-date="${next}"]:not(:disabled)`)?.focus({preventScroll:true});
});
window.addEventListener('resize',()=>{if(riskCalendar.panel){riskCalendar.month=riskCalendarFirst(riskCalendar.end);renderRiskCalendar()}});
// 点击远处卡片后返回日期按钮可能触发延迟滚动；可见时跟随定位，不误关弹层。
window.addEventListener('scroll',event=>{if(!riskCalendar.panel||riskCalendar.panel.contains(event.target))return;const r=$('#risk-date-trigger')?.getBoundingClientRect();if(!r||r.bottom<0||r.top>innerHeight)closeRiskCalendar(false);else positionRiskCalendar()},true);
// 移动现有筛选和周期节点，保留原 ID、值、事件及各榜单时间口径。
function alignRiskCardFilters(){
  for(const card of $$('#riskrail .riskcard')){
    const head=card.querySelector('.rhead'),filter=card.querySelector(':scope > .qr-card-filter');
    if(!head)continue;
    // 品质榜试版：平台、风险筛选与查看全部同组，保留原控件事件。
    if(card.querySelector('.rp-quality-columns,.rp-shop-columns')){
      if(filter){
        const actions=document.createElement('div');actions.className='rp-quality-actions';
        const more=head.querySelector('[data-risk]');
        actions.append(filter);if(more)actions.append(more);head.append(actions);
      }
      card.querySelector(':scope > .qr-card-date')?.remove();
      continue;
    }
    // 六榜使用标题行与条件行，保留原下拉节点及联动事件。
    if(card.querySelector('.rp-items')){
      const date=card.querySelector(':scope > .qr-card-date');
      if(filter||date){
        const toolbar=document.createElement('div');toolbar.className='rp-card-toolbar';
        head.after(toolbar);
        if(date){date.classList.add('risk-card-subtitle');toolbar.append(date)}
        if(filter)toolbar.append(filter);
      }
      continue;
    }
    if(filter){
      let actions=head.querySelector('.risk-card-actions');
      if(!actions){actions=document.createElement('div');actions.className='risk-card-actions';head.append(actions)}
      const more=head.querySelector('[data-risk]');
      for(const node of [...filter.children].filter(n=>n.matches('select,label:has(select)')))actions.append(node);
      if(more&&more.parentElement!==actions)actions.append(more);
      filter.remove();
    }
    const date=card.querySelector(':scope > .qr-card-date');
    if(date){date.classList.add('risk-card-subtitle');head.after(date)}
  }
}
const riskCardsRender=renderRisks;
renderRisks=function(...args){const result=riskCardsRender(...args);alignRiskCardFilters();return result};
// 部门页面沿用已有处理器；本模块仅管理下拉菜单及键盘焦点。
const chainTrigger = $('#chain-menu-trigger');
const chainMenu = $('#chain-menu');
const chainSwitch = chainTrigger.parentElement;
let chainCloseTimer = 0;
const chainMenuItems = () => [...chainMenu.querySelectorAll('button:not(:disabled)')];
function closeChainMenu(returnFocus = false) {
  clearTimeout(chainCloseTimer);
  chainMenu.hidden = true;
  chainTrigger.setAttribute('aria-expanded', 'false');
  if (returnFocus) chainTrigger.focus();
}
function openChainMenu(focusItem = false) {
  clearTimeout(chainCloseTimer);
  chainMenu.hidden = false;
  chainTrigger.setAttribute('aria-expanded', 'true');
  if (focusItem) (chainMenu.querySelector('button.active:not(:disabled)') || chainMenuItems()[0])?.focus();
}
chainTrigger.addEventListener('click', () => {
  if (chainMenu.hidden) openChainMenu();
  else closeChainMenu();
});
chainTrigger.addEventListener('keydown', event => {
  if (['ArrowDown', 'ArrowUp'].includes(event.key)) {
    event.preventDefault();
    openChainMenu(true);
    if (event.key === 'ArrowUp') chainMenuItems().at(-1)?.focus();
  }
  if (event.key === 'Escape') closeChainMenu(true);
});
chainMenu.addEventListener('keydown', event => {
  const items = chainMenuItems(), index = items.indexOf(document.activeElement);
  if (['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) {
    event.preventDefault();
    const target = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1
      : (index + (event.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
    items[target]?.focus();
  }
  if (event.key === 'Escape') {
    event.preventDefault();
    event.stopPropagation();
    closeChainMenu(true);
  }
});
chainMenu.addEventListener('click', event => {
  const item = event.target.closest('button:not(:disabled)');
  if (item) closeChainMenu(true);
});
chainSwitch.addEventListener('pointerenter', () => clearTimeout(chainCloseTimer));
chainSwitch.addEventListener('pointerleave', () => {
  chainCloseTimer = setTimeout(() => closeChainMenu(), 250);
});
chainSwitch.addEventListener('focusout', event => {
  if (event.relatedTarget && !chainSwitch.contains(event.relatedTarget)) closeChainMenu();
});
document.addEventListener('click', event => {
  if (!chainSwitch.contains(event.target)) closeChainMenu();
});
