// 表头排序使用原始数值，先排全量再分页；取消排序即保留业务规则顺序。
function rpSortCycle(state,key){
 if(state.key!==key){state.key=key;state.direction='desc'}
 else if(state.direction==='desc')state.direction='asc';
 else {state.key='';state.direction=''}
}
function rpSortHeader(key,label,state,kind){
 if(['core','type','attribute','causes','mainSpu','season','productType'].includes(key))return label;
 const active=state.key===key,action=!active?'降序':state.direction==='desc'?'升序':'恢复榜单排序';
 const note=key==='fine'||key==='frozen'?'按金额排序；':key==='score'&&kind===1?'不同平台分组，同平台内按评分排序；':'';
 return '<button type="button" class="rp-sort-header" data-rp-sort="'+key+'" data-direction="'+(active?state.direction:'')+'" title="'+note+'点击'+action+'" aria-label="'+esc(label)+'：'+note+action+'">'+esc(label)+'<span class="rp-sort-arrows" aria-hidden="true"></span></button>';
}
function rpSortRows(rows,state,valueOf,groupOf=()=>null){
 if(!state.key)return rows;
 const groups=new Map();
 return rows.map((row,index)=>{
  const group=groupOf(row);if(!groups.has(group))groups.set(group,groups.size);
  return {row,index,value:valueOf(row,state.key),group:groups.get(group)};
 }).sort((a,b)=>{
  const av=Number.isFinite(a.value),bv=Number.isFinite(b.value);
  if(av!==bv)return av?-1:1; // 缺失与不适用始终置后，不能视为0。
  if(!av)return a.index-b.index;
  return a.group-b.group||(state.direction==='asc'?a.value-b.value:b.value-a.value)||a.index-b.index;
 }).map(entry=>entry.row);
}
function rpGroupSortKeys(k){return ['count','warehouse','factory','undelivered','totalUnits',k===3?'goodsValueCents':'staleValueCents','staleUnits']}
function rpApplySortAria(host,state){
 for(const button of host.querySelectorAll('[data-rp-sort]'))button.closest('th').setAttribute('aria-sort',state.key!==button.dataset.rpSort?'none':state.direction==='asc'?'ascending':'descending');
}
// 保留原表头与事件：纵向跟随抽屉，横向仍由表格容器和固定列管理。
let rpStickyHeaderDispose=null;
function rpStickListHeader(host){
 rpStickyHeaderDispose?.();
 const body=$('#dialogbody'),overlay=$('#overlay'),head=host.querySelector('thead'),table=head?.closest('table');
 if(!head)return;
 let frame=0,offset=0,disposed=false;
 function update(){
  frame=0;
  if(!host.isConnected||overlay.hidden){dispose();return}
  const naturalTop=head.getBoundingClientRect().top-offset;
  const boundary=body.getBoundingClientRect().top+body.clientTop;
  const limit=Math.max(0,table.getBoundingClientRect().bottom-naturalTop-head.offsetHeight);
  offset=Math.min(limit,Math.max(0,boundary-naturalTop));
  head.style.transform=`translateY(${offset}px)`;
 }
 function schedule(){if(!frame&&!disposed)frame=requestAnimationFrame(update)}
 function dispose(){
  if(disposed)return;
  disposed=true;cancelAnimationFrame(frame);
  body.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule);
  resize.disconnect();lifecycle.disconnect();head.style.removeProperty('transform');
  if(rpStickyHeaderDispose===dispose)rpStickyHeaderDispose=null;
 }
 const resize=new ResizeObserver(schedule);
 resize.observe(body);resize.observe(host);resize.observe(head);
 const lifecycle=new MutationObserver(()=>{if(!host.isConnected||overlay.hidden)dispose();else schedule()});
 lifecycle.observe(body,{childList:true});
 lifecycle.observe(overlay,{attributes:true,attributeFilter:['hidden']});
 body.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);
 rpStickyHeaderDispose=dispose;schedule();
}

