function ppSampleLedger(source){
 const index=Math.abs(Number(source.id)||0),templates=Object.values(ppRiskExamples).flat();
 const examples=ppRiskExamples[source.sourceKey]||[templates[index%templates.length],templates[(index+3)%templates.length]];
 const records=examples.map(([department,light,category,description,rootCause,action,owner,deadline,taskNames],i)=>({
  id:`demo-${source.sourceKey}-${i+1}`,department,light:ppRiskExamples[source.sourceKey]?light:source.status,category,description,rootCause,action,owner,deadline,
  taskNames:[...taskNames],status:'待整改',recordedAt:/^\d{4}-\d{2}-\d{2}$/.test(source.started)&&source.started>'2026-10-01'?source.started:'2026-10-01',sample:true
 }));
 return ppSampleRiskEvents(source,records);
}

// 缺失报价仅用于演示；不覆盖真实数组或已导入的金额。
function ppSampleQuotes(source){
 const sampleFields=[],result={...source},base=Number.isFinite(source.cost)?source.cost:180+(Math.abs(Number(source.id)||0)%8)*30;
 if(source.targetCosts==null&&!Number.isFinite(source.cost)){result.targetCosts=[{version:'基础款',factory:base}];sampleFields.push('targetCosts')}
 if(source.finalQuotes==null){result.finalQuotes=[{version:'基础款',factory:base+12,channel:Math.round((base+12)*1.12),company:Math.round((base+12)*1.2)}];sampleFields.push('finalQuotes')}
 if(source.targetPrices==null&&!Number.isFinite(source.price)){result.targetPrices=[{version:'基础款',price:Math.round(base*2.2/100)*100+99}];sampleFields.push('targetPrices')}
 return {...result,sampleFields};
}
// 项目全景只适配明确来源字段；日报、项目经理不能代替风险台账及责任链主。
const ppStages={
 '自研开发':['立项筹备期','研发评审期','产品研发期','打样验证期','开模试产期','首批上线期'],
 '自选开发':['产品寻源期','整改测试期','首批上线期'],
 '品质整改':['整改立项','样机制作与测试','改善品生产期','销售与数据回收','改善大货退货率监控数据'],
 '产品迭代':['提需规划期','迭代开发期','首批上线期'],
 '研发创新':['第一阶段：创新需求收集与技术研判','第二阶段：技术可行性评审','第三阶段：创新难点预研','第四阶段：功能手板评审&测试','第五阶段：创新模块评审','第六阶段：专利申请']
};
const ppProjectStates=['进行中','已完成','已暂停/取消','未开始'];
const ppDepartments=['产品部','研发部','采购部','品质部'];
const ppState={category:[],type:[],projectState:['进行中'],brand:[],light:[],stage:[],department:[],owner:'',query:'',plan:null,started:null,page:1,distribution:'type',departmentDistribution:'type',riskDepartment:'全部',link:null,sort:{key:'revisedPlan',direction:'asc'}};
const ppValues=value=>[...new Set((Array.isArray(value)?value:[value]).filter(v=>v!=null&&v!==''&&v!=='—'))];
// 高危红灯是红灯子集；保留原灯色，避免分布和红灯率重复统计。
const ppHighRisk=p=>p.status==='红灯'&&p.delay>15;
const ppMatchesLight=(p,values)=>!values.length||values.some(value=>value==='高危红灯'?ppHighRisk(p):p.status===value);
const ppDate=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')?value:null;
function ppAdapt(source,cutoff){
 source=ppSampleQuotes(source);
 const type=({'自研':'自研开发','自选':'自选开发','创新研发':'研发创新','创新项目':'研发创新'})[source.type]||source.type;
 const ledger=(Array.isArray(source.riskLedger)?source.riskLedger:ppSampleLedger(source)).filter(r=>!r.recordedAt||r.recordedAt.slice(0,10)<=cutoff).map(r=>ppRiskFields({...r,...(ppDate(r.closedAt)&&r.closedAt>cutoff?{status:'待整改'}:{}),taskNames:ppValues(r.taskNames).filter(name=>typeof name==='string')},cutoff));
 const stages=ppValues(String(source.stage||'').split(/[,，、]/)).filter(s=>(ppStages[type]||[]).includes(s));
 const actual=ppDate(source.actual)&&source.actual<=cutoff?source.actual:null,plan=ppDate(source.plan);
 const revised=ppDate(source.revisedPlan),revisedPlan=revised&&(!plan||revised>plan)?revised:null;
 const delay=plan&&(actual||source.projectState!=='已完成')?Math.max(0,Math.round((Date.parse(actual||cutoff)-Date.parse(plan))/86400000)):null;
 return {...source,type,category:pfCategory(source),stages,ledger,actual,delay,revisedPlan,
  departments:ppValues(ledger.filter(r=>r.status!=='已闭环').flatMap(r=>ppValues(r.department))).filter(d=>ppDepartments.includes(d)),
  responsible:ppValues(ledger.map(r=>r.owner))};
}
function ppRows(){const cutoff=bounds().cutoff;return [...new Map(projects().filter(p=>!ppDate(p.started)||p.started<=cutoff).map(p=>[p.id,ppAdapt(p,cutoff)])).values()]}
function ppScope(rows){return rows.filter(p=>pfIncludes(ppState.category,p.category)&&pfIncludes(ppState.type,p.type)&&pfIncludes(ppState.projectState,p.projectState))}
function ppFiltered(rows,s=ppState){
 const q=s.query.trim().toLowerCase(),owner=s.owner.trim().toLowerCase(),range=s.plan?nspLaunchRange(s.plan.mode,s.plan.year,s.plan.value):null;
 const startedRange=s.started?nspLaunchRange(s.started.mode,s.started.year,s.started.value):null;
 const includesAny=(filter,values)=>!filter.length||values.some(v=>filter.includes(v));
 return rows.filter(p=>pfIncludes(s.brand,p.brand)&&ppMatchesLight(p,s.light)&&(!s.stage.length||s.stage.some(path=>path.type===p.type&&p.stages.includes(path.stage)))&&includesAny(s.department,p.departments)&&(!owner||p.responsible.some(name=>String(name).toLowerCase().includes(owner)))
  &&(!q||String(p.name||'').toLowerCase().includes(q))
  &&(!range||(p.plan>=range.start&&p.plan<=range.end))&&(!startedRange||(ppDate(p.started)&&p.started>=startedRange.start&&p.started<=startedRange.end))&&ppLinked(p,s.link))
  .sort((a,b)=>ppCompareProjects(a,b,s.sort));
}
function ppLinked(p,link){if(!link)return true;if(link.kind==='light')return link.value==='红黄灯'?['红灯','黄灯'].includes(p.status):ppMatchesLight(p,[link.value]);if(link.kind==='departmentRisk')return p[link.type]===link.value&&ppDepartmentRiskRecords(p,link.department).length>0;if(link.kind==='department')return p.departments.includes(link.value);return p[link.kind]===link.value&&['红灯','黄灯','绿灯'].includes(p.status)}
function ppCounts(rows){const red=rows.filter(p=>p.status==='红灯').length,yellow=rows.filter(p=>p.status==='黄灯').length,green=rows.filter(p=>p.status==='绿灯').length,total=rows.length;return {total,red,high:rows.filter(ppHighRisk).length,yellow,green,rate:n=>total?(n/total*100).toFixed(1)+'%':'—'}}
function ppDepartmentFacts(rows,department){
 const records=rows.flatMap(p=>p.ledger.filter(r=>r.status!=='已闭环'&&ppValues(r.department).includes(department)).map(r=>({project:p,risk:r})));
 const red=records.filter(x=>x.risk.light==='红灯'),yellow=records.filter(x=>x.risk.light==='黄灯');
 const redProjects=[...new Map(records.filter(x=>x.project.status==='红灯').map(x=>[x.project.id,x.project])).values()];
 return {records,red,yellow,redProjects};
}
function ppQuoteLines(p,key){
 const rows=p[key];
 if(Array.isArray(rows))return rows.flatMap(r=>{
  const version=r.version&&r.version!=='无'?r.version+'－':'';
  const fields=key==='targetPrices'?[['price','目标售价']]:[['factory','工厂供价'],['channel','渠道供价'],['company','公司供价']];
  return fields.filter(([k])=>typeof r[k]==='number'&&Number.isFinite(r[k])).map(([k,label])=>version+label+'：'+r[k].toFixed(2)+'元');
 });
 // 导入表仅有单一金额时如实展示；不补造版本、供价类型或最终报价。
 const legacy=key==='targetCosts'?p.cost:key==='targetPrices'?p.price:null;
 return typeof legacy==='number'&&Number.isFinite(legacy)?[legacy.toFixed(2)+'元']:[];
}

// 使用原始日期排序，缺失值在升降序中均置后；相同值按项目ID稳定排序。
function ppCompareProjects(a,b,sort=ppState.sort){
 const key=sort.key,value=p=>key==='delay'?p.delay:ppDate(p[key]),av=value(a),bv=value(b);
 if(av==null||bv==null)return av==null&&bv==null?a.id-b.id:av==null?1:-1;
 const compared=typeof av==='number'?av-bv:av.localeCompare(bv);
 return compared*(sort.direction==='asc'?1:-1)||a.id-b.id;
}
function ppHelp(label,text){return `<span class="metric-help" role="button" tabindex="0" aria-label="${esc(label)}说明" data-metric-rule="${esc(text)}"></span>`}
function ppLightValues(value){return value==='红黄灯'?['红灯','黄灯']:[value]}
function ppLightActive(value){const values=ppLightValues(value);return ppState.light.length===values.length&&values.every(light=>ppState.light.includes(light))}
function ppLink(kind,value,label,body='',type=''){
 const active=kind==='light'?ppLightActive(value):['type','category'].includes(kind)?ppState[kind].includes(value):ppState.link?.kind===kind&&ppState.link.value===value&&(!type||ppState.link.type===type);
 return `<button type="button" class="pp-link ${active?'selected':''}" data-pp-link="${kind}" data-value="${esc(value)}" data-type="${esc(type)}" aria-pressed="${active}">${label}${body}</button>`;
}
function ppOverview(rows){
 const ongoing=rows.filter(p=>p.projectState==='进行中'),c=ppCounts(ongoing),dimension=ppState.distribution;
 const keys=dimension==='type'?Object.keys(ppStages):pfCategories;
 const groups=keys.map(key=>({key,...ppCounts(ongoing.filter(p=>p[dimension]===key))}));
 // 红灯拆为高危与普通红灯，两部分互斥；每组总宽度保持100%。
 const share=(group,count)=>count/Math.max(1,group.red+group.yellow+group.green)*100;
 return `<article class="pp-card pp-rate"><div class="pp-card-head"><h3>红黄灯率 ${ppHelp('红黄灯率','红黄灯率＝（红灯项目数＋黄灯项目数）÷进行中项目数。')}</h3><span>${c.total}个进行中项目</span></div>
 ${ppLink('light','红黄灯',`<span>红黄灯合计</span><strong>${c.rate(c.red+c.yellow)}</strong><small>${c.red+c.yellow} 个项目</small>`)}
 <div class="pp-rate-split">${[['红灯',c.red,'red'],['黄灯',c.yellow,'orange']].map(([name,count,color])=>ppLink('light',name,`<span><i class="dot ${color}"></i>${name}率</span><b class="${color}">${c.rate(count)}</b><small>${count} 个项目</small>`)).join('')}</div></article>
 <article class="pp-card pp-distribution"><div class="pp-card-head"><h3>进行中项目红绿灯分布</h3><span><i class="dot pp-high-risk"></i>高危红灯 <i class="dot red"></i>红灯 <i class="dot orange"></i>黄灯 <i class="dot green"></i>绿灯</span></div>
 <div class="pp-tabs">${[['type','项目类型'],['category','类目']].map(([key,label])=>`<button type="button" data-pp-distribution="${key}" aria-pressed="${dimension===key}" class="${dimension===key?'active':''}">${label}</button>`).join('')}</div>
 <div class="pp-bars">${groups.map(g=>ppLink(dimension,g.key,`<span class="pp-bar-label">${esc(g.key)}</span>`,`<span class="pp-bar-line"><span class="pp-track"><i class="pp-high" style="width:${share(g,g.high)}%" title="高危红灯 ${g.high} 个"></i><i class="pp-red" style="width:${share(g,g.red-g.high)}%" title="红灯 ${g.red-g.high} 个"></i><i class="pp-yellow" style="width:${share(g,g.yellow)}%"></i><i class="pp-green" style="width:${share(g,g.green)}%"></i></span><span><b class="pp-high-risk" title="高危红灯">${g.high}</b> / <b class="red" title="红灯">${g.red-g.high}</b> / <b class="orange">${g.yellow}</b> / <b class="green">${g.green}</b></span></span>`)).join('')}</div></article>
 ${ppDepartmentRiskChart(rows)}${ppRiskEventChart()}`;
}
const ppHeaders=['产品名称','项目红绿灯','项目状态','计划上线日期','实际上线日期','延期天数','卡点阶段','责任部门','根因分析','责任链主','目标成本','最终产品报价','目标售价','立项日期','类目','品牌','操作'];
function ppSelect(key,label,values,selected=ppState[key]){
 const allLabel={category:'全部类目',type:'全部项目类型'}[key]||'全部';
 return `<label class="unified-filter-field"><span>${label}</span><select id="pp-filter-${key}" data-pp-filter="${key}" aria-label="项目${label}" multiple data-pf-multiple data-pf-label="${label}"><option value="all" ${!selected.length?'selected':''}>${allLabel}</option>${values.map(value=>`<option value="${esc(value)}" ${selected.includes(value)?'selected':''}>${esc(value)}</option>`).join('')}</select></label>`;
}
function ppDateFilter(key,label,hint=''){
 return `<div class="pp-plan"><button type="button" class="pp-plan-trigger" aria-label="${label}筛选" aria-haspopup="dialog" aria-expanded="false" aria-controls="pp-${key}-panel"><span>${label}${hint?ppHelp(label,hint):''}</span><span>${esc(nspLaunchLabel(ppState[key]))}</span><i>⌄</i></button><button type="button" data-pp-plan-clear="${key}" aria-label="清空${label}" ${ppState[key]?'':'hidden'}>×</button><div id="pp-${key}-panel" class="nsp-launch-panel nsp-period-panel" popover="auto" role="dialog" aria-label="选择项目${label}期间"></div></div>`;
}
function ppToolbar(rows){
 return `<div class="pp-filter-row"><label class="ui-search-field"><input type="search" data-pp-search aria-label="项目名称搜索" placeholder="搜索项目名称" value="${esc(ppState.query)}"></label>
 <label class="ui-search-field"><input type="search" data-pp-owner-search aria-label="责任链主搜索" placeholder="搜索责任链主" value="${esc(ppState.owner)}"></label>
 ${ppDateFilter('plan','计划上线日期','项目的计划量产/完成日期')}${ppDateFilter('started','立项日期')}
 ${ppSelect('brand','品牌',ppValues(rows.map(p=>p.brand)))}${ppSelect('light','项目红绿灯',['高危红灯','红灯','黄灯','绿灯'])}${ppSelect('projectState','项目状态',ppProjectStates)}${ppSelect('department','责任部门',ppDepartments)}${ppStageCascader()}
 </div><button type="button" class="link pp-reset" data-pp-reset>重置</button>`;
}
// 多个任务保留在同一风险单内；仅展示名称，不展开成重复风险记录。
function ppTaskNames(r){return r.taskNames?.length?r.taskNames.map(name=>`<span class="pp-task-name">${esc(name)}</span>`).join(''):'未填写'}
function ppLedger(p){
 const heads=['序号','任务名称','风险单红绿灯','问题类别','问题描述','根因分析','纠正措施','责任链主','整改期限'];
 return `<div class="pp-ledger" id="pp-ledger-${p.id}"><div class="pp-card-head"><h4>${esc(p.name)} · 风险台账</h4><span>共 ${p.ledger.length} 条</span></div><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${p.ledger.length?p.ledger.map((r,i)=>`<tr><td>${i+1}</td><td>${ppTaskNames(r)}</td><td>${ppTraffic(r.light)}</td>${[r.category,r.description,r.rootCause,r.action,r.owner,r.deadline].map(v=>`<td>${esc(v==null||v===''?'未填写':String(v))}</td>`).join('')}</tr>`).join(''):'<tr><td colspan="9" class="pp-empty-ledger">暂无风险台账，请在项目中维护。</td></tr>'}</tbody></table></div>`;
}
function ppPriceCell(p,key){const lines=ppQuoteLines(p,key);if(!lines.length)return '<span class="muted">—</span>';return `<span class="pp-wrap" title="${esc(lines.join('\n'))}">${lines.map(esc).join('<br>')}</span>`}
function ppProjectTraffic(p){return ppTraffic(ppHighRisk(p)?'高危红灯':p.status)}
function ppProductCell(p){return `<button type="button" class="pp-product" data-pp-project="${p.id}">${p.image?`<img src="${esc(p.image)}" alt="">`:'<span class="pp-placeholder">项</span>'}<span><b>${esc(p.name)}</b><small>${esc(p.type)}</small></span></button>`}
function ppPlanDates(p){return `<span class="pp-plan-dates"><span>${esc(p.plan||'—')}</span><small class="${p.revisedPlan?'orange':'muted'}">延期 ${esc(p.revisedPlan||'—')}</small></span>`}
function ppDelayText(p){return p.delay==null?'—':`<span class="${p.delay>15?'pp-high-risk pp-delay-high':p.delay>0?'orange':'muted'}">${p.delay}天</span>`}
function ppProjectRow(p){
 const reasons=ppValues(p.ledger.map(r=>r.rootCause||r.description)),stage=p.stages.length?p.stages.join('、'):'待核对';
 const cells=[
  ppProductCell(p),
  ppProjectTraffic(p),esc(p.projectState||'—'),ppPlanDates(p),p.actual||'<span class="muted">'+(p.projectState==='已完成'?'待补录':'—')+'</span>',
  ppDelayText(p),
  `<span class="pp-wrap" title="${esc(p.stage||'未提供阶段')}">${esc(stage)}</span>`,
  esc(p.departments.join('、')||'待补充'),
  `<button type="button" class="pp-root-cause ${p.ledger.length?'':'muted'}" data-pp-ledger="${p.id}" aria-expanded="false" aria-controls="pp-ledger-popover" aria-haspopup="dialog"><span class="pp-wrap">${esc(reasons.join('；')||'暂无风险台账')}</span><small>${p.ledger.length?'共 '+p.ledger.length+' 条 · ':''}查看更多</small></button>`,
  esc(p.responsible.join('、')||'—'),ppPriceCell(p,'targetCosts'),ppPriceCell(p,'finalQuotes'),ppPriceCell(p,'targetPrices'),esc(p.started||'—'),esc(p.category||'—'),esc(p.brand||'—'),
  `<button type="button" class="link" data-pp-view="${p.id}">查看</button>`
 ];
 return `<tr data-pp-row="${p.id}">${cells.map((v,i)=>`<td data-label="${ppHeaders[i]}">${v}</td>`).join('')}</tr>`;
}
function ppTable(rows){
 ppHideLedger();
 const filtered=ppFiltered(rows),pages=Math.max(1,Math.ceil(filtered.length/10));ppState.page=Math.min(ppState.page,pages);
 const body=$('#pp-table-scroll'),scroll=body.scrollLeft;
 body.innerHTML=`<table class="pp-table"><colgroup>${[274,112,120,132,132,96,180,130,240,140,210,210,190,130,110,100,88].map(w=>`<col style="width:${w}px">`).join('')}</colgroup><thead><tr>${ppHeaders.map(ppTableHeader).join('')}</tr></thead><tbody>${filtered.length?filtered.slice((ppState.page-1)*10,ppState.page*10).map(ppProjectRow).join(''):'<tr><td colspan="17"><div class="empty">暂无匹配项目，请调整筛选条件。</div></td></tr>'}</tbody></table>`;
 body.scrollLeft=scroll;
 $('#pp-pages').innerHTML=listPager(filtered.length,ppState.page,10,{attr:'data-pp-page'});
 $('#pp-ai').innerHTML=ppAI(ppAnalysisRows());
 return filtered;
}

function ppSortButton(key,label){
 const active=ppState.sort.key===key,direction=active?ppState.sort.direction:'',next=direction==='asc'?'降序':'升序';
 return `<button type="button" class="rp-sort-header" data-pp-sort="${key}" data-direction="${direction}" aria-label="${label}：点击${next}">${label}<span class="rp-sort-arrows" aria-hidden="true"></span></button>`;
}
function ppTableHeader(label){
 const key={'计划上线日期':'plan','实际上线日期':'actual','延期天数':'delay','立项日期':'started'}[label];
 const active=ppState.sort.key===key||(key==='plan'&&ppState.sort.key==='revisedPlan');
 const sort=active?(ppState.sort.direction==='asc'?'ascending':'descending'):'none';
 return `<th${key?` aria-sort="${sort}"`:''}>${key==='plan'?`<div class="pp-plan-sort">${ppSortButton('plan',label)}${ppSortButton('revisedPlan','延期上线日期')}</div>`:key?ppSortButton(key,label):label}</th>`;
}
// 阶段按“项目类型 + 阶段”保存，避免不同类型的同名阶段互相命中。
let ppStageActiveType='';
function ppStageTypes(){return ppState.type.length?ppState.type:Object.keys(ppStages)}
function ppStageLabel(){return ppState.stage.map(p=>p.type+' / '+p.stage).join('、')||'全部'}
function ppStageOptions(type){
 return (ppStages[type]||[]).map(stage=>`<label class="pp-stage-option"><input type="checkbox" data-pp-stage-type="${esc(type)}" data-pp-stage-value="${esc(stage)}" aria-label="${esc(type+' / '+stage)}" ${ppState.stage.some(p=>p.type===type&&p.stage===stage)?'checked':''}><span>${esc(stage)}</span></label>`).join('');
}
function ppStageCascader(){
 const types=ppStageTypes();if(!types.includes(ppStageActiveType))ppStageActiveType=types[0];
 return `<details class="pp-stage-cascader"><summary aria-label="卡点阶段筛选"><span>卡点阶段</span><span class="pp-stage-value" title="${esc(ppStageLabel())}">${esc(ppStageLabel())}</span><i aria-hidden="true"></i></summary><div class="pp-stage-menu"><div class="pp-stage-types" role="group" aria-label="项目类型"><button type="button" data-pp-stage-clear>全部阶段</button>${types.map(type=>`<button type="button" data-pp-stage-branch="${esc(type)}" aria-pressed="${type===ppStageActiveType}"><span>${esc(type)}</span><span aria-hidden="true">›</span></button>`).join('')}</div><div class="pp-stage-options" role="group" aria-label="${esc(ppStageActiveType)}阶段">${ppStageOptions(ppStageActiveType)}</div></div></details>`;
}
function ppStageChooseBranch(button){
 const menu=button.closest('.pp-stage-cascader');ppStageActiveType=button.dataset.ppStageBranch;
 for(const branch of menu.querySelectorAll('[data-pp-stage-branch]'))branch.setAttribute('aria-pressed',String(branch===button));
 const options=menu.querySelector('.pp-stage-options');options.innerHTML=ppStageOptions(ppStageActiveType);options.setAttribute('aria-label',ppStageActiveType+'阶段');
}
function ppStageSync(menu){
 const value=menu.querySelector('.pp-stage-value');value.textContent=ppStageLabel();value.title=ppStageLabel();
 for(const box of menu.querySelectorAll('[data-pp-stage-value]'))box.checked=ppState.stage.some(p=>p.type===box.dataset.ppStageType&&p.stage===box.dataset.ppStageValue);
 ppState.page=1;ppRefreshTable();
}
